enum PatchSectionReadMode {
    Parse,
    PreserveRaw,
}

#[derive(Debug, Clone, Eq)]
struct FileContentState {
    len: u64,
    hash: String,
    identity: Option<FileIdentity>,
}

enum PreviousOutputSource {
    Live(PinnedOutputSource),
    Retained(PinnedOutputSource),
}

struct PinnedOutputSource {
    path: PathBuf,
    live_identity: Option<FileIdentity>,
}

impl PreviousOutputSource {
    fn path(&self) -> &Path {
        match self {
            Self::Live(source) => &source.path,
            Self::Retained(source) => &source.path,
        }
    }

    fn is_retained(&self) -> bool {
        matches!(self, Self::Retained(_))
    }

    fn is_live(&self) -> bool {
        matches!(self, Self::Live(_))
    }

    fn live_identity(&self) -> Option<&FileIdentity> {
        match self {
            Self::Live(source) => source.live_identity.as_ref(),
            Self::Retained(_) => None,
        }
    }
}

impl Drop for PinnedOutputSource {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.path);
    }
}

enum PreviousOutputSourceSelection {
    Available(PreviousOutputSource),
    OutputChanged,
    RetainedOutputChanged,
}

#[derive(Debug, Clone)]
struct FileIdentity {
    len: u64,
    dev: u64,
    ino: u64,
    modified_sec: i64,
    modified_nsec: i64,
    changed_sec: i64,
    changed_nsec: i64,
}

impl PartialEq for FileIdentity {
    fn eq(&self, other: &Self) -> bool {
        self.len == other.len
            && self.dev == other.dev
            && self.ino == other.ino
            && self.modified_sec == other.modified_sec
            && self.modified_nsec == other.modified_nsec
            && self.changed_sec == other.changed_sec
            && self.changed_nsec == other.changed_nsec
    }
}

impl Eq for FileIdentity {}

