const GENERATED_SECTION_INPUT_FILE: &str = "generated";
const GENERATED_SECTION_INDEX: u32 = 0;

struct ExpectedInputContent {
    path: PathBuf,
    len: u64,
    hash: String,
    identity: Option<FileIdentity>,
}

impl ExpectedInputContent {
    #[cfg(test)]
    fn from_bytes(path: &Path, bytes: &[u8]) -> Self {
        let content = FileContentState::from_bytes(bytes);
        Self::from_content(path, &content)
    }

    fn from_content(path: &Path, content: &FileContentState) -> Self {
        Self {
            path: path.to_owned(),
            len: content.len,
            hash: content.hash.clone(),
            identity: content.identity.clone(),
        }
    }

    fn matches_unchanged_atomic_replacement_input(&self) -> bool {
        if !is_atomic_replacement_rust_input(&self.path) {
            return false;
        }
        let Some(expected_identity) = self.identity.as_ref() else {
            return false;
        };
        FileIdentity::from_path(&self.path)
            .ok()
            .flatten()
            .as_ref()
            .is_some_and(|identity| identity == expected_identity)
    }

    fn matches_installed_atomic_replacement_snapshot(&self, state_dir: &Path) -> bool {
        if !is_atomic_replacement_rust_input(&self.path) {
            return false;
        }
        let Some(expected_identity) = self.identity.as_ref() else {
            return false;
        };
        let Ok(Some(current_identity)) = FileIdentity::from_path(&self.path) else {
            return false;
        };
        let Ok(Some(snapshot_identity)) =
            FileIdentity::from_path(&input_snapshot_path(state_dir, &self.path))
        else {
            return false;
        };
        expected_identity.matches_same_data_ignoring_change_time(&current_identity)
            && current_identity == snapshot_identity
    }
}

fn patch_output_range_rejection_reason(patches: &[SectionPatch]) -> Option<String> {
    let mut ranges = Vec::with_capacity(patches.len());
    for (index, patch) in patches.iter().enumerate() {
        let Ok(start) = usize::try_from(patch.output_offset) else {
            return Some("changed patch output range is out of bounds".to_owned());
        };
        let Some(end) = start.checked_add(patch.size as usize) else {
            return Some("changed patch output range overflow".to_owned());
        };
        ranges.push((start..end, index));
    }
    ranges.sort_by_key(|(range, _)| range.start);

    let mut previous = (0..0, 0);
    for (range, index) in ranges {
        if !range.is_empty() && range.start < previous.0.end {
            return Some(format!(
                "changed patch output ranges overlap: patch {} at {:#x}..{:#x} and patch {} at {:#x}..{:#x}",
                previous.1, previous.0.start, previous.0.end, index, range.start, range.end,
            ));
        }
        if range.end > previous.0.end {
            previous = (range, index);
        }
    }
    None
}

fn deduplicate_identical_plain_section_patches(patches: &mut Vec<SectionPatch>) {
    let mut unique = Vec::<SectionPatch>::with_capacity(patches.len());
    let mut plain_by_range = HashMap::<(u64, u64), usize>::new();
    for patch in patches.drain(..) {
        let is_plain = patch.deferred_relocation.is_none()
            && patch.preserve_ranges.is_empty()
            && patch.adjustments.is_empty();
        let key = (patch.output_offset, patch.size);
        if is_plain
            && plain_by_range
                .get(&key)
                .is_some_and(|index| unique[*index].data == patch.data)
        {
            continue;
        }
        if is_plain {
            plain_by_range.entry(key).or_insert(unique.len());
        }
        unique.push(patch);
    }
    *patches = unique;
}

fn merge_compatible_overlapping_section_patches(
    patches: &mut Vec<SectionPatch>,
    previous_output: Option<&[u8]>,
) -> std::result::Result<(), String> {
    loop {
        let mut merged = None;
        'pairs: for left_index in 0..patches.len() {
            let left = &patches[left_index];
            let left_start = left.output_offset;
            let Some(left_end) = left_start.checked_add(left.size) else {
                continue;
            };
            for right_index in left_index + 1..patches.len() {
                let right = &patches[right_index];
                let right_start = right.output_offset;
                let Some(right_end) = right_start.checked_add(right.size) else {
                    continue;
                };
                let overlap_start = left_start.max(right_start);
                let overlap_end = left_end.min(right_end);
                if overlap_start >= overlap_end {
                    continue;
                }
                let materialized_data = |patch: &SectionPatch| {
                    if let Some(previous_output) = previous_output {
                        return stored_output_patch(patch, previous_output)
                            .map(|patch| Some(patch.data));
                    }
                    let is_complete_plain_patch = patch.deferred_relocation.is_none()
                        && patch.preserve_ranges.is_empty()
                        && patch.adjustments.is_empty()
                        && usize::try_from(patch.size).is_ok_and(|size| size == patch.data.len());
                    Ok(is_complete_plain_patch.then(|| patch.data.clone()))
                };
                let Some(left_data) = materialized_data(left)? else {
                    continue;
                };
                let Some(right_data) = materialized_data(right)? else {
                    continue;
                };
                let (Ok(left_overlap_start), Ok(right_overlap_start), Ok(overlap_len)) = (
                    usize::try_from(overlap_start - left_start),
                    usize::try_from(overlap_start - right_start),
                    usize::try_from(overlap_end - overlap_start),
                ) else {
                    continue;
                };
                let left_overlap = &left_data[left_overlap_start..left_overlap_start + overlap_len];
                let right_overlap =
                    &right_data[right_overlap_start..right_overlap_start + overlap_len];
                if let Some(difference) = left_overlap
                    .iter()
                    .zip(right_overlap)
                    .position(|(left, right)| left != right)
                {
                    return Err(format!(
                        "materialized changed patches disagree at {:#x}: patch {left_index} writes {:#04x} and patch {right_index} writes {:#04x}",
                        overlap_start + difference as u64,
                        left_overlap[difference],
                        right_overlap[difference],
                    ));
                }
                let output_offset = left_start.min(right_start);
                let end = left_end.max(right_end);
                let (Ok(data_len), Ok(left_offset), Ok(right_offset)) = (
                    usize::try_from(end - output_offset),
                    usize::try_from(left_start - output_offset),
                    usize::try_from(right_start - output_offset),
                ) else {
                    continue;
                };
                let mut data = vec![0; data_len];
                data[left_offset..left_offset + left_data.len()].copy_from_slice(&left_data);
                data[right_offset..right_offset + right_data.len()].copy_from_slice(&right_data);
                merged = Some((
                    left_index,
                    right_index,
                    SectionPatch {
                        output_offset,
                        size: end - output_offset,
                        data,
                        deferred_relocation: None,
                        preserve_ranges: Vec::new(),
                        adjustments: Vec::new(),
                    },
                ));
                break 'pairs;
            }
        }
        let Some((left_index, right_index, patch)) = merged else {
            break;
        };
        patches[left_index] = patch;
        patches.remove(right_index);
    }
    Ok(())
}

fn compose_historical_plain_patches_with_current(
    historical: &mut Vec<SectionPatch>,
    current: &mut [SectionPatch],
) -> std::result::Result<(), String> {
    for historical_patch in historical {
        let historical_end = historical_patch
            .output_offset
            .checked_add(historical_patch.size)
            .ok_or_else(|| "historical patch range overflowed".to_owned())?;
        for current_patch in current.iter() {
            let current_end = current_patch
                .output_offset
                .checked_add(current_patch.size)
                .ok_or_else(|| "current patch range overflowed".to_owned())?;
            if historical_patch.output_offset < current_end
                && current_patch.output_offset < historical_end
            {
                return Err(
                    "historical Mach-O archive patch overlaps changed unwind without exact ownership"
                        .to_owned(),
                );
            }
        }
    }
    Ok(())
}

fn remove_plain_patches_shadowed_by_exact_current_ranges(
    patches: &mut Vec<SectionPatch>,
    current: &[SectionPatch],
) {
    patches.retain(|patch| {
        let is_plain = patch.deferred_relocation.is_none()
            && patch.preserve_ranges.is_empty()
            && patch.adjustments.is_empty();
        !is_plain
            || !current.iter().any(|current| {
                current.deferred_relocation.is_none()
                    && current.preserve_ranges.is_empty()
                    && current.adjustments.is_empty()
                    && current.output_offset == patch.output_offset
                    && current.size == patch.size
            })
    });
}

fn apply_addend_delta(data: &mut [u8], addend_delta: i64) -> std::result::Result<(), String> {
    match data.len() {
        4 => {
            let value = i64::from(i32::from_le_bytes(data.try_into().unwrap()));
            let adjusted = value
                .checked_add(addend_delta)
                .and_then(|value| i32::try_from(value).ok())
                .ok_or_else(|| "changed .eh_frame relocation adjustment overflowed".to_owned())?;
            data.copy_from_slice(&adjusted.to_le_bytes());
            Ok(())
        }
        8 => {
            let value = i64::from_le_bytes(data.try_into().unwrap());
            let adjusted = value
                .checked_add(addend_delta)
                .ok_or_else(|| "changed .eh_frame relocation adjustment overflowed".to_owned())?;
            data.copy_from_slice(&adjusted.to_le_bytes());
            Ok(())
        }
        _ => Err("unsupported .eh_frame relocation field size for incremental patch".to_owned()),
    }
}

fn materialize_deferred_relocation_patch(
    data: &mut [u8],
    previous_output: &[u8],
    deferred_relocation: DeferredRelocationPatch,
) -> std::result::Result<(), String> {
    if data.len() != previous_output.len() {
        return Err("deferred relocation patch output size changed".to_owned());
    }
    let RelocationSize::BitMasking(mask) = deferred_relocation.rel_info.size else {
        return Err("deferred relocation patch is not instruction-shaped".to_owned());
    };
    if mask.instruction.write_windows_size() != data.len() {
        return Err("deferred relocation patch output size changed".to_owned());
    }

    let mut replayed_previous_output = previous_output.to_vec();
    clear_deferred_relocation_bits(&mut replayed_previous_output, mask);
    deferred_relocation
        .rel_info
        .write_to_buffer(
            deferred_relocation.previous_written_value,
            &mut replayed_previous_output,
        )
        .map_err(|error| format!("failed to validate deferred relocation patch: {error:#}"))?;
    if replayed_previous_output != previous_output {
        return Err("deferred relocation patch encoding changed".to_owned());
    }

    data.copy_from_slice(previous_output);
    clear_deferred_relocation_bits(data, mask);
    deferred_relocation
        .rel_info
        .write_to_buffer(deferred_relocation.written_value, data)
        .map_err(|error| format!("failed to encode deferred relocation patch: {error:#}"))
}

fn clear_deferred_relocation_bits(data: &mut [u8], mask: linker_utils::elf::BitMask) {
    if data.len() != 4 {
        return;
    }
    let preserved_bits = mask.instruction.bit_mask(mask.range);
    for (byte, preserved) in data.iter_mut().zip(preserved_bits) {
        *byte &= preserved;
    }
}

struct DirectlyPatchedOutput {
    path: PathBuf,
    remove_path_on_drop: bool,
    published_path: Option<PathBuf>,
    published_identity: Option<FileIdentity>,
    standby_state_path: Option<PathBuf>,
    install_if_missing: bool,
}

impl DirectlyPatchedOutput {
    fn new(
        output: &Path,
        state_dir: &Path,
        should_replace: bool,
        retained_output_snapshot: Option<&Path>,
        live_output_identity: Option<&FileIdentity>,
    ) -> Option<Self> {
        if let Some(snapshot) = retained_output_snapshot {
            let output_exists = output.try_exists().ok()?;
            let published_identity = if output_exists {
                FileIdentity::from_path(output).ok().flatten()
            } else {
                None
            };
            match (live_output_identity, published_identity.as_ref()) {
                (Some(expected), Some(actual)) if expected == actual => {}
                (Some(_), None) | (None, None) if !output_exists => {}
                _ => return None,
            }
            let generation = install_unique_output_generation_copy(state_dir, snapshot).ok()?;
            let install_if_missing = !output_exists;
            return Some(Self {
                path: generation,
                remove_path_on_drop: true,
                published_path: Some(output.to_path_buf()),
                published_identity,
                standby_state_path: None,
                install_if_missing,
            });
        }
        if !output.try_exists().unwrap_or(false) {
            return None;
        }
        if !should_replace {
            return Some(Self {
                path: output.to_path_buf(),
                remove_path_on_drop: false,
                published_path: None,
                published_identity: None,
                standby_state_path: None,
                install_if_missing: false,
            });
        }

        let published_identity = FileIdentity::from_path(output).ok().flatten()?;
        let generation = directly_patched_output_standby_path(state_dir);
        let standby_state_path = directly_patched_output_standby_state_path(state_dir);
        let reused_standby =
            read_directly_patched_output_standby_ranges(output, &generation, &standby_state_path)
                .is_some_and(|ranges| {
                    verbose_timing_phase!(
                        "Catch up directly patched output generation",
                        range_count = ranges.len(),
                        byte_count = ranges.iter().map(std::ops::Range::len).sum::<usize>()
                    );
                    copy_output_ranges(output, &generation, &ranges).is_ok()
                });
        if !reused_standby {
            let _ = std::fs::remove_file(&generation);
            verbose_timing_phase!("Clone directly patched output generation");
            if !clone_snapshot_bytes(output, &generation) {
                return None;
            }
        }
        if !FileIdentity::from_path(output)
            .ok()
            .flatten()
            .as_ref()
            .is_some_and(|identity| {
                identity.matches_same_data_ignoring_change_time(&published_identity)
            })
        {
            let _ = std::fs::remove_file(&generation);
            return None;
        }
        Some(Self {
            path: generation,
            remove_path_on_drop: true,
            published_path: Some(output.to_path_buf()),
            published_identity: Some(published_identity),
            standby_state_path: Some(standby_state_path),
            install_if_missing: false,
        })
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn is_generation(&self) -> bool {
        self.published_path.is_some()
    }

    fn should_invalidate_code_signature_cache(&self) -> bool {
        !self.is_generation()
    }

    fn install(&mut self, ranges: &[std::ops::Range<usize>]) -> Result<Option<FileIdentity>> {
        self.install_with_exchange_hooks(ranges, || {}, || {})
    }

    fn install_with_exchange_hooks(
        &mut self,
        ranges: &[std::ops::Range<usize>],
        pre_exchange_hook: impl FnOnce(),
        post_exchange_hook: impl FnOnce(),
    ) -> Result<Option<FileIdentity>> {
        let Some(published_path) = self.published_path.as_ref() else {
            return Ok(None);
        };
        if self.install_if_missing {
            std::fs::hard_link(&self.path, published_path).with_context(|| {
                format!(
                    "Failed to install directly patched missing output `{}` without replacing an existing file",
                    published_path.display()
                )
            })?;
            let installed_identity = FileIdentity::from_path(published_path)?;
            std::fs::remove_file(&self.path).with_context(|| {
                format!(
                    "Failed to remove directly patched output generation `{}`",
                    self.path.display()
                )
            })?;
            self.published_path = None;
            return Ok(installed_identity);
        }
        if self.standby_state_path.is_none()
            && let Some(expected) = self.published_identity.as_ref()
        {
            if !published_path.try_exists().unwrap_or(true) {
                std::fs::hard_link(&self.path, published_path).with_context(|| {
                    format!(
                        "Failed to install directly patched output `{}` after the selected output disappeared",
                        published_path.display()
                    )
                })?;
                let installed_identity = FileIdentity::from_path(published_path)?;
                std::fs::remove_file(&self.path).with_context(|| {
                    format!(
                        "Failed to remove directly patched output generation `{}`",
                        self.path.display()
                    )
                })?;
                self.published_path = None;
                return Ok(installed_identity);
            }
            let actual = FileIdentity::from_path(published_path)?;
            if actual.as_ref() != Some(expected) {
                return Err(crate::error!(
                    "Refusing to replace changed incremental output `{}`",
                    published_path.display()
                ));
            }
            verbose_timing_phase!("Exchange directly patched output generation");
            let generation_identity = FileIdentity::from_path(&self.path)?;
            pre_exchange_hook();
            if FileIdentity::from_path(published_path)?.as_ref() != Some(expected) {
                return Err(crate::error!(
                    "Refusing to replace changed incremental output `{}`",
                    published_path.display()
                ));
            }
            if let Err(error) =
                exchange_directly_patched_output_generation(&self.path, published_path)
            {
                if !published_path.try_exists().unwrap_or(true) {
                    std::fs::hard_link(&self.path, published_path).with_context(|| {
                        format!(
                            "Failed to install directly patched output `{}` after the selected output disappeared",
                            published_path.display()
                        )
                    })?;
                    let installed_identity = FileIdentity::from_path(published_path)?;
                    std::fs::remove_file(&self.path)?;
                    self.published_path = None;
                    return Ok(installed_identity);
                }
                return Err(error);
            }
            self.remove_path_on_drop = false;
            post_exchange_hook();
            let predecessor_matches = FileIdentity::from_path(&self.path)?
                .as_ref()
                .is_some_and(|actual| actual.matches_same_data_ignoring_change_time(expected));
            let public_matches_generation = FileIdentity::from_path(published_path)?
                .as_ref()
                .zip(generation_identity.as_ref())
                .is_some_and(|(actual, generation)| {
                    actual.matches_same_data_ignoring_change_time(generation)
                });
            if !predecessor_matches || !public_matches_generation {
                return Err(crate::error!(
                    "Refusing to replace raced incremental output `{}`",
                    published_path.display()
                ));
            }
            std::fs::remove_file(&self.path)?;
            self.published_path = None;
            return Ok(generation_identity);
        }
        let generation_identity = FileIdentity::from_path(&self.path)?;
        verbose_timing_phase!("Install directly patched output generation");
        install_directly_patched_output_generation(&self.path, published_path)?;
        let standby_is_predecessor = self
            .published_identity
            .as_ref()
            .zip(FileIdentity::from_path(&self.path).ok().flatten().as_ref())
            .is_some_and(|(expected, actual)| {
                expected.matches_same_data_ignoring_change_time(actual)
            });
        let standby_state_installed = standby_is_predecessor
            && self
                .standby_state_path
                .as_ref()
                .is_some_and(|standby_state_path| {
                    write_directly_patched_output_standby_state(
                        standby_state_path,
                        published_path,
                        &self.path,
                        ranges,
                    )
                    .is_ok()
                });
        if !standby_state_installed {
            let _ = std::fs::remove_file(&self.path);
        }
        if !standby_state_installed
            && let Some(standby_state_path) = self.standby_state_path.as_ref()
        {
            let _ = std::fs::remove_file(standby_state_path);
        }
        self.published_path = None;
        Ok(generation_identity)
    }
}

impl Drop for DirectlyPatchedOutput {
    fn drop(&mut self) {
        if self.published_path.is_some() && self.remove_path_on_drop {
            let _ = std::fs::remove_file(&self.path);
        }
    }
}

fn publish_selected_output_source(
    state_dir: &Path,
    source: &Path,
    output: &Path,
    live_output_identity: Option<&FileIdentity>,
    source_was_live: bool,
) -> Result<bool> {
    if source_was_live && output.try_exists().unwrap_or(true) {
        if let Some(expected) = live_output_identity {
            return Ok(FileIdentity::from_path(output)?.as_ref() == Some(expected));
        }
        let source = FileContentState::from_path(source)?;
        let output = FileContentState::from_path(output)?;
        return Ok(content_state_matches_previous(&source, &output));
    }
    let Some(mut publication) =
        DirectlyPatchedOutput::new(output, state_dir, false, Some(source), live_output_identity)
    else {
        return Ok(false);
    };
    let restored_missing_output = publication.install_if_missing;
    publication.install(&[])?;
    if restored_missing_output {
        append_log(state_dir, "restored missing output from retained snapshot")?;
    }
    Ok(true)
}

fn directly_patched_output_standby_path(state_dir: &Path) -> PathBuf {
    state_dir.join(DIRECT_PATCH_STANDBY_FILE)
}

fn directly_patched_output_generation_path(state_dir: &Path, sequence: &AtomicUsize) -> PathBuf {
    let sequence = sequence.fetch_add(1, Ordering::Relaxed);
    state_dir.join(format!(
        "{DIRECT_PATCH_STANDBY_FILE}.{}.{sequence}",
        std::process::id()
    ))
}

fn install_unique_output_generation_copy(state_dir: &Path, source: &Path) -> Result<PathBuf> {
    install_unique_output_generation_copy_with_sequence(
        state_dir,
        source,
        &DIRECT_PATCH_GENERATION_SEQUENCE,
    )
}

fn install_unique_output_generation_copy_with_sequence(
    state_dir: &Path,
    source: &Path,
    sequence: &AtomicUsize,
) -> Result<PathBuf> {
    loop {
        let generation = directly_patched_output_generation_path(state_dir, sequence);
        if clone_snapshot_bytes(source, &generation) {
            return Ok(generation);
        }
        let mut target = match OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&generation)
        {
            Ok(target) => target,
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => return Err(error.into()),
        };
        let mut source_file = std::fs::File::open(source)?;
        if let Err(error) = std::io::copy(&mut source_file, &mut target) {
            drop(target);
            let _ = std::fs::remove_file(&generation);
            return Err(error.into());
        }
        let permissions = match std::fs::metadata(source) {
            Ok(metadata) => metadata.permissions(),
            Err(error) => {
                let _ = std::fs::remove_file(&generation);
                return Err(error.into());
            }
        };
        if let Err(error) = std::fs::set_permissions(&generation, permissions) {
            let _ = std::fs::remove_file(&generation);
            return Err(error.into());
        }
        return Ok(generation);
    }
}

fn directly_patched_output_standby_state_path(state_dir: &Path) -> PathBuf {
    state_dir.join(DIRECT_PATCH_STANDBY_STATE_FILE)
}

fn invalidate_directly_patched_output_standby(state_dir: &Path) -> Result {
    for path in [
        directly_patched_output_standby_state_path(state_dir),
        directly_patched_output_standby_path(state_dir),
    ] {
        match std::fs::remove_file(&path) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).with_context(|| {
                    format!(
                        "Failed to remove directly patched output standby `{}`",
                        path.display()
                    )
                });
            }
        }
    }
    Ok(())
}

fn read_directly_patched_output_standby_ranges(
    output: &Path,
    standby: &Path,
    state_path: &Path,
) -> Option<Vec<std::ops::Range<usize>>> {
    if std::fs::metadata(state_path).ok()?.len() > DIRECT_PATCH_STANDBY_STATE_MAX_LEN {
        return None;
    }
    let contents = std::fs::read_to_string(state_path).ok()?;
    let mut lines = contents.lines();
    if lines.next()? != DIRECT_PATCH_STANDBY_STATE_VERSION {
        return None;
    }
    let expected_output = FileIdentity::parse(lines.next()?).ok().flatten()?;
    let expected_standby = FileIdentity::parse(lines.next()?).ok().flatten()?;
    let output_identity = FileIdentity::from_path(output).ok().flatten()?;
    let standby_identity = FileIdentity::from_path(standby).ok().flatten()?;
    if expected_output != output_identity || expected_standby != standby_identity {
        return None;
    }

    let range_count = lines.next()?.parse().ok()?;
    if range_count > DIRECT_PATCH_STANDBY_MAX_RANGES {
        return None;
    }
    let mut ranges = Vec::with_capacity(range_count);
    for line in lines.by_ref().take(range_count) {
        let (start, end) = line.split_once(':')?;
        let start = start.parse().ok()?;
        let end = end.parse().ok()?;
        if start > end || end > output_identity.len.try_into().ok()? {
            return None;
        }
        ranges.push(start..end);
    }
    if ranges.len() != range_count || lines.next().is_some() {
        return None;
    }
    Some(merged_output_ranges(&ranges))
}

fn write_directly_patched_output_standby_state(
    state_path: &Path,
    output: &Path,
    standby: &Path,
    ranges: &[std::ops::Range<usize>],
) -> Result {
    let ranges = merged_output_ranges(ranges);
    if ranges.len() > DIRECT_PATCH_STANDBY_MAX_RANGES {
        let _ = std::fs::remove_file(state_path);
        let _ = std::fs::remove_file(standby);
        return Ok(());
    }
    let output_identity = FileIdentity::from_path(output)?
        .context("Missing directly patched output generation identity")?;
    let standby_identity = FileIdentity::from_path(standby)?
        .context("Missing directly patched output standby identity")?;
    let mut contents = format!(
        "{DIRECT_PATCH_STANDBY_STATE_VERSION}\n{}\n{}\n{}\n",
        output_identity.render(),
        standby_identity.render(),
        ranges.len(),
    );
    for range in ranges {
        writeln!(&mut contents, "{}:{}", range.start, range.end)?;
    }
    let tmp_path = append_suffix(state_path, ".tmp");
    std::fs::write(&tmp_path, contents).with_context(|| {
        format!(
            "Failed to write directly patched output standby state `{}`",
            tmp_path.display()
        )
    })?;
    std::fs::rename(&tmp_path, state_path).with_context(|| {
        format!(
            "Failed to install directly patched output standby state `{}`",
            state_path.display()
        )
    })
}

fn copy_output_ranges(
    source_path: &Path,
    target_path: &Path,
    ranges: &[std::ops::Range<usize>],
) -> Result {
    let mut source = std::fs::File::open(source_path).with_context(|| {
        format!(
            "Failed to open directly patched output source `{}`",
            source_path.display()
        )
    })?;
    let mut target = OpenOptions::new()
        .write(true)
        .open(target_path)
        .with_context(|| {
            format!(
                "Failed to open directly patched output standby `{}`",
                target_path.display()
            )
        })?;
    let mut buffer = [0; 64 * 1024];
    for range in merged_output_ranges(ranges) {
        source.seek(SeekFrom::Start(range.start as u64))?;
        target.seek(SeekFrom::Start(range.start as u64))?;
        let mut remaining = range.len();
        while remaining > 0 {
            let len = remaining.min(buffer.len());
            source.read_exact(&mut buffer[..len])?;
            target.write_all(&buffer[..len])?;
            remaining -= len;
        }
    }
    Ok(())
}

#[cfg(target_vendor = "apple")]
fn exchange_directly_patched_output_generation(generation: &Path, output: &Path) -> Result {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt as _;

    let generation_cstring = CString::new(generation.as_os_str().as_bytes())
        .context("Directly patched output generation path contains a NUL byte")?;
    let output_cstring = CString::new(output.as_os_str().as_bytes())
        .context("Directly patched output path contains a NUL byte")?;
    // SAFETY: Both paths are valid NUL-terminated strings for the duration of the call.
    if unsafe {
        libc::renamex_np(
            generation_cstring.as_ptr(),
            output_cstring.as_ptr(),
            libc::RENAME_SWAP,
        )
    } == 0
    {
        return Ok(());
    }
    Err(std::io::Error::last_os_error())
        .context("Failed to exchange directly patched output generation")
}

#[cfg(target_os = "linux")]
fn exchange_directly_patched_output_generation(generation: &Path, output: &Path) -> Result {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt as _;

    let generation = CString::new(generation.as_os_str().as_bytes())
        .context("Directly patched output generation path contains a NUL byte")?;
    let output = CString::new(output.as_os_str().as_bytes())
        .context("Directly patched output path contains a NUL byte")?;
    // SAFETY: Both paths are valid NUL-terminated strings for the duration of the call.
    if unsafe {
        libc::renameat2(
            libc::AT_FDCWD,
            generation.as_ptr(),
            libc::AT_FDCWD,
            output.as_ptr(),
            libc::RENAME_EXCHANGE,
        )
    } == 0
    {
        return Ok(());
    }
    Err(std::io::Error::last_os_error())
        .context("Failed to exchange directly patched output generation")
}

#[cfg(not(any(target_vendor = "apple", target_os = "linux")))]
fn exchange_directly_patched_output_generation(_generation: &Path, _output: &Path) -> Result {
    Err(crate::error!(
        "Atomic output generation exchange is unsupported on this platform"
    ))
}

#[cfg(target_vendor = "apple")]
fn install_directly_patched_output_generation(generation: &Path, output: &Path) -> Result {
    if exchange_directly_patched_output_generation(generation, output).is_ok() {
        return Ok(());
    }
    // Some Apple filesystems may support clones without swap publication. Retain the previous
    // atomic-replacement behavior there; the absent standby disables reuse on the next link.
    std::fs::rename(generation, output)
        .context("Failed to install directly patched output generation")
}

#[cfg(not(target_vendor = "apple"))]
fn install_directly_patched_output_generation(generation: &Path, output: &Path) -> Result {
    std::fs::rename(generation, output).with_context(|| {
        format!(
            "Failed to install directly patched output generation `{}` as `{}`",
            generation.display(),
            output.display()
        )
    })
}

fn flush_output_ranges(
    output: &memmap2::MmapMut,
    ranges: &[std::ops::Range<usize>],
    output_path: &Path,
) -> Result {
    for range in merged_output_ranges(ranges) {
        output
            .flush_range(range.start, range.end - range.start)
            .with_context(|| {
                format!(
                    "Failed to flush incrementally patched output `{}`",
                    output_path.display()
                )
            })?;
    }
    Ok(())
}

fn write_output_ranges(
    output: &[u8],
    ranges: &[std::ops::Range<usize>],
    file: &mut std::fs::File,
    output_path: &Path,
) -> Result {
    let ranges = merged_output_ranges(ranges);
    verbose_timing_phase!(
        "Write output generation ranges",
        range_count = ranges.len(),
        byte_count = ranges.iter().map(std::ops::Range::len).sum::<usize>()
    );
    for range in ranges {
        verbose_timing_phase!(
            "Write output generation range",
            start = range.start,
            byte_count = range.len()
        );
        let Some(output_range) = output.get(range.clone()) else {
            return Err(crate::error!(
                "Incrementally patched output range {range:?} is out of bounds for `{}`",
                output_path.display()
            ));
        };
        file.seek(SeekFrom::Start(range.start as u64))
            .with_context(|| {
                format!(
                    "Failed to seek incrementally patched output `{}`",
                    output_path.display()
                )
            })?;
        file.write_all(output_range).with_context(|| {
            format!(
                "Failed to write incrementally patched output `{}`",
                output_path.display()
            )
        })?;
    }
    Ok(())
}

fn merged_output_ranges(ranges: &[std::ops::Range<usize>]) -> Vec<std::ops::Range<usize>> {
    let mut ranges = ranges
        .iter()
        .filter(|range| !range.is_empty())
        .cloned()
        .collect::<Vec<_>>();
    ranges.sort_by_key(|range| range.start);

    let mut merged = Vec::<std::ops::Range<usize>>::new();
    for range in ranges {
        if let Some(previous) = merged.last_mut()
            && range.start <= previous.end
        {
            previous.end = previous.end.max(range.end);
            continue;
        }
        merged.push(range);
    }
    merged
}

#[derive(Debug, Clone)]
struct PatchSection {
    input: String,
    section_index: u32,
    section_name: Option<String>,
    input_size: u64,
    output_offset: u64,
    output_size: u64,
    data_hash: Option<String>,
    cstring_nul_boundaries_hash: Option<String>,
}

#[derive(Clone)]
struct MatchedPatchSection {
    previous: PatchSection,
    current: PatchSection,
}

struct MatchedPatchSections {
    sections: Vec<MatchedPatchSection>,
    changed_sections: Vec<PatchSection>,
}

struct ActivatedMachOTextSection {
    section: PatchSection,
    matched_section_index: Option<usize>,
}

struct MachOTextSectionActivation {
    text_sections: Vec<ActivatedMachOTextSection>,
    auxiliary_sections: Vec<PatchSection>,
    auxiliary_patches: Vec<SectionPatch>,
    appended_records: Vec<SectionRecord>,
    retired_record_keys: Vec<(String, u32)>,
    grew_existing_sections: bool,
    normalized_archive_identifiers: Vec<Vec<u8>>,
    remaining_reserved_ranges: Vec<ReservedRangeRecord>,
}

struct ChangedMachODefinitionActivation {
    state_updates: Vec<MachOArchiveActivationStateUpdate>,
    symbol_resolutions: Vec<MachOSymbolResolutionRecord>,
    output_patches: Vec<SectionPatch>,
    added_names: Vec<SharedText>,
    retired_names: Vec<SharedText>,
    recycled_names: Vec<SharedText>,
    remaining_reserved_ranges: Vec<ReservedRangeRecord>,
}

impl ChangedMachODefinitionActivation {
    fn owns_changed_unwind(&self) -> bool {
        self.state_updates.iter().any(|update| match update {
            MachOArchiveActivationStateUpdate::Replace(_, state)
            | MachOArchiveActivationStateUpdate::Add(state) => state.kind.owns_changed_unwind(),
        })
    }

    fn attach_changed_unwind_transaction(
        &mut self,
        activation: &ChangedMachOArchiveUnwindActivation,
        previous_output: &[u8],
    ) -> std::result::Result<(), String> {
        let patches = &activation.patches;
        if patches.is_empty() {
            return Err("changed Mach-O unwind transaction has no output patches".to_owned());
        }
        let Some(unwind_transaction) = activation.unwind_transaction.clone() else {
            return Err("changed Mach-O unwind transaction has no version state".to_owned());
        };
        let mut candidate = None;
        for update in &mut self.state_updates {
            let MachOArchiveActivationStateUpdate::Add(state) = update else {
                continue;
            };
            if state.kind != MachOArchiveActivationKind::ChangedDefinitions {
                continue;
            }
            if candidate.replace(state).is_some() {
                return Err(
                    "changed Mach-O unwind spans multiple new definition transactions".to_owned(),
                );
            }
        }
        let Some(state) = candidate else {
            return Err(
                "changed Mach-O unwind has no new definition ownership transaction".to_owned(),
            );
        };
        let forward_patches = patches
            .iter()
            .map(|patch| stored_output_patch(patch, previous_output))
            .collect::<std::result::Result<Vec<_>, _>>()?;
        let rollback_patches = forward_patches
            .iter()
            .map(|patch| {
                let start = usize::try_from(patch.output_offset)
                    .map_err(|_| "Mach-O unwind rollback offset is too large".to_owned())?;
                let end = start
                    .checked_add(patch.data.len())
                    .ok_or_else(|| "Mach-O unwind rollback range overflowed".to_owned())?;
                let data = previous_output
                    .get(start..end)
                    .ok_or_else(|| "Mach-O unwind rollback patch is outside output".to_owned())?;
                Ok(StoredOutputPatch {
                    output_offset: patch.output_offset,
                    data: data.to_vec(),
                })
            })
            .collect::<std::result::Result<Vec<_>, String>>()?;
        state.kind = MachOArchiveActivationKind::ChangedDefinitionsWithUnwind;
        state.forward_patches.extend(forward_patches);
        state.rollback_patches.extend(rollback_patches);
        state.unwind_transaction = Some(unwind_transaction);
        Ok(())
    }

    fn changed_unwind_ownership_state(
        &self,
    ) -> std::result::Result<Option<&MachOArchiveActivationState>, String> {
        let mut candidate = None;
        for update in &self.state_updates {
            let state = match update {
                MachOArchiveActivationStateUpdate::Replace(_, state)
                | MachOArchiveActivationStateUpdate::Add(state) => state,
            };
            if state.unwind_transaction.is_none() && !state.kind.owns_changed_unwind() {
                continue;
            }
            if candidate.replace(state).is_some() {
                return Err("changed Mach-O unwind ownership is ambiguous".to_owned());
            }
        }
        Ok(candidate)
    }
}

fn reuse_historical_macho_archive_unwind_transaction(
    state: &MachOArchiveActivationState,
    changed: &ChangedMachOArchiveUnwindMembers,
    previous_output: &[u8],
    reserved_ranges: &[ReservedRangeRecord],
) -> std::result::Result<Vec<ReservedRangeRecord>, String> {
    let transaction = state
        .unwind_transaction
        .as_ref()
        .ok_or_else(|| "historical Mach-O unwind ownership has no version state".to_owned())?;
    if !macho_archive_transaction_patches_match(state) {
        return Err("historical Mach-O unwind transaction is incomplete".to_owned());
    }
    let (source, target, source_patches, target_patches) = if state.active {
        (
            &transaction.rollback,
            &transaction.forward,
            &state.rollback_patches,
            &state.forward_patches,
        )
    } else {
        (
            &transaction.forward,
            &transaction.rollback,
            &state.forward_patches,
            &state.rollback_patches,
        )
    };
    if changed.previous_common_members != source.common_members
        || changed.current_common_members != target.common_members
    {
        return Err("historical Mach-O unwind transaction direction changed".to_owned());
    }
    for patch in source_patches {
        let start = usize::try_from(patch.output_offset)
            .map_err(|_| "historical Mach-O unwind source offset is too large".to_owned())?;
        let end = start
            .checked_add(patch.data.len())
            .ok_or_else(|| "historical Mach-O unwind source range overflowed".to_owned())?;
        if previous_output.get(start..end) != Some(patch.data.as_slice()) {
            return Err("historical Mach-O unwind source differs from output".to_owned());
        }
    }
    scratch_apply_macho_archive_unwind_transition(previous_output, target_patches, source, target)?;
    transition_macho_eh_frame_reserve(
        reserved_ranges,
        source.eh_frame_reserve,
        target.eh_frame_reserve,
    )
}

fn validate_historical_macho_archive_unwind_planning(
    historical_unwind_state: Option<&MachOArchiveActivationState>,
    can_plan_changed_unwind: bool,
) -> std::result::Result<(), String> {
    if historical_unwind_state.is_some() && !can_plan_changed_unwind {
        return Err(
            "historical Mach-O unwind ownership cannot compose with a fresh archive activation"
                .to_owned(),
        );
    }
    Ok(())
}

enum MachOArchiveActivationStateUpdate {
    Replace(usize, MachOArchiveActivationState),
    Add(MachOArchiveActivationState),
}

