    #[test]
    fn retired_macho_symbol_proof_ignores_only_the_exact_definition() {
        const DATA_SECTION_HEADER: usize = 32 + 72 + 80;
        const SYMTAB_COMMAND: usize = 32 + 72 + 2 * 80;

        let previous = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let previous_text = test_macho_section_range(&previous, "__text");
        let text_entry = macho_symbol_value_field_range(&previous, object::SymbolIndex(0))
            .unwrap()
            .start
            - 8;
        let data_entry = macho_symbol_value_field_range(&previous, object::SymbolIndex(1))
            .unwrap()
            .start
            - 8;
        let ignored_text = HashSet::from([b"_text".to_vec()]);
        let ignored_data = HashSet::from([b"_data".to_vec()]);
        let fingerprint = |bytes: &[u8], ignored: &HashSet<Vec<u8>>| {
            macho_object_semantic_patch_fingerprint(
                bytes,
                0,
                &[test_macho_section_range(bytes, "__text")],
                &HashSet::new(),
                &HashSet::new(),
                ignored,
                false,
                true,
            )
            .unwrap()
        };

        let mut retired = previous.clone();
        retired[text_entry + 4] = object::macho::N_STAB;
        assert_eq!(
            fingerprint(&previous, &ignored_text),
            fingerprint(&retired, &ignored_text)
        );
        assert_ne!(
            fingerprint(&previous, &HashSet::new()),
            fingerprint(&retired, &HashSet::new())
        );
        assert_ne!(
            fingerprint(&previous, &ignored_data),
            fingerprint(&retired, &ignored_data)
        );

        let mut changed_flags = retired.clone();
        changed_flags[data_entry + 6..data_entry + 8].copy_from_slice(&1_u16.to_le_bytes());
        assert_ne!(
            fingerprint(&previous, &ignored_text),
            fingerprint(&changed_flags, &ignored_text)
        );

        let mut changed_section = retired.clone();
        changed_section[data_entry + 5] = 1;
        assert_ne!(
            fingerprint(&previous, &ignored_text),
            fingerprint(&changed_section, &ignored_text)
        );

        let mut added_relocation = retired.clone();
        let symoff = read_u32_le(&added_relocation[SYMTAB_COMMAND + 8..SYMTAB_COMMAND + 12])
            .unwrap() as usize;
        let stroff = read_u32_le(&added_relocation[SYMTAB_COMMAND + 16..SYMTAB_COMMAND + 20])
            .unwrap() as usize;
        added_relocation.splice(
            symoff..symoff,
            [
                0_u32.to_le_bytes(),
                ((2_u32 << 25) | (1_u32 << 27)).to_le_bytes(),
            ]
            .concat(),
        );
        added_relocation[DATA_SECTION_HEADER + 56..DATA_SECTION_HEADER + 60]
            .copy_from_slice(&(symoff as u32).to_le_bytes());
        added_relocation[DATA_SECTION_HEADER + 60..DATA_SECTION_HEADER + 64]
            .copy_from_slice(&1_u32.to_le_bytes());
        added_relocation[SYMTAB_COMMAND + 8..SYMTAB_COMMAND + 12]
            .copy_from_slice(&((symoff + 8) as u32).to_le_bytes());
        added_relocation[SYMTAB_COMMAND + 16..SYMTAB_COMMAND + 20]
            .copy_from_slice(&((stroff + 8) as u32).to_le_bytes());
        assert_ne!(
            macho_object_semantic_patch_fingerprint(
                &previous,
                0,
                &[previous_text],
                &HashSet::new(),
                &HashSet::new(),
                &ignored_text,
                false,
                true,
            ),
            macho_object_semantic_patch_fingerprint(
                &added_relocation,
                0,
                &[test_macho_section_range(&added_relocation, "__text")],
                &HashSet::new(),
                &HashSet::new(),
                &ignored_text,
                false,
                true,
            )
        );
    }

    #[test]
    fn macho_member_retirement_ignores_only_masked_local_definitions() {
        let object = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let text_entry = macho_symbol_value_field_range(&object, object::SymbolIndex(0))
            .unwrap()
            .start
            - 8;
        let fingerprint = |bytes: &[u8]| {
            macho_object_semantic_patch_fingerprint(
                bytes,
                0,
                &[test_macho_section_range(bytes, "__text")],
                &HashSet::new(),
                &HashSet::new(),
                &HashSet::new(),
                true,
                true,
            )
            .unwrap()
        };

        let mut previous_local = object.clone();
        previous_local[text_entry + 4] &= !object::macho::N_EXT;
        let mut retired_local = previous_local.clone();
        retired_local[text_entry + 4] |= object::macho::N_STAB;
        assert_eq!(fingerprint(&previous_local), fingerprint(&retired_local));

        let mut retired_external = object.clone();
        retired_external[text_entry + 4] |= object::macho::N_STAB;
        assert_ne!(fingerprint(&object), fingerprint(&retired_external));
    }

    #[test]
    fn masked_macho_alias_fingerprint_ignores_only_strippable_local_labels() {
        let fingerprint = |bytes: &[u8]| {
            let ranges = [
                test_macho_section_range(bytes, "__text"),
                test_macho_section_range(bytes, "__data"),
            ];
            macho_object_semantic_patch_fingerprint_with_retargets(
                bytes,
                0,
                &ranges,
                &HashSet::new(),
                &HashSet::new(),
                &HashSet::new(),
                true,
                true,
                true,
                &[],
                &[],
            )
            .unwrap()
            .0
        };
        let previous = test_macho_object(&[0; 4], &[1; 4], 0);
        let current = test_macho_object(&[0; 8], &[1; 4], 1);
        let previous_ltmp = add_test_macho_local_alias(previous.clone(), b"ltmp3", 2, 4);
        let current_ltmp = add_test_macho_local_alias(current.clone(), b"ltmp3", 2, 9);
        assert_eq!(fingerprint(&previous_ltmp), fingerprint(&current_ltmp));

        let previous_alias = add_test_macho_local_alias(previous.clone(), b"alias", 2, 4);
        let current_alias = add_test_macho_local_alias(current.clone(), b"alias", 2, 9);
        assert_ne!(fingerprint(&previous_alias), fingerprint(&current_alias));

        for n_desc in [
            object::macho::N_WEAK_DEF,
            object::macho::N_NO_DEAD_STRIP,
            object::macho::N_ALT_ENTRY,
        ] {
            let mut previous_hostile = add_test_macho_local_alias(previous.clone(), b"ltmp3", 2, 4);
            let previous_entry = test_macho_symbol_entry_offset(&previous_hostile, b"ltmp3");
            previous_hostile[previous_entry + 6..previous_entry + 8]
                .copy_from_slice(&n_desc.to_le_bytes());
            let mut current_hostile = add_test_macho_local_alias(current.clone(), b"ltmp3", 2, 9);
            let current_entry = test_macho_symbol_entry_offset(&current_hostile, b"ltmp3");
            current_hostile[current_entry + 6..current_entry + 8]
                .copy_from_slice(&n_desc.to_le_bytes());
            assert_ne!(
                fingerprint(&previous_hostile),
                fingerprint(&current_hostile)
            );
        }
    }

    #[test]
    fn masked_macho_alias_fingerprint_rejects_strippable_validated_target() {
        let fingerprint = |bytes: &[u8], target_name: &[u8]| {
            let file = object::File::parse(bytes).unwrap();
            let section = file.section_by_name("__text").unwrap();
            let target = file
                .symbols()
                .find(|symbol| symbol.name_bytes().ok() == Some(target_name))
                .unwrap();
            let site = ValidatedMachOLocalRelocationSite {
                archive_identifier: Vec::new(),
                section_index: section.index().0,
                relocation_offset: 0,
                normalize_relocation_offset: false,
                target_symbol_index: target.index().0,
                hash_target_symbol: false,
                hash_unmasked_target_offset: false,
                exact_symbol_indices: Vec::new(),
            };
            let ranges = [
                test_macho_section_range(bytes, "__text"),
                test_macho_section_range(bytes, "__const"),
            ];
            macho_object_semantic_patch_fingerprint_with_retargets(
                bytes,
                0,
                &ranges,
                &HashSet::new(),
                &HashSet::new(),
                &HashSet::new(),
                true,
                true,
                true,
                &[&site],
                &[],
            )
        };
        let previous_unaliased =
            test_macho_local_text_target_object_with_alias(b"ltmp0", b"A-target", 0, None);
        let current_unaliased =
            test_macho_local_text_target_object_with_alias(b"ltmp1", b"B-target", 4, None);
        let previous =
            test_macho_local_text_target_object_with_alias(b"ltmp0", b"A-target", 0, Some(0));
        let current =
            test_macho_local_text_target_object_with_alias(b"ltmp1", b"B-target", 4, Some(4));

        assert!(fingerprint(&previous_unaliased, b"ltmp0").is_some());
        assert!(fingerprint(&current_unaliased, b"ltmp1").is_some());
        assert!(fingerprint(&previous, b"ltmp0").is_none());
        assert!(fingerprint(&current, b"ltmp1").is_none());
    }

    #[test]
    fn macho_local_retarget_fingerprint_binds_unmasked_target_offset_and_bytes() {
        let fingerprint =
            |bytes: &[u8], target_name: &[u8; 5], masked_const_bytes: Option<usize>| {
                let file = object::File::parse(bytes).unwrap();
                let source = file.section_by_name("__text").unwrap();
                let target = file
                    .symbols()
                    .find(|symbol| symbol.name_bytes().ok() == Some(target_name))
                    .unwrap();
                let site = ValidatedMachOLocalRelocationSite {
                    archive_identifier: Vec::new(),
                    section_index: source.index().0,
                    relocation_offset: 0,
                    normalize_relocation_offset: false,
                    target_symbol_index: target.index().0,
                    hash_target_symbol: false,
                    hash_unmasked_target_offset: true,
                    exact_symbol_indices: Vec::new(),
                };
                let mut ranges = vec![test_macho_section_range(bytes, "__text")];
                if let Some(masked_const_bytes) = masked_const_bytes {
                    let const_range = test_macho_section_range(bytes, "__const");
                    ranges.push(
                        const_range.start
                            ..const_range
                                .start
                                .saturating_add(masked_const_bytes)
                                .min(const_range.end),
                    );
                }
                macho_object_semantic_patch_fingerprint_with_retargets(
                    bytes,
                    0,
                    &ranges,
                    &HashSet::new(),
                    &HashSet::new(),
                    &HashSet::new(),
                    true,
                    true,
                    true,
                    &[&site],
                    &[],
                )
                .map(|(fingerprint, _, _)| fingerprint)
            };
        let previous =
            test_macho_local_text_target_object_with_alias(b"l_a.1", b"constant", 0, None);
        let renamed =
            test_macho_local_text_target_object_with_alias(b"l_b.2", b"constant", 0, None);
        let moved = test_macho_local_text_target_object_with_alias(b"l_b.2", b"constant", 4, None);
        let changed =
            test_macho_local_text_target_object_with_alias(b"l_b.2", b"changed!", 0, None);

        let previous_fingerprint = fingerprint(&previous, b"l_a.1", None).unwrap();
        assert_eq!(
            previous_fingerprint,
            fingerprint(&renamed, b"l_b.2", None).unwrap(),
        );
        assert_ne!(
            previous_fingerprint,
            fingerprint(&moved, b"l_b.2", None).unwrap(),
        );
        assert_ne!(
            previous_fingerprint,
            fingerprint(&changed, b"l_b.2", None).unwrap(),
        );
        assert!(fingerprint(&previous, b"l_a.1", Some(1)).is_none());
        assert!(fingerprint(&previous, b"l_a.1", Some(usize::MAX)).is_none());
    }

    #[test]
    fn macho_member_retirement_ignores_only_fully_masked_unwind_sections() {
        let object = test_observed_049_macho_unwind_object(false);
        let file = object::File::parse(object.as_slice()).unwrap();
        let eh_frame = file.section_by_name("__eh_frame").unwrap();
        let (offset, size) = eh_frame.file_range().unwrap();
        let range = offset as usize..(offset + size) as usize;

        assert_eq!(
            fully_masked_macho_unwind_sections(&file, 0, std::slice::from_ref(&range)).unwrap(),
            HashSet::from([eh_frame.index()]),
        );
        assert!(
            fully_masked_macho_unwind_sections(&file, 0, &[range.start..range.end - 1])
                .unwrap()
                .is_empty(),
        );
    }

    #[test]
    fn retired_macho_symbol_proof_allows_shifted_survivors_and_unmasked_members() {
        let mut previous = test_macho_object(&[0; 8], &[1; 4], 0);
        let previous_survivor =
            macho_symbol_value_field_range(&previous, object::SymbolIndex(1)).unwrap();
        previous[previous_survivor.start - 3] = 1;
        previous[previous_survivor].copy_from_slice(&4_u64.to_le_bytes());

        let mut current = test_macho_object(&[0; 4], &[1; 4], 0);
        let retired = macho_symbol_value_field_range(&current, object::SymbolIndex(0))
            .unwrap()
            .start
            - 8;
        current[retired + 4] = object::macho::N_STAB;
        let current_survivor =
            macho_symbol_value_field_range(&current, object::SymbolIndex(1)).unwrap();
        current[current_survivor.start - 3] = 1;
        current[current_survivor].copy_from_slice(&0_u64.to_le_bytes());

        let untouched = test_macho_object(&[2; 4], &[3; 4], 0);
        let archive = |changed: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, bytes) in [
                (b"changed.o".as_slice(), changed),
                (b"untouched.o".as_slice(), untouched.as_slice()),
            ] {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), bytes.len() as u64),
                        bytes,
                    )
                    .unwrap();
            }
            let bytes = builder.into_inner().unwrap();
            let mut entries = ArchiveIterator::from_archive_bytes(&bytes).unwrap();
            let ArchiveEntry::Regular(member) = entries.next().unwrap().unwrap() else {
                panic!("expected regular archive member");
            };
            let text = test_macho_section_range(member.entry_data, "__text");
            let data_offset = member.data_offset;
            (bytes, data_offset + text.start..data_offset + text.end)
        };
        let (previous_archive, previous_text) = archive(&previous);
        let (current_archive, current_text) = archive(&current);
        let ignored = HashSet::from([b"_text".to_vec()]);

        assert_eq!(
            archive_macho_semantic_patch_proof_fingerprint(
                &previous_archive,
                &[previous_text],
                &[],
                &ignored,
            )
            .unwrap(),
            archive_macho_semantic_patch_proof_fingerprint(
                &current_archive,
                &[current_text],
                &[],
                &ignored,
            )
            .unwrap(),
        );
        assert_ne!(
            macho_object_patch_fingerprint(
                &previous,
                0,
                &[test_macho_section_range(&previous, "__text")],
            ),
            macho_object_patch_fingerprint(
                &current,
                0,
                &[test_macho_section_range(&current, "__text")],
            ),
            "ordinary patch fingerprints must retain symbol layout sensitivity",
        );
    }

