    #[test]
    fn retired_macho_symbol_proof_requires_one_previous_and_zero_current_definitions() {
        let object = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let archive = |members: &[(&[u8], &[u8])]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, bytes) in members {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), bytes.len() as u64),
                        *bytes,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let name = b"_text".to_vec();
        let names = HashSet::from([name.clone()]);
        let one = archive(&[(b"one.o", object.as_slice())]);
        let duplicate = archive(&[(b"one.o", object.as_slice()), (b"two.o", object.as_slice())]);

        assert_eq!(
            archive_macho_defined_symbol_counts(&one, &[], &names)
                .unwrap()
                .unwrap()[&name],
            1
        );
        assert_eq!(
            archive_macho_defined_symbol_counts(&duplicate, &[], &names)
                .unwrap()
                .unwrap()[&name],
            2
        );
        let one_count = archive_macho_defined_symbol_counts(&one, &[], &names)
            .unwrap()
            .unwrap();
        let duplicate_count = archive_macho_defined_symbol_counts(&duplicate, &[], &names)
            .unwrap()
            .unwrap();
        let zero_count = HashMap::from([(name.clone(), 0)]);
        assert!(macho_definition_counts_prove_retirement(
            &names,
            &one_count,
            &zero_count
        ));
        assert!(
            !macho_definition_counts_prove_retirement(&names, &duplicate_count, &zero_count),
            "duplicate previous definitions must reject retirement"
        );
        assert!(
            !macho_definition_counts_prove_retirement(&names, &one_count, &one_count),
            "current same-name reappearance must reject retirement"
        );
        assert!(macho_definition_counts_prove_restoration(
            &names,
            &zero_count,
            &one_count,
        ));
        assert!(
            !macho_definition_counts_prove_restoration(&names, &zero_count, &duplicate_count),
            "duplicate current definitions must reject restoration"
        );
        assert!(
            !macho_definition_counts_prove_restoration(&names, &one_count, &one_count),
            "previous same-name definitions must reject restoration"
        );
    }

    #[test]
    fn dormant_macho_text_section_activation_consumes_reserve_transactionally() {
        let previous = test_macho_data_object(b"\x05\x06\x07\x08", Some(b""), false);
        let current = test_macho_data_object(b"\x05\x06\x07\x08", Some(b"\x1f\x20\x03\xd5"), false);
        let input = hex::encode("input.o");
        let data = PatchSection {
            input: input.clone(),
            section_index: 0,
            section_name: Some("__DATA,__data".to_owned()),
            input_size: 4,
            output_offset: 64,
            output_size: 4,
            data_hash: Some(hash_bytes(b"\x05\x06\x07\x08")),
            cstring_nul_boundaries_hash: None,
        };
        let previous_text = PatchSection {
            input: input.clone(),
            section_index: 1,
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: 0,
            output_offset: 96,
            output_size: 0,
            data_hash: Some(hash_bytes(b"")),
            cstring_nul_boundaries_hash: None,
        };
        let mut current_text = previous_text.clone();
        current_text.input_size = 4;
        current_text.data_hash = Some(hash_bytes(b"\x1f\x20\x03\xd5"));
        let matched = [
            MatchedPatchSection::same(data),
            MatchedPatchSection {
                previous: previous_text,
                current: current_text,
            },
        ];
        let reserves = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 16,
        }];

        let activation = macho_text_section_activation(
            &previous, &current, &input, &matched, &reserves, 100, true, true,
        )
        .unwrap()
        .unwrap()
        .unwrap();

        let [activated] = activation.text_sections.as_slice() else {
            panic!("expected one activated text section");
        };
        assert_eq!(activated.section.section_index, 1);
        assert_eq!(
            activated.section.section_name.as_deref(),
            Some("__TEXT,__text")
        );
        assert_eq!(activated.section.input_size, 4);
        assert_eq!(activated.section.output_offset, 128);
        assert_eq!(activated.section.output_size, 8);
        assert_eq!(activated.matched_section_index, Some(1));
        assert!(!activation.grew_existing_sections);
        assert!(activation.appended_records.is_empty());
        assert!(activation.auxiliary_sections.is_empty());
        assert!(activation.auxiliary_patches.is_empty());
        assert_eq!(
            activation.remaining_reserved_ranges,
            vec![ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: 2,
                output_offset: 136,
                size: 8,
            }]
        );

        let resolved =
            resolved_patch_sections_for_input(&current, &input, [activated.section.clone()])
                .unwrap()
                .unwrap();
        assert_eq!(resolved[0].patch.data, b"\x1f\x20\x03\xd5");
        assert_eq!(resolved[0].patch.size, 8);
    }

    #[test]
    fn dormant_macho_text_section_activation_rejects_unsafe_deltas() {
        let previous = test_macho_data_object(b"\x05\x06\x07\x08", Some(b""), false);
        let input = hex::encode("input.o");
        let data = PatchSection {
            input: input.clone(),
            section_index: 0,
            section_name: Some("__DATA,__data".to_owned()),
            input_size: 4,
            output_offset: 64,
            output_size: 4,
            data_hash: Some(hash_bytes(b"\x05\x06\x07\x08")),
            cstring_nul_boundaries_hash: None,
        };
        let previous_text = PatchSection {
            input: input.clone(),
            section_index: 1,
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: 0,
            output_offset: 96,
            output_size: 0,
            data_hash: Some(hash_bytes(b"")),
            cstring_nul_boundaries_hash: None,
        };
        let mut current_text = previous_text.clone();
        current_text.input_size = 4;
        current_text.data_hash = Some(hash_bytes(b"\x1f\x20\x03\xd5"));
        let matched = [
            MatchedPatchSection::same(data),
            MatchedPatchSection {
                previous: previous_text,
                current: current_text,
            },
        ];
        let reserves = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 16,
        }];

        let symbol = test_macho_data_object(b"\x05\x06\x07\x08", Some(b"\x1f\x20\x03\xd5"), true);
        assert!(
            macho_text_section_activation(
                &previous, &symbol, &input, &matched, &reserves, 100, true, true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("changed symbols")
        );

        let mut unrelated_change =
            test_macho_data_object(b"\x05\x06\x07\x08", Some(b"\x1f\x20\x03\xd5"), false);
        unrelated_change[8] ^= 1;
        assert!(
            macho_text_section_activation(
                &previous,
                &unrelated_change,
                &input,
                &matched,
                &reserves,
                100,
                true,
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("outside activated")
        );

        let current = test_macho_data_object(b"\x05\x06\x07\x08", Some(b"\x1f\x20\x03\xd5"), false);
        let insufficient = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 4,
        }];
        assert!(
            macho_text_section_activation(
                &previous,
                &current,
                &input,
                &matched,
                &insufficient,
                100,
                true,
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("insufficient incremental reserve")
        );
        assert_eq!(insufficient[0].output_offset, 128);
        assert_eq!(insufficient[0].size, 4);
    }

    #[test]
    fn grown_macho_archive_text_section_activation_consumes_reserve() {
        fn archive(input_file: &str, identifier: &[u8], object: &[u8]) -> (Vec<u8>, String) {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            let archive = builder.into_inner().unwrap();
            let ArchiveMemberMatch::Unique(member) =
                patch_archive_member_bytes(&archive, identifier).unwrap()
            else {
                panic!("expected unique archive member");
            };
            let input_ref = resolved_patch_input_ref(input_file, input_file, member).unwrap();
            (archive, input_ref)
        }

        let input_file = hex::encode("libarchive.rlib");
        let previous_object = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let current_object =
            test_macho_object(b"\x01\x02\x03\x04\x09\x0a\x0b\x0c", b"\x05\x06\x07\x08", 0);
        let (previous, previous_input) =
            archive(&input_file, b"crate-hash.cgu.old.rcgu.o", &previous_object);
        let (current, current_input) =
            archive(&input_file, b"crate-hash.cgu.new.rcgu.o", &current_object);
        let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
        let current_file = object::File::parse(current_object.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let previous_section = PatchSection {
            input: previous_input,
            section_index: patch_section_record_index(&previous_file, previous_text.index())
                .unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: previous_text.size(),
            output_offset: 64,
            output_size: previous_text.size(),
            data_hash: Some(hash_bytes(previous_text.data().unwrap())),
            cstring_nul_boundaries_hash: None,
        };
        let current_section = PatchSection {
            input: current_input,
            section_index: patch_section_record_index(&current_file, current_text.index()).unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: current_text.size(),
            output_offset: 64,
            output_size: previous_text.size(),
            data_hash: Some(hash_bytes(current_text.data().unwrap())),
            cstring_nul_boundaries_hash: None,
        };
        let matched = [MatchedPatchSection {
            previous: previous_section.clone(),
            current: current_section.clone(),
        }];
        let reserves = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 32,
        }];

        let activation = macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &matched,
            &reserves,
            100,
            true,
            false,
        )
        .unwrap()
        .unwrap()
        .unwrap();

        let [activated] = activation.text_sections.as_slice() else {
            panic!("expected one grown text section");
        };
        assert!(activation.grew_existing_sections);
        assert_eq!(activated.matched_section_index, Some(0));
        assert_eq!(activated.section.output_offset, 128);
        assert_eq!(activated.section.output_size, 16);
        assert_eq!(
            activation.normalized_archive_identifiers,
            [b"crate-hash.cgu.rcgu.o".to_vec()]
        );
        assert_eq!(
            activation.remaining_reserved_ranges,
            vec![ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: 2,
                output_offset: 144,
                size: 16,
            }]
        );

        let (stable_current, stable_current_input) =
            archive(&input_file, b"crate-hash.cgu.old.rcgu.o", &current_object);
        let stable_matched = [MatchedPatchSection {
            previous: previous_section,
            current: PatchSection {
                input: stable_current_input,
                ..current_section
            },
        }];
        let stable_activation = macho_text_section_activation(
            &previous,
            &stable_current,
            &input_file,
            &stable_matched,
            &reserves,
            100,
            true,
            false,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert!(
            stable_activation.normalized_archive_identifiers.is_empty(),
            "exact-stable archive members use the ordinary masked archive fingerprint"
        );
    }

    #[test]
    fn grown_macho_archive_text_sections_activate_transactionally() {
        fn archive(input_file: &str, members: &[(&[u8], &[u8])]) -> (Vec<u8>, Vec<String>) {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, object) in members {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), object.len() as u64),
                        *object,
                    )
                    .unwrap();
            }
            let archive = builder.into_inner().unwrap();
            let inputs = members
                .iter()
                .map(|(identifier, _)| {
                    let ArchiveMemberMatch::Unique(member) =
                        patch_archive_member_bytes(&archive, identifier).unwrap()
                    else {
                        panic!("expected unique archive member");
                    };
                    resolved_patch_input_ref(input_file, input_file, member).unwrap()
                })
                .collect();
            (archive, inputs)
        }

        let input_file = hex::encode("libarchive.rlib");
        let previous_objects = [
            test_macho_object(b"\x01\x02\x03\x04", b"\x11\x12\x13\x14", 0),
            test_macho_object(b"\x05\x06\x07\x08", b"\x15\x16\x17\x18", 0),
        ];
        let current_objects = [
            test_macho_object(b"\x01\x02\x03\x04\x09\x0a\x0b\x0c", b"\x11\x12\x13\x14", 0),
            test_macho_object(b"\x05\x06\x07\x08\x0d\x0e\x0f\x10", b"\x15\x16\x17\x18", 0),
        ];
        let previous_members = [
            (
                b"crate.one.old.rcgu.o".as_slice(),
                previous_objects[0].as_slice(),
            ),
            (
                b"crate.two.old.rcgu.o".as_slice(),
                previous_objects[1].as_slice(),
            ),
        ];
        let current_members = [
            (
                b"crate.one.new.rcgu.o".as_slice(),
                current_objects[0].as_slice(),
            ),
            (
                b"crate.two.new.rcgu.o".as_slice(),
                current_objects[1].as_slice(),
            ),
        ];
        let (previous, previous_inputs) = archive(&input_file, &previous_members);
        let (current, current_inputs) = archive(&input_file, &current_members);
        let matched = previous_objects
            .iter()
            .zip(&current_objects)
            .zip(previous_inputs.iter().zip(&current_inputs))
            .enumerate()
            .map(
                |(index, ((previous_object, current_object), (previous_input, current_input)))| {
                    let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
                    let current_file = object::File::parse(current_object.as_slice()).unwrap();
                    let previous_text = previous_file.section_by_name("__text").unwrap();
                    let current_text = current_file.section_by_name("__text").unwrap();
                    MatchedPatchSection {
                        previous: PatchSection {
                            input: previous_input.clone(),
                            section_index: patch_section_record_index(
                                &previous_file,
                                previous_text.index(),
                            )
                            .unwrap(),
                            section_name: Some("__TEXT,__text".to_owned()),
                            input_size: previous_text.size(),
                            output_offset: 64 + index as u64 * 16,
                            output_size: previous_text.size(),
                            data_hash: Some(hash_bytes(previous_text.data().unwrap())),
                            cstring_nul_boundaries_hash: None,
                        },
                        current: PatchSection {
                            input: current_input.clone(),
                            section_index: patch_section_record_index(
                                &current_file,
                                current_text.index(),
                            )
                            .unwrap(),
                            section_name: Some("__TEXT,__text".to_owned()),
                            input_size: current_text.size(),
                            output_offset: 64 + index as u64 * 16,
                            output_size: previous_text.size(),
                            data_hash: Some(hash_bytes(current_text.data().unwrap())),
                            cstring_nul_boundaries_hash: None,
                        },
                    }
                },
            )
            .collect::<Vec<_>>();
        let reserves = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 64,
        }];

        let activation = grown_macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &matched,
            &reserves,
            100,
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();

        assert_eq!(activation.text_sections.len(), 2);
        assert_eq!(
            activation
                .text_sections
                .iter()
                .map(|activated| (
                    activated.matched_section_index,
                    activated.section.output_offset,
                    activated.section.output_size,
                ))
                .collect::<Vec<_>>(),
            [(Some(0), 128, 16), (Some(1), 144, 16)]
        );
        assert_eq!(
            activation.normalized_archive_identifiers,
            [b"crate.one.rcgu.o".to_vec(), b"crate.two.rcgu.o".to_vec()]
        );
        assert_eq!(
            activation.remaining_reserved_ranges,
            [ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: 2,
                output_offset: 160,
                size: 32,
            }]
        );

        let insufficient = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 2,
            output_offset: 128,
            size: 16,
        }];
        let failure = grown_macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &matched,
            &insufficient,
            100,
            true,
        )
        .unwrap()
        .err()
        .unwrap();
        assert!(failure.contains("insufficient incremental reserve"));
        assert_eq!(insufficient[0].output_offset, 128);
        assert_eq!(insufficient[0].size, 16);

        let ambiguous = [matched[0].clone(), matched[0].clone()];
        let failure = grown_macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &ambiguous,
            &reserves,
            100,
            true,
        )
        .unwrap()
        .err()
        .unwrap();
        assert!(failure.contains("multiple grown text sections in one object"));
    }

    #[test]
    fn grown_macho_archive_text_section_activation_allocates_exception_table() {
        fn archive(input_file: &str, identifier: &[u8], object: &[u8]) -> (Vec<u8>, String) {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            let archive = builder.into_inner().unwrap();
            let ArchiveMemberMatch::Unique(member) =
                patch_archive_member_bytes(&archive, identifier).unwrap()
            else {
                panic!("expected unique archive member");
            };
            let input_ref = resolved_patch_input_ref(input_file, input_file, member).unwrap();
            (archive, input_ref)
        }

        let input_file = hex::encode("libarchive.rlib");
        let previous_object = test_observed_049_macho_unwind_object(false);
        let current_object = test_observed_049_macho_unwind_object(true);
        let (previous, previous_input) =
            archive(&input_file, b"crate-hash.cgu.old.rcgu.o", &previous_object);
        let (current, current_input) =
            archive(&input_file, b"crate-hash.cgu.new.rcgu.o", &current_object);
        let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
        let current_file = object::File::parse(current_object.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let current_gcc_except_table = current_file.section_by_name("__gcc_except_tab").unwrap();
        let text_alignment = crate::alignment::Alignment::new(current_text.align().max(1)).unwrap();
        let gcc_alignment =
            crate::alignment::Alignment::new(current_gcc_except_table.align().max(1)).unwrap();
        let previous_section = PatchSection {
            input: previous_input.clone(),
            section_index: patch_section_record_index(&previous_file, previous_text.index())
                .unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: previous_text.size(),
            output_offset: 64,
            output_size: previous_text.size(),
            data_hash: Some(hash_bytes(previous_text.data().unwrap())),
            cstring_nul_boundaries_hash: None,
        };
        let current_section = PatchSection {
            input: current_input.clone(),
            section_index: patch_section_record_index(&current_file, current_text.index()).unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: current_text.size(),
            output_offset: 64,
            output_size: previous_text.size(),
            data_hash: Some(hash_bytes(current_text.data().unwrap())),
            cstring_nul_boundaries_hash: None,
        };
        let matched = [MatchedPatchSection {
            previous: previous_section,
            current: current_section,
        }];
        let text_output_offset = 0x1000;
        let gcc_output_offset = 0x2000;
        let reserves = [
            ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: text_alignment.exponent,
                output_offset: text_output_offset,
                size: current_text.size(),
            },
            ReservedRangeRecord {
                output_section_id: crate::output_section_id::GCC_EXCEPT_TABLE.as_usize() as u32,
                alignment_exponent: gcc_alignment.exponent,
                output_offset: gcc_output_offset,
                size: current_gcc_except_table.size(),
            },
        ];

        let activation = macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &matched,
            &reserves,
            0,
            true,
            false,
        )
        .unwrap()
        .unwrap()
        .unwrap();

        let [activated] = activation.text_sections.as_slice() else {
            panic!("expected one grown text section");
        };
        assert!(activation.grew_existing_sections);
        assert_eq!(activated.section.output_offset, text_output_offset);
        assert_eq!(activated.section.output_size, current_text.size());
        assert_eq!(activation.auxiliary_sections.len(), 1);
        let exception_table = &activation.auxiliary_sections[0];
        assert_eq!(exception_table.input, current_input);
        assert_eq!(
            exception_table.section_name.as_deref(),
            Some("__TEXT,__gcc_except_tab")
        );
        assert_eq!(exception_table.input_size, current_gcc_except_table.size());
        assert_eq!(exception_table.output_offset, gcc_output_offset);
        assert_eq!(
            activation.auxiliary_patches[0].data,
            current_gcc_except_table.data().unwrap()
        );
        assert_eq!(
            activation.appended_records,
            vec![SectionRecord {
                input_file: input_file.clone().into(),
                input: exception_table.input.clone().into(),
                section_index: exception_table.section_index,
                output_offset: gcc_output_offset,
                size: current_gcc_except_table.size(),
            }]
        );
        assert_eq!(
            activation.retired_record_keys,
            vec![(
                previous_input,
                patch_section_record_index(
                    &previous_file,
                    previous_file
                        .section_by_name("__gcc_except_tab")
                        .unwrap()
                        .index(),
                )
                .unwrap(),
            )]
        );
        assert!(activation.remaining_reserved_ranges.is_empty());

        let insufficient_reserves = [ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: text_alignment.exponent,
            output_offset: text_output_offset,
            size: current_text.size(),
        }];
        let failure = macho_text_section_activation(
            &previous,
            &current,
            &input_file,
            &matched,
            &insufficient_reserves,
            0,
            true,
            false,
        )
        .unwrap()
        .err()
        .unwrap();
        assert!(failure.contains("reserve for grown Mach-O exception table"));
        assert_eq!(
            insufficient_reserves[0],
            ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: text_alignment.exponent,
                output_offset: text_output_offset,
                size: current_text.size(),
            }
        );
    }

    #[test]
    fn current_patch_state_masks_macho_symbol_catalog_values() {
        let previous = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let current = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 1);
        let mut input_file = crate::input_data::InputFile::for_testing();
        input_file.filename = PathBuf::from("input.o");
        let input_ref = InputRef {
            file: &input_file,
            entry: None,
        };
        let input = encode_path(&input_file.filename);
        let sections = [
            SectionRecord::new(input_ref, object::SectionIndex(0), 64, 4),
            SectionRecord::new(input_ref, object::SectionIndex(1), 128, 4),
        ];
        let sections = sections.iter().collect::<Vec<_>>();
        let mut output = vec![0; 132];
        output[64..68].copy_from_slice(b"\x01\x02\x03\x04");
        output[128..132].copy_from_slice(b"\x05\x06\x07\x08");
        let resolution = MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode("_data")),
            direct_value: Some(0x1000),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: SharedText::from(input.clone()),
                input: SharedText::from(input.clone()),
                section_index: 2,
                section_offset: 0,
            }),
        };
        let previous_patch = current_patch_state(
            &previous,
            &input,
            &output,
            &sections,
            &[],
            &[],
            &[],
            &[&resolution],
            &[],
            true,
            None,
            PatchInputLookup::CurrentRecordedRange,
        )
        .unwrap()
        .unwrap();
        let input_state = FileState {
            path: input.clone(),
            content: FileContentState::from_bytes(&previous),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };
        let mut current_resolutions = vec![resolution];
        let updates = update_macho_symbol_resolutions_for_input(
            &mut current_resolutions,
            &input_state,
            &current,
            false,
            None,
        )
        .unwrap()
        .unwrap();
        assert!(updates.changed);
        let current_fingerprint = patch_fingerprint_with_extra_ranges(
            &current,
            &input,
            previous_patch.sections.iter().map(|section| PatchSection {
                input: section.input.clone(),
                section_index: section.section_index,
                section_name: section.section_name.clone(),
                input_size: section.input_size,
                output_offset: section.output_offset,
                output_size: section.output_size,
                data_hash: section.data_hash.clone(),
                cstring_nul_boundaries_hash: section.cstring_nul_boundaries_hash.clone(),
            }),
            updates.input_ranges,
        )
        .unwrap()
        .unwrap();

        assert_eq!(previous_patch.fingerprint, current_fingerprint);
    }

    #[test]
    fn macho_symbol_resolution_uses_activated_output_address() {
        let object = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let file = object::File::parse(object.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let input_path = hex::encode("input.o");
        let output = test_macho_unwind_output(0x1000);
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
        let previous_output_offset = output.text_offset + 0x100;
        let current_output_offset = output.text_offset + 0x500;
        let previous_value =
            macho_output_address_for_file_offset(&output_file, previous_output_offset).unwrap();
        let current_value =
            macho_output_address_for_file_offset(&output_file, current_output_offset).unwrap();
        let section_index = patch_section_record_index(&file, text.index()).unwrap();
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: previous_output_offset,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: current_output_offset,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let input = FileState {
            path: input_path.clone(),
            content: FileContentState::from_bytes(&object),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };
        let mut resolutions = vec![MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode("_text")),
            direct_value: Some(previous_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input_path.clone().into(),
                input: input_path.into(),
                section_index: text.index().0 as u32,
                section_offset: 0,
            }),
        }];
        let updates = update_macho_symbol_resolutions_for_input(
            &mut resolutions,
            &input,
            &object,
            false,
            Some((&matched, &output.bytes)),
        )
        .unwrap()
        .unwrap();

        assert!(updates.changed);
        assert_eq!(resolutions[0].direct_value, Some(current_value));
        assert_eq!(updates.output_symbols.len(), 1);
        assert_eq!(updates.output_symbols[0].target_name, hex::encode("_text"));
        assert_eq!(
            updates.output_symbols[0].previous_target_value,
            previous_value
        );
        assert_eq!(updates.output_symbols[0].target_value, current_value);
        assert!(updates.output_symbols[0].allow_missing);
        assert_eq!(updates.moves.len(), 1);
        assert_eq!(
            updates.moves[0].name,
            SharedText::from(hex::encode("_text"))
        );
        assert_eq!(updates.moves[0].previous_value, previous_value);
        assert_eq!(updates.moves[0].current_value, current_value);
        assert_eq!(updates.moves[0].previous_target.section_offset, 0);
        assert_eq!(updates.moves[0].current_target.section_offset, 0);
    }

    #[test]
    fn changed_shadowed_macho_predecessor_requires_current_rollback_resolution() {
        let previous = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let current = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 1);
        let file = object::File::parse(previous.as_slice()).unwrap();
        let data = file.section_by_name("__data").unwrap();
        let input_path = hex::encode("input.o");
        let owner_path = hex::encode("owner.rlib");
        let output = test_macho_object(&vec![0; 0x200], &vec![0; 0x200], 0x100);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let output_data = output_file.section_by_name("__data").unwrap();
        let output_offset = output_data.file_range().unwrap().0 + 0x100;
        let previous_value =
            macho_output_address_for_file_offset(&output_file, output_offset).unwrap();
        let section_index = patch_section_record_index(&file, data.index()).unwrap();
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__DATA,__data".to_owned()),
                input_size: data.size(),
                output_offset,
                output_size: data.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__DATA,__data".to_owned()),
                input_size: data.size(),
                output_offset,
                output_size: data.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let input = FileState {
            path: input_path.clone(),
            content: FileContentState::from_bytes(&previous),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };
        let rollback = MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode("_data")),
            direct_value: Some(previous_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input_path.clone().into(),
                input: input_path.into(),
                section_index: data.index().0 as u32,
                section_offset: 0,
            }),
        };
        let replacement = MachOSymbolResolutionRecord {
            direct_value: Some(previous_value + 0x100),
            target: Some(RelocationTargetRecord {
                input_file: owner_path.clone().into(),
                input: owner_path.clone().into(),
                section_index: 1,
                section_offset: 0,
            }),
            ..rollback.clone()
        };
        let output_entry = test_macho_symbol_entry_offset(&output, b"_data");
        let rollback_nlist = output[output_entry..output_entry + 16].to_vec();
        let active = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: Vec::new(),
            active: true,
            sections: Vec::new(),
            relocations: Vec::new(),
            symbol_resolutions: vec![replacement.clone()],
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: vec![rollback.clone()],
            forward_patches: vec![StoredOutputPatch {
                output_offset: 0,
                data: rollback_nlist.clone(),
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: 0,
                data: rollback_nlist,
            }],
            unwind_transaction: None,
        };
        let owner = FileState {
            path: owner_path,
            content: FileContentState::from_bytes(&[]),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: Some(FilePatchState {
                fingerprint: String::new(),
                archive_member_set_proof: None,
                archive_member_patch_fingerprints: None,
                macho_archive_members: vec![active.clone()],
                sections: Vec::new(),
                raw_sections: None,
            }),
        };

        let reason = validate_active_macho_archive_rollback_symbol_resolutions_for_input(
            &[input.clone(), owner.clone()],
            &input,
            &current,
            Some((&matched, &output)),
            None,
        )
        .unwrap()
        .unwrap_err();
        assert!(reason.contains("shadowed by an active rollback transaction changed"));

        validate_active_macho_archive_rollback_symbol_resolutions_for_input(
            &[input.clone(), owner.clone()],
            &input,
            &previous,
            Some((&matched, &output)),
            None,
        )
        .unwrap()
        .unwrap();

        let mut weak = previous.clone();
        let entry = test_macho_symbol_entry_offset(&weak, b"_data");
        weak[entry + 6..entry + 8].copy_from_slice(&object::macho::N_WEAK_DEF.to_le_bytes());
        let mut private = previous.clone();
        let entry = test_macho_symbol_entry_offset(&private, b"_data");
        private[entry + 4] |= object::macho::N_PEXT;
        let mut changed_desc = previous.clone();
        let entry = test_macho_symbol_entry_offset(&changed_desc, b"_data");
        changed_desc[entry + 6..entry + 8]
            .copy_from_slice(&object::macho::N_NO_DEAD_STRIP.to_le_bytes());
        for (kind, changed) in [
            ("weak", weak),
            ("private", private),
            ("n_desc", changed_desc),
        ] {
            let reason = validate_active_macho_archive_rollback_symbol_resolutions_for_input(
                &[input.clone(), owner.clone()],
                &input,
                &changed,
                Some((&matched, &output)),
                None,
            )
            .unwrap()
            .unwrap_err();
            assert!(
                reason.contains("shadowed by an active rollback transaction changed"),
                "unexpected {kind} binding validation result: {reason}"
            );
        }

        let mut dormant_owner = owner.clone();
        dormant_owner.patch.as_mut().unwrap().macho_archive_members[0].active = false;
        validate_active_macho_archive_rollback_symbol_resolutions_for_input(
            &[input.clone(), dormant_owner],
            &input,
            &current,
            Some((&matched, &output)),
            None,
        )
        .unwrap()
        .unwrap();

        validate_active_macho_archive_rollback_symbol_resolutions_for_input(
            &[input, owner],
            &FileState {
                path: hex::encode("unrelated.o"),
                content: FileContentState::from_bytes(&current),
                snapshot_identity: None,
                rustc_link_content_digest: None,
                rustc_raw_object_manifest: None,
                patch: None,
            },
            &current,
            Some((&matched, &output)),
            None,
        )
        .unwrap()
        .unwrap();

        let mut resolutions = vec![replacement];
        finalize_retired_macho_archive_symbol_resolutions(
            &mut resolutions,
            &[RetiredMachOArchiveActivation {
                state: active,
                newly_tracked: false,
            }],
        )
        .unwrap();
        assert_eq!(resolutions, vec![rollback]);
    }

    #[test]
    fn macho_symbol_resolution_reuses_proven_section_owner() {
        let object = test_macho_object(b"\x01\x02\x03\x04", b"\x05\x06\x07\x08", 0);
        let current_file = object::File::parse(object.as_slice()).unwrap();
        let text = current_file.section_by_name("__text").unwrap();
        let input_file_path = hex::encode("input.rlib");
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(b"old.rcgu.o".to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let previous = builder.into_inner().unwrap();
        let mut entries = ArchiveIterator::from_archive_bytes(&previous).unwrap();
        let ArchiveEntry::Regular(member) = entries.next().unwrap().unwrap() else {
            panic!("expected regular archive member");
        };
        let previous_input = resolved_patch_input_ref(
            &input_file_path,
            &input_file_path,
            PatchInputBytes {
                bytes: member.entry_data,
                file_offset: member.data_offset,
                archive_identifier: Some(member.ident.as_slice()),
            },
        )
        .unwrap();
        let output = test_macho_unwind_output(0x1000);
        let output_offset = output.text_offset + 0x100;
        let section_index = patch_section_record_index(&current_file, text.index()).unwrap();
        let records = [SectionRecord {
            input_file: input_file_path.clone().into(),
            input: previous_input.clone().into(),
            section_index,
            output_offset,
            size: text.size(),
        }];

        let mapping = retained_macho_section_owner_mapping(
            &previous,
            &input_file_path,
            &previous_input,
            &current_file,
            section_index,
            &records,
            &[],
            &[],
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(mapping.previous.input, previous_input);
        assert_eq!(mapping.current.input, previous_input);
        assert_eq!(mapping.current.section_index, section_index);
        assert_eq!(mapping.current.output_offset, output_offset);
    }

    #[test]
    fn retained_macho_output_owner_is_recovered_from_auxiliary_match() {
        let previous_object = test_macho_object(b"old!", b"same", 0);
        let current_object = test_macho_object(b"new!", b"same", 0);
        let input_file_path = hex::encode("input.rlib");
        let mut previous_builder = ar::Builder::new(Vec::new());
        previous_builder
            .append(
                &ar::Header::new(
                    b"crate-hash.cgu.old.rcgu.o".to_vec(),
                    previous_object.len() as u64,
                ),
                previous_object.as_slice(),
            )
            .unwrap();
        let previous = previous_builder.into_inner().unwrap();
        let mut current_builder = ar::Builder::new(Vec::new());
        current_builder
            .append(
                &ar::Header::new(
                    b"crate-hash.cgu.new.rcgu.o".to_vec(),
                    current_object.len() as u64,
                ),
                current_object.as_slice(),
            )
            .unwrap();
        let current = current_builder.into_inner().unwrap();

        let mut previous_entries = ArchiveIterator::from_archive_bytes(&previous).unwrap();
        let ArchiveEntry::Regular(previous_member) = previous_entries.next().unwrap().unwrap()
        else {
            panic!("expected previous archive member");
        };
        let previous_input = resolved_patch_input_ref(
            &input_file_path,
            &input_file_path,
            PatchInputBytes {
                bytes: previous_member.entry_data,
                file_offset: previous_member.data_offset,
                archive_identifier: Some(previous_member.ident.as_slice()),
            },
        )
        .unwrap();
        let mut current_entries = ArchiveIterator::from_archive_bytes(&current).unwrap();
        let ArchiveEntry::Regular(current_member) = current_entries.next().unwrap().unwrap() else {
            panic!("expected current archive member");
        };
        let current_input = resolved_patch_input_ref(
            &input_file_path,
            &input_file_path,
            PatchInputBytes {
                bytes: current_member.entry_data,
                file_offset: current_member.data_offset,
                archive_identifier: Some(current_member.ident.as_slice()),
            },
        )
        .unwrap();
        let previous_file = object::File::parse(previous_member.entry_data).unwrap();
        let current_file = object::File::parse(current_member.entry_data).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let previous_const = previous_file.section_by_name("__data").unwrap();
        let current_const = current_file.section_by_name("__data").unwrap();
        let text_index = patch_section_record_index(&previous_file, previous_text.index()).unwrap();
        let const_index =
            patch_section_record_index(&previous_file, previous_const.index()).unwrap();
        assert_eq!(
            text_index,
            patch_section_record_index(&current_file, current_text.index()).unwrap()
        );
        assert_eq!(
            const_index,
            patch_section_record_index(&current_file, current_const.index()).unwrap()
        );
        let records = [SectionRecord {
            input_file: input_file_path.clone().into(),
            input: previous_input.clone().into(),
            section_index: text_index,
            output_offset: 0x100,
            size: previous_text.size(),
        }];
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: previous_input.clone(),
                section_index: const_index,
                section_name: patch_section_name_for_matching(&previous_const),
                input_size: previous_const.size(),
                output_offset: 0x200,
                output_size: previous_const.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input.clone(),
                section_index: const_index,
                section_name: patch_section_name_for_matching(&current_const),
                input_size: current_const.size(),
                output_offset: 0x200,
                output_size: current_const.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let current_resolver = PatchInputResolver::new(&current, true).unwrap();

        let mappings = retained_macho_output_owner_mappings(
            &previous,
            &input_file_path,
            &current_resolver,
            &records,
            &matched,
        )
        .unwrap()
        .unwrap();

        assert_eq!(mappings.len(), 1);
        assert_eq!(mappings[0].previous.input, previous_input);
        assert_eq!(mappings[0].current.input, current_input);
        assert_eq!(mappings[0].current.section_index, text_index);
        assert_eq!(mappings[0].current.output_offset, 0x100);
        assert_ne!(
            mappings[0].previous.data_hash,
            mappings[0].current.data_hash
        );

        let mut relocation = relocation_record(
            "unused.o",
            text_index,
            0,
            Some(0),
            0,
            Some("_target"),
            None,
            0,
            0x100,
            4,
            encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
                r_address: 0,
                r_symbolnum: 0,
                r_pcrel: true,
                r_length: 2,
                r_extern: true,
                r_type: object::macho::ARM64_RELOC_PAGE21,
            }),
            0,
        );
        relocation.input_file = input_file_path.clone().into();
        relocation.input = previous_input.clone().into();
        let target_moves = [MachORelocationTargetMove {
            relocation_index: 0,
            current_section_offset: 4,
            current_target_value: 0x1004,
            current_input: Some(current_input.clone().into()),
        }];
        let mappings = retained_macho_text_target_move_owner_mappings(
            &previous,
            &input_file_path,
            &current_resolver,
            &records,
            &[],
            &[relocation.clone()],
            &target_moves,
            &mut Vec::new(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(mappings.len(), 1);
        assert_eq!(mappings[0].mapping.previous.input, previous_input);
        assert_eq!(mappings[0].mapping.current.input, current_input);
        assert_eq!(mappings[0].mapping.current.section_index, text_index);

        let mut claimed = mappings[0].mapping.clone();
        claimed.previous.input = current_input.clone();
        let rebound = retained_macho_text_target_move_owner_mappings(
            &previous,
            &input_file_path,
            &current_resolver,
            &records,
            std::slice::from_ref(&claimed),
            std::slice::from_ref(&relocation),
            &target_moves,
            &mut Vec::new(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(rebound.len(), 1);
        assert_eq!(rebound[0].matched_section_index, Some(0));
        assert_eq!(rebound[0].mapping.previous.input, previous_input);
        assert_eq!(rebound[0].mapping.current.input, current_input);
        let mut changed_sections = vec![claimed.current.clone()];
        changed_sections[0].data_hash = Some("raw-text-change".to_owned());
        upsert_changed_patch_section(&mut changed_sections, rebound[0].mapping.current.clone());
        assert_eq!(changed_sections.len(), 1);
        assert_eq!(changed_sections[0].input, current_input);
        assert_eq!(changed_sections[0].section_index, text_index);

        claimed.current.output_offset += 4;
        let conflicting = retained_macho_text_target_move_owner_mappings(
            &previous,
            &input_file_path,
            &current_resolver,
            &records,
            &[claimed],
            std::slice::from_ref(&relocation),
            &target_moves,
            &mut Vec::new(),
        )
        .unwrap();
        let Err(reason) = conflicting else {
            panic!("conflicting claimed output owner was accepted");
        };
        assert!(reason.contains("conflicts with claimed output owner"));

        assert!(
            retained_macho_text_target_move_owner_mappings(
                &previous,
                &input_file_path,
                &current_resolver,
                &records,
                &[],
                std::slice::from_ref(&relocation),
                &[],
                &mut Vec::new(),
            )
            .unwrap()
            .unwrap()
            .is_empty()
        );
        let duplicate_records = [records[0].clone(), records[0].clone()];
        let duplicate = retained_macho_text_target_move_owner_mappings(
            &previous,
            &input_file_path,
            &current_resolver,
            &duplicate_records,
            &[],
            std::slice::from_ref(&relocation),
            &target_moves,
            &mut Vec::new(),
        )
        .unwrap();
        let Err(reason) = duplicate else {
            panic!("duplicate retained owner records were accepted");
        };
        assert!(reason.contains("ambiguous previous output mappings"));
        relocation.kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: false,
            r_length: 3,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_UNSIGNED,
        });
        assert!(
            retained_macho_text_target_move_owner_mappings(
                &previous,
                &input_file_path,
                &current_resolver,
                &records,
                &[],
                &[relocation],
                &target_moves,
                &mut Vec::new(),
            )
            .unwrap()
            .unwrap()
            .is_empty()
        );
    }

    #[test]
    fn retained_macho_const_owner_requires_an_exact_record() {
        fn archive(object: &[u8]) -> Vec<u8> {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(b"unit.rcgu.o".to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        }

        let previous_object = test_macho_object_with_text_const(b"old!", b"constant", true, false);
        let current_object =
            test_macho_object_with_text_const(b"newer!", b"constant-grown", true, false);
        let previous = archive(&previous_object);
        let current = archive(&current_object);
        let input_file = hex::encode("input.rlib");
        let ArchiveMemberMatch::Unique(previous_member) =
            patch_archive_member_bytes(&previous, b"unit.rcgu.o").unwrap()
        else {
            panic!("expected previous archive member");
        };
        let ArchiveMemberMatch::Unique(current_member) =
            patch_archive_member_bytes(&current, b"unit.rcgu.o").unwrap()
        else {
            panic!("expected current archive member");
        };
        let previous_input =
            resolved_patch_input_ref(&input_file, &input_file, previous_member).unwrap();
        let current_input =
            resolved_patch_input_ref(&input_file, &input_file, current_member).unwrap();
        let previous_file = object::File::parse(previous_member.bytes).unwrap();
        let current_file = object::File::parse(current_member.bytes).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let previous_const = previous_file.section_by_name("__const").unwrap();
        let current_const = current_file.section_by_name("__const").unwrap();
        let text_index = patch_section_record_index(&previous_file, previous_text.index()).unwrap();
        let const_index =
            patch_section_record_index(&previous_file, previous_const.index()).unwrap();
        assert_eq!(
            text_index,
            patch_section_record_index(&current_file, current_text.index()).unwrap()
        );
        assert_eq!(
            const_index,
            patch_section_record_index(&current_file, current_const.index()).unwrap()
        );
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: previous_input.clone(),
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input.clone(),
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let text_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.clone().into(),
            section_index: text_index,
            output_offset: 0x100,
            size: current_text.size(),
        };
        let const_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.into(),
            section_index: const_index,
            output_offset: 0x200,
            size: current_const.size() + 8,
        };
        let resolver = PatchInputResolver::new(&current, true).unwrap();

        let mappings = retained_macho_output_owner_mappings(
            &previous,
            &input_file,
            &resolver,
            &[text_record.clone(), const_record.clone()],
            &matched,
        )
        .unwrap()
        .unwrap();
        assert_eq!(mappings.len(), 1);
        assert_eq!(
            mappings[0].current.section_name.as_deref(),
            Some("__TEXT,__const")
        );
        assert_eq!(mappings[0].current.output_offset, 0x200);
        let resolved = resolved_patch_sections_for_input_with_resolver_detailed(
            &input_file,
            matched
                .iter()
                .map(|section| section.current.clone())
                .chain(mappings.iter().map(|section| section.current.clone())),
            std::iter::empty(),
            std::iter::empty(),
            &resolver,
        )
        .unwrap()
        .unwrap();
        assert_eq!(resolved.len(), 2);

        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &resolver,
                std::slice::from_ref(&text_record),
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "matched text ownership must not confer const ownership",
        );

        let mut short_const_record = const_record;
        short_const_record.size = current_const.size() - 1;
        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &resolver,
                &[text_record, short_const_record],
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "const growth beyond its recorded capacity must not recover ownership",
        );
    }

    #[test]
    fn retained_macho_data_const_owner_requires_an_exact_record() {
        fn archive(identifier: &[u8], object: &[u8]) -> Vec<u8> {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        }

        let previous_identifier = b"crate-hash.cgu.previous.rcgu.o";
        let current_identifier = b"crate-hash.cgu.current.rcgu.o";
        assert_eq!(
            archive_member_patch_identifier(previous_identifier),
            archive_member_patch_identifier(current_identifier),
        );
        let previous_object =
            test_macho_object_with_data_section_name(b"text", b"constant", 0, b"__const");
        let current_object =
            test_macho_object_with_data_section_name(b"text", b"conSTAnt", 0, b"__const");
        let previous = archive(previous_identifier, &previous_object);
        let current = archive(current_identifier, &current_object);
        let input_file = hex::encode("input.rlib");
        let ArchiveMemberMatch::Unique(previous_member) =
            patch_archive_member_bytes(&previous, previous_identifier).unwrap()
        else {
            panic!("expected previous archive member");
        };
        let ArchiveMemberMatch::Unique(current_member) =
            patch_archive_member_bytes(&current, current_identifier).unwrap()
        else {
            panic!("expected current archive member");
        };
        let previous_input =
            resolved_patch_input_ref(&input_file, &input_file, previous_member).unwrap();
        let current_input =
            resolved_patch_input_ref(&input_file, &input_file, current_member).unwrap();
        let previous_file = object::File::parse(previous_member.bytes).unwrap();
        let current_file = object::File::parse(current_member.bytes).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let previous_const = previous_file.section_by_name("__const").unwrap();
        let current_const = current_file.section_by_name("__const").unwrap();
        assert_eq!(previous_const.segment_name().unwrap(), Some("__DATA"));
        assert_eq!(current_const.segment_name().unwrap(), Some("__DATA"));
        assert_eq!(previous_const.size(), current_const.size());
        assert_eq!(
            previous_const
                .data()
                .unwrap()
                .iter()
                .zip(current_const.data().unwrap())
                .filter(|(previous, current)| previous != current)
                .count(),
            3,
        );
        let text_index = patch_section_record_index(&previous_file, previous_text.index()).unwrap();
        let const_index =
            patch_section_record_index(&previous_file, previous_const.index()).unwrap();
        assert_eq!(
            text_index,
            patch_section_record_index(&current_file, current_text.index()).unwrap()
        );
        assert_eq!(
            const_index,
            patch_section_record_index(&current_file, current_const.index()).unwrap()
        );
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: previous_input.clone(),
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: 0x100,
                output_size: previous_text.size(),
                data_hash: Some(hash_bytes(previous_text.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input.clone(),
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: 0x100,
                output_size: current_text.size(),
                data_hash: Some(hash_bytes(current_text.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
        }];
        let text_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.clone().into(),
            section_index: text_index,
            output_offset: 0x100,
            size: previous_text.size(),
        };
        let const_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.into(),
            section_index: const_index,
            output_offset: 0x200,
            size: previous_const.size() + 8,
        };
        let resolver = PatchInputResolver::new(&current, true).unwrap();

        let mappings = retained_macho_output_owner_mappings(
            &previous,
            &input_file,
            &resolver,
            &[text_record.clone(), const_record.clone()],
            &matched,
        )
        .unwrap()
        .unwrap();
        assert_eq!(mappings.len(), 1);
        assert_eq!(
            mappings[0].current.section_name.as_deref(),
            Some("__DATA,__const")
        );
        assert_eq!(mappings[0].current.output_offset, 0x200);
        let resolved = resolved_patch_sections_for_input_with_resolver_detailed(
            &input_file,
            [mappings[0].current.clone()],
            std::iter::empty(),
            std::iter::empty(),
            &resolver,
        )
        .unwrap()
        .unwrap();
        assert_eq!(resolved.len(), 1);
        assert_eq!(resolved[0].patch.output_offset, 0x200);
        assert_eq!(resolved[0].patch.size, current_const.size() + 8);
        assert_eq!(resolved[0].patch.data, current_const.data().unwrap());
        assert!(resolved[0].patch.preserve_ranges.is_empty());

        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &resolver,
                std::slice::from_ref(&text_record),
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "matched text ownership must not confer data-const ownership",
        );

        let mut short_const_record = const_record.clone();
        short_const_record.size = current_const.size() - 1;
        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &resolver,
                &[text_record.clone(), short_const_record],
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "data-const bytes beyond recorded capacity must not recover ownership",
        );

        let mut duplicate_const_record = const_record.clone();
        duplicate_const_record.output_offset = 0x300;
        let reason = retained_macho_output_owner_mappings(
            &previous,
            &input_file,
            &resolver,
            &[text_record, const_record, duplicate_const_record],
            &matched,
        )
        .unwrap();
        let Err(reason) = reason else {
            panic!("ambiguous data-const owners must reject recovery");
        };
        assert_eq!(
            reason,
            "retained Mach-O section owner has ambiguous previous output mappings"
        );
    }

    #[test]
    fn retained_macho_data_const_owner_preserves_recorded_relocations() {
        let previous_source = [0; 24];
        let mut current_source = previous_source;
        current_source[16..19].copy_from_slice(&[1, 2, 3]);
        let previous =
            test_macho_local_data_retarget_object_with_source(b"l_anon.20", 0x12, &previous_source);
        let current =
            test_macho_local_data_retarget_object_with_source(b"l_anon.20", 0x12, &current_source);
        let previous_file = object::File::parse(previous.as_slice()).unwrap();
        let current_file = object::File::parse(current.as_slice()).unwrap();
        let previous_const = previous_file
            .sections()
            .find(|section| {
                section.name().ok() == Some("__const")
                    && section.segment_name().ok().flatten() == Some("__DATA")
            })
            .unwrap();
        let current_const = current_file
            .sections()
            .find(|section| {
                section.name().ok() == Some("__const")
                    && section.segment_name().ok().flatten() == Some("__DATA")
            })
            .unwrap();
        let section_index =
            patch_section_record_index(&previous_file, previous_const.index()).unwrap();
        assert_eq!(
            section_index,
            patch_section_record_index(&current_file, current_const.index()).unwrap()
        );
        let input = hex::encode("relocated.o");
        let record = SectionRecord {
            input_file: input.clone().into(),
            input: input.clone().into(),
            section_index,
            output_offset: 0x100,
            size: 32,
        };
        let mapping = retained_macho_section_owner_mapping(
            &previous,
            &input,
            &input,
            &current_file,
            section_index,
            std::slice::from_ref(&record),
            &[],
            &[],
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(
            mapping.current.section_name.as_deref(),
            Some("__DATA,__const")
        );
        assert_ne!(mapping.previous.data_hash, mapping.current.data_hash);
        let resolver = PatchInputResolver::new(&current, true).unwrap();
        let materialize = |relocations: &[RelocationRecord]| {
            resolved_patch_sections_for_input_with_resolver_detailed(
                &input,
                [mapping.current.clone()],
                std::iter::empty(),
                relocations,
                &resolver,
            )
            .unwrap()
        };

        let Err(reason) = materialize(&[]) else {
            panic!("unrecorded data relocations must reject materialization");
        };
        assert_eq!(
            reason,
            "changed patch section __DATA,__const cannot be directly patched"
        );

        let relocation_kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: false,
            r_length: 3,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_UNSIGNED,
        });
        let relocation = |offset| {
            relocation_record(
                "relocated.o",
                section_index,
                0,
                Some(0),
                0,
                None,
                None,
                offset,
                0x100 + offset,
                8,
                relocation_kind,
                0,
            )
        };
        let first = relocation(0);
        let second = relocation(8);
        let mismatched = relocation(16);
        let Err(reason) = materialize(&[first.clone(), mismatched]) else {
            panic!("mismatched data relocation records must reject materialization");
        };
        assert_eq!(
            reason,
            "changed patch section __DATA,__const cannot be directly patched"
        );

        let mut resolved = materialize(&[first, second]).unwrap();
        assert_eq!(resolved.len(), 1);
        let patch = &mut resolved[0].patch;
        assert_eq!(patch.preserve_ranges, vec![0..8, 8..16]);
        let chained = encode_incremental_macho_chained_rebase(
            crate::macho::MACHO_START_MEM_ADDRESS + 0x2000,
            2,
        )
        .unwrap();
        let mut output = vec![0; 0x120];
        output[0x100..0x108].copy_from_slice(&chained.to_le_bytes());
        output[0x108..0x110].copy_from_slice(&0x1000_3000_u64.to_le_bytes());
        let output_range = &mut output[0x100..0x120];
        for preserve_range in &patch.preserve_ranges {
            patch.data[preserve_range.clone()]
                .copy_from_slice(&output_range[preserve_range.clone()]);
        }
        let (data, padding) = output_range.split_at_mut(patch.data.len());
        data.copy_from_slice(&patch.data);
        padding.fill(0);
        assert_eq!(read_u64_le(&output[0x100..0x108]), Some(chained));
        assert_eq!(read_u64_le(&output[0x108..0x110]), Some(0x1000_3000));
        assert_eq!(&output[0x110..0x113], &[1, 2, 3]);
    }

    #[test]
    fn retained_macho_data_const_owner_recovers_changed_local_cohort() {
        fn object(name: &[u8; 5]) -> Vec<u8> {
            let mut object =
                test_macho_object_with_data_section_name(b"text", b"constant", 0, b"__const");
            let entry = test_macho_symbol_entry_offset(&object, b"_data");
            object[entry + 4] &= !object::macho::N_EXT;
            let string = object
                .windows(b"_data\0".len())
                .rposition(|window| window == b"_data\0")
                .unwrap();
            object[string..string + name.len()].copy_from_slice(name);
            object
        }

        fn archive(identifier: &[u8], object: &[u8]) -> Vec<u8> {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        }

        let previous_identifier = b"crate-hash.cgu.previous.rcgu.o";
        let current_identifier = b"crate-hash.cgu.current.rcgu.o";
        let previous = archive(previous_identifier, &object(b"old__"));
        let current = archive(current_identifier, &object(b"new__"));
        let unchanged = archive(current_identifier, &object(b"old__"));
        let input_file = hex::encode("input.rlib");
        let ArchiveMemberMatch::Unique(previous_member) =
            patch_archive_member_bytes(&previous, previous_identifier).unwrap()
        else {
            panic!("expected previous archive member");
        };
        let ArchiveMemberMatch::Unique(current_member) =
            patch_archive_member_bytes(&current, current_identifier).unwrap()
        else {
            panic!("expected current archive member");
        };
        let previous_input =
            resolved_patch_input_ref(&input_file, &input_file, previous_member).unwrap();
        let current_input =
            resolved_patch_input_ref(&input_file, &input_file, current_member).unwrap();
        let previous_file = object::File::parse(previous_member.bytes).unwrap();
        let current_file = object::File::parse(current_member.bytes).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let previous_const = previous_file.section_by_name("__const").unwrap();
        let text_index = patch_section_record_index(&previous_file, previous_text.index()).unwrap();
        let const_index =
            patch_section_record_index(&previous_file, previous_const.index()).unwrap();
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: previous_input.clone(),
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: 0x100,
                output_size: previous_text.size(),
                data_hash: Some(hash_bytes(previous_text.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input,
                section_index: text_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: 0x100,
                output_size: current_text.size(),
                data_hash: Some(hash_bytes(current_text.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
        }];
        let text_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.clone().into(),
            section_index: text_index,
            output_offset: 0x100,
            size: previous_text.size(),
        };
        let const_record = SectionRecord {
            input_file: input_file.clone().into(),
            input: previous_input.into(),
            section_index: const_index,
            output_offset: 0x200,
            size: previous_const.size(),
        };

        let mappings = retained_macho_output_owner_mappings(
            &previous,
            &input_file,
            &PatchInputResolver::new(&current, true).unwrap(),
            &[text_record.clone(), const_record.clone()],
            &matched,
        )
        .unwrap()
        .unwrap();
        assert_eq!(mappings.len(), 1);
        assert_eq!(
            mappings[0].current.section_name.as_deref(),
            Some("__DATA,__const")
        );
        assert_eq!(
            mappings[0].previous.data_hash,
            mappings[0].current.data_hash
        );

        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &PatchInputResolver::new(&unchanged, true).unwrap(),
                &[text_record.clone(), const_record.clone()],
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "an unchanged local cohort must not force retained ownership",
        );
        assert!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &PatchInputResolver::new(&current, true).unwrap(),
                std::slice::from_ref(&text_record),
                &matched,
            )
            .unwrap()
            .unwrap()
            .is_empty(),
            "a changed cohort without an exact const record must remain unowned",
        );
        let mut duplicate = const_record.clone();
        duplicate.output_offset += 0x100;
        assert!(matches!(
            retained_macho_output_owner_mappings(
                &previous,
                &input_file,
                &PatchInputResolver::new(&current, true).unwrap(),
                &[text_record, const_record, duplicate],
                &matched,
            )
            .unwrap(),
            Err(reason)
                if reason == "retained Mach-O section owner has ambiguous previous output mappings"
        ));
    }

    #[test]
    fn moved_macho_symbol_retargets_recorded_thunk() {
        let object = test_macho_object(&[0; 32], &[0; 4], 0);
        let file = object::File::parse(object.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let input_path = hex::encode("input.o");
        let mut output = test_macho_unwind_output(0x1000);
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
        let previous_output_offset = output.text_offset + 0x100;
        let current_output_offset = output.text_offset + 0x500;
        let thunk_output_offset = output.text_offset + 0x700;
        let previous_value =
            macho_output_address_for_file_offset(&output_file, previous_output_offset).unwrap();
        let current_value =
            macho_output_address_for_file_offset(&output_file, current_output_offset).unwrap();
        let thunk_address =
            macho_output_address_for_file_offset(&output_file, thunk_output_offset).unwrap();
        let config =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::thunk_config().unwrap();
        let mut previous_thunk = vec![0; config.thunk_size as usize];
        <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::write_thunk(
            thunk_address,
            previous_value,
            &mut previous_thunk,
        );
        let thunk_start = thunk_output_offset as usize;
        output.bytes[thunk_start..thunk_start + previous_thunk.len()]
            .copy_from_slice(&previous_thunk);
        let section_index = patch_section_record_index(&file, text.index()).unwrap();
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: previous_output_offset,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: input_path.clone(),
                section_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: current_output_offset,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let input = FileState {
            path: input_path.clone(),
            content: FileContentState::from_bytes(&object),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };
        let resolution = MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode("_text")),
            direct_value: Some(previous_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: vec![thunk_address],
            target: Some(RelocationTargetRecord {
                input_file: input_path.clone().into(),
                input: input_path.into(),
                section_index: text.index().0 as u32,
                section_offset: 0,
            }),
        };
        let mut resolutions = vec![resolution.clone()];
        let updates = update_macho_symbol_resolutions_for_input(
            &mut resolutions,
            &input,
            &object,
            false,
            Some((&matched, &output.bytes)),
        )
        .unwrap()
        .unwrap();

        let mut expected = vec![0; config.thunk_size as usize];
        <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::write_thunk(
            thunk_address,
            current_value,
            &mut expected,
        );
        assert_eq!(updates.thunk_patches.len(), 1);
        assert_eq!(updates.thunk_patches[0].output_offset, thunk_output_offset);
        assert_eq!(updates.thunk_patches[0].data, expected);
        assert_eq!(
            updates.reusable_branch_targets,
            vec![MachOReusableBranchTarget {
                moved: updates.moves[0].clone(),
                applied_target_value: thunk_address,
            }]
        );
        assert_eq!(resolutions[0].thunk_addresses, vec![thunk_address]);

        let mut corrupted_output = output.bytes.clone();
        corrupted_output[thunk_start] ^= 1;
        assert!(matches!(
            update_macho_symbol_resolutions_for_input(
                &mut [resolution],
                &input,
                &object,
                false,
                Some((&matched, &corrupted_output)),
            )
            .unwrap(),
            Err(reason) if reason.contains("thunk encoding changed")
        ));
    }

