    #[test]
    fn published_local_macho_cohort_allows_other_local_names_only_at_distinct_sites() {
        let output = test_macho_object(&[0; 16], &[0; 16], 0);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let text = output_file.section_by_name("__text").unwrap();
        let data = output_file.section_by_name("__data").unwrap();
        let text_section = u8::try_from(text.index().0).unwrap();
        let data_section = u8::try_from(data.index().0).unwrap();
        let entry = MachOLocalSymbolCohortEntry {
            name: b"GCC_except_table17".to_vec(),
            n_desc: 0,
            output_section_index: text_section,
            output_value: text.address(),
            output_entry_offset: None,
            string_index: None,
        };

        let outside = add_test_macho_local_alias(
            output.clone(),
            &entry.name,
            text_section,
            text.address() + 8,
        );
        assert!(!macho_local_symbol_cohort_additions_collide(
            &outside,
            &[&entry],
        ));
        let repeated = add_test_macho_local_alias(
            outside.clone(),
            &entry.name,
            text_section,
            text.address() + 12,
        );
        assert!(!macho_local_symbol_cohort_additions_collide(
            &repeated,
            &[&entry],
        ));
        assert!(macho_local_symbol_cohort_additions_collide(
            &outside,
            &[&entry, &entry],
        ));
        let mut malformed = outside.clone();
        let malformed_entry = test_macho_symbol_entry_offset(&malformed, &entry.name);
        malformed[malformed_entry..malformed_entry + 4].copy_from_slice(&u32::MAX.to_le_bytes());
        assert!(macho_local_symbol_cohort_additions_collide(
            &malformed,
            &[&entry],
        ));

        let wrong_section =
            add_test_macho_local_alias(output.clone(), &entry.name, data_section, data.address());
        assert!(macho_local_symbol_cohort_additions_collide(
            &wrong_section,
            &[&entry],
        ));

        let nonrepeatable_entry = MachOLocalSymbolCohortEntry {
            name: b"l_b.2".to_vec(),
            ..entry.clone()
        };
        let nonrepeatable = add_test_macho_local_alias(
            output.clone(),
            &nonrepeatable_entry.name,
            text_section,
            text.address() + 8,
        );
        assert!(macho_local_symbol_cohort_additions_collide(
            &nonrepeatable,
            &[&nonrepeatable_entry],
        ));

        let same_site =
            add_test_macho_local_alias(output.clone(), &entry.name, text_section, text.address());
        assert!(macho_local_symbol_cohort_additions_collide(
            &same_site,
            &[&entry],
        ));

        let mut stab = outside.clone();
        let stab_entry = test_macho_symbol_entry_offset(&stab, &entry.name);
        stab[stab_entry + 4] |= object::macho::N_STAB;
        assert!(macho_local_symbol_cohort_additions_collide(
            &stab,
            &[&entry],
        ));

        for n_desc in [object::macho::N_ALT_ENTRY, object::macho::N_NO_DEAD_STRIP] {
            let mut metadata = outside.clone();
            let metadata_entry = test_macho_symbol_entry_offset(&metadata, &entry.name);
            metadata[metadata_entry + 6..metadata_entry + 8].copy_from_slice(&n_desc.to_le_bytes());
            assert!(macho_local_symbol_cohort_additions_collide(
                &metadata,
                &[&entry],
            ));
        }

        let mut global = outside;
        let global_entry = test_macho_symbol_entry_offset(&global, &entry.name);
        global[global_entry + 4] |= object::macho::N_EXT;
        assert!(macho_local_symbol_cohort_additions_collide(
            &global,
            &[&entry],
        ));
    }

    #[test]
    fn published_local_macho_cohort_batches_large_collision_checks() {
        let mut output = test_macho_object(&[0; 16], &[0; 16], 0);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let text = output_file.section_by_name("__text").unwrap();
        let text_section = u8::try_from(text.index().0).unwrap();
        let text_address = text.address();
        drop(output_file);
        for index in 0..512 {
            output = add_test_macho_local_alias(
                output,
                format!("unrelated{index}").as_bytes(),
                text_section,
                text_address + 0x1000 + index,
            );
        }
        let additions = (0..2048)
            .map(|index| MachOLocalSymbolCohortEntry {
                name: format!("added{index}").into_bytes(),
                n_desc: 0,
                output_section_index: text_section,
                output_value: text_address + 0x4000 + index,
                output_entry_offset: None,
                string_index: None,
            })
            .collect::<Vec<_>>();
        let addition_refs = additions.iter().collect::<Vec<_>>();
        assert!(!macho_local_symbol_cohort_additions_collide(
            &output,
            &addition_refs,
        ));

        let collision = MachOLocalSymbolCohortEntry {
            name: b"unrelated511".to_vec(),
            ..additions[0].clone()
        };
        assert!(macho_local_symbol_cohort_additions_collide(
            &output,
            &[&collision],
        ));
    }

    #[test]
    fn published_local_macho_cohort_indexes_large_exact_population() {
        let mut output = test_macho_object(&[0; 4096], &[0; 16], 0);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let text = output_file.section_by_name("__text").unwrap();
        let text_section = u8::try_from(text.index().0).unwrap();
        let text_address = text.address();
        drop(output_file);
        let mut entries = Vec::new();
        for index in 0..512 {
            let name = format!("local{index}").into_bytes();
            let value = text_address + index * 8;
            output = add_test_macho_local_alias(output, &name, text_section, value);
            entries.push(MachOLocalSymbolCohortEntry {
                name,
                n_desc: 0,
                output_section_index: text_section,
                output_value: value,
                output_entry_offset: None,
                string_index: None,
            });
        }
        let output_file = object::File::parse(output.as_slice()).unwrap();
        verify_previous_macho_local_symbol_cohort(
            &output,
            &output_file,
            &[test_macho_patch_section(&output, "__text")],
            &mut entries,
            &HashSet::new(),
        )
        .unwrap();
        assert!(
            entries
                .iter()
                .all(|entry| entry.output_entry_offset.is_some() && entry.string_index.is_some())
        );

        let mut duplicate_entries = vec![entries[0].clone(), entries[0].clone()];
        assert_eq!(
            verify_previous_macho_local_symbol_cohort(
                &output,
                &output_file,
                &[test_macho_patch_section(&output, "__text")],
                &mut duplicate_entries,
                &HashSet::new(),
            )
            .unwrap_err(),
            "published local Mach-O cohort contains duplicate names",
        );

        for changed in ["section", "value", "metadata"] {
            let mut changed_entries = entries.clone();
            match changed {
                "section" => changed_entries[0].output_section_index += 1,
                "value" => changed_entries[0].output_value += 1,
                "metadata" => changed_entries[0].n_desc = object::macho::N_NO_DEAD_STRIP,
                _ => unreachable!(),
            }
            assert_eq!(
                verify_previous_macho_local_symbol_cohort(
                    &output,
                    &output_file,
                    &[test_macho_patch_section(&output, "__text")],
                    &mut changed_entries,
                    &HashSet::new(),
                )
                .unwrap_err(),
                "published local Mach-O cohort has no unique output nlist",
                "accepted mismatched {changed}",
            );
        }
    }

    #[test]
    fn published_local_macho_cohort_retains_unique_mixed_population() {
        let entry = |name: &[u8], section, value, n_desc| MachOLocalSymbolCohortEntry {
            name: name.to_vec(),
            n_desc,
            output_section_index: section,
            output_value: value,
            output_entry_offset: None,
            string_index: None,
        };
        let previous = vec![entry(b"old.0", 1, 0x1000, 0), entry(b"old.1", 1, 0x1010, 0)];
        let renamed = vec![entry(b"new.0", 1, 0x1000, 0), entry(b"new.1", 1, 0x1010, 0)];
        assert!(macho_local_symbol_cohort_retains_published_population(
            &previous, &renamed,
        ));

        let moved_named = vec![entry(b"old.0", 1, 0x1020, 0), entry(b"old.1", 1, 0x1030, 0)];
        assert!(macho_local_symbol_cohort_retains_published_population(
            &previous,
            &moved_named,
        ));
        assert!(macho_local_cohort_entry_liveness_is_proven(true, 0, false));
        assert!(!macho_local_cohort_entry_liveness_is_proven(
            true,
            moved_named.len(),
            false,
        ));
        assert!(macho_local_cohort_entry_liveness_is_proven(
            true,
            moved_named.len(),
            true,
        ));
        assert!(!macho_local_cohort_entry_liveness_is_proven(false, 0, true,));

        let mixed = vec![entry(b"new.0", 1, 0x1000, 0), entry(b"old.1", 1, 0x1030, 0)];
        assert!(macho_local_symbol_cohort_retains_published_population(
            &previous, &mixed,
        ));

        let workload_previous = vec![
            entry(b"GCC_except_table14", 4, 0x1000, 0),
            entry(b"GCC_except_table15", 4, 0x1010, 0),
            entry(b"GCC_except_table16", 4, 0x1020, 0),
            entry(b"rust.local", 3, 0x2000, 0),
        ];
        let workload_current = vec![
            entry(b"GCC_except_table15", 4, 0x1000, 0),
            entry(b"GCC_except_table16", 4, 0x1010, 0),
            entry(b"GCC_except_table17", 4, 0x1020, 0),
            entry(b"rust.local", 3, 0x202c, 0),
        ];
        assert!(macho_local_symbol_cohort_retains_published_population(
            &workload_previous,
            &workload_current,
        ));
        assert_eq!(
            macho_local_symbol_cohort_retained_current_names(&workload_previous, &workload_current,),
            HashSet::from([
                b"GCC_except_table15".to_vec(),
                b"GCC_except_table16".to_vec(),
                b"GCC_except_table17".to_vec(),
            ]),
            "site-preserving renames are roots, but a same-name move is not",
        );

        let ambiguous = vec![entry(b"old.0", 1, 0x1010, 0), entry(b"old.1", 1, 0x1000, 0)];
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous, &ambiguous,
        ));

        let mut aliased_site = renamed.clone();
        aliased_site[1].output_value = aliased_site[0].output_value;
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous,
            &aliased_site,
        ));

        let mut moved_rename = renamed.clone();
        moved_rename[1].output_value += 8;
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous,
            &moved_rename,
        ));

        let mut changed_section = renamed.clone();
        changed_section[1].output_section_index += 1;
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous,
            &changed_section,
        ));

        let mut changed_metadata = renamed.clone();
        changed_metadata[1].n_desc = 1;
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous,
            &changed_metadata,
        ));
        assert!(!macho_local_symbol_cohort_retains_published_population(
            &previous,
            &renamed[..1],
        ));

        let added = vec![
            entry(b"old.0", 1, 0x1020, 0),
            entry(b"old.1", 1, 0x1030, 0),
            entry(b"new.2", 1, 0x1040, 0),
        ];
        assert!(
            macho_local_symbol_cohort_retained_current_names(&previous, &added).is_empty(),
            "same-name moves must not manufacture retained roots",
        );
        assert_eq!(
            macho_local_symbol_cohort_retained_current_names(&previous, &renamed[..1]),
            HashSet::from([b"new.0".to_vec()]),
        );
        assert!(
            macho_local_symbol_cohort_retained_current_names(&previous, &ambiguous).is_empty(),
            "a name/site cycle must not manufacture a retained root",
        );
        let unrooted_additions = vec![entry(b"new.0", 1, 0x1020, 0), entry(b"new.1", 1, 0x1030, 0)];
        assert!(
            macho_local_symbol_cohort_retained_current_names(&previous, &unrooted_additions)
                .is_empty(),
        );
    }

    #[test]
    fn macho_local_symbol_cohort_target_transition_is_exact_and_unique() {
        let entry = |name: &[u8], section, value, n_desc| MachOLocalSymbolCohortEntry {
            name: name.to_vec(),
            n_desc,
            output_section_index: section,
            output_value: value,
            output_entry_offset: None,
            string_index: None,
        };
        let plan = MachOLocalSymbolCohortPlan {
            previous_input: "previous".to_owned(),
            current_input: "current".to_owned(),
            previous: vec![entry(b"old.2", 2, 0x100, 0)],
            current: vec![entry(b"new.3", 2, 0x120, 0)],
            validated_local_symbol_renames: Vec::new(),
        };
        assert_eq!(
            macho_local_symbol_cohort_target_transition(&plan, b"old.2", b"new.3", 0x100, 0x120,),
            Some((2, 0x120, 0)),
        );
        assert!(macho_local_symbol_cohort_has_target_transition(
            std::slice::from_ref(&plan),
            "previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x120,
        ));
        assert!(!macho_local_symbol_cohort_has_target_transition(
            &[plan.clone(), plan.clone()],
            "previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x120,
        ));
        assert!(!macho_local_symbol_cohort_has_target_transition(
            std::slice::from_ref(&plan),
            "wrong-previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x120,
        ));
        assert!(!macho_local_symbol_cohort_has_target_transition(
            std::slice::from_ref(&plan),
            "previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x121,
        ));

        let mut ambiguous_previous = plan.clone();
        ambiguous_previous.previous.push(plan.previous[0].clone());
        assert_eq!(
            macho_local_symbol_cohort_target_transition(
                &ambiguous_previous,
                b"old.2",
                b"new.3",
                0x100,
                0x120,
            ),
            None,
        );

        let mut ambiguous_current = plan.clone();
        ambiguous_current.current.push(plan.current[0].clone());
        assert_eq!(
            macho_local_symbol_cohort_target_transition(
                &ambiguous_current,
                b"old.2",
                b"new.3",
                0x100,
                0x120,
            ),
            None,
        );

        for current in [
            entry(b"new.3", 3, 0x120, 0),
            entry(b"new.3", 2, 0x121, 0),
            entry(b"new.3", 2, 0x120, object::macho::N_NO_DEAD_STRIP),
        ] {
            let changed = MachOLocalSymbolCohortPlan {
                current: vec![current],
                ..plan.clone()
            };
            assert_eq!(
                macho_local_symbol_cohort_target_transition(
                    &changed, b"old.2", b"new.3", 0x100, 0x120,
                ),
                None,
            );
        }

        assert!(macho_local_data_target_has_validated_cohort_transition(
            std::slice::from_ref(&plan),
            "previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x120,
            true,
        ));
        assert!(
            !macho_local_data_target_has_validated_cohort_transition(
                std::slice::from_ref(&plan),
                "previous",
                "current",
                b"old.2",
                b"new.3",
                0x100,
                0x120,
                false,
            ),
            "a moved target requires an independently validated relocation retarget",
        );
        let equal_value = MachOLocalSymbolCohortPlan {
            current: vec![entry(b"new.3", 2, 0x100, 0)],
            ..plan.clone()
        };
        assert!(macho_local_data_target_has_validated_cohort_transition(
            std::slice::from_ref(&equal_value),
            "previous",
            "current",
            b"old.2",
            b"new.3",
            0x100,
            0x100,
            false,
        ));
    }

    #[test]
    fn macho_data_target_cohort_policy_separates_plan_and_transition_proofs() {
        assert!(macho_local_data_target_needs_cohort_plan(
            false, false, true,
        ));
        assert!(macho_local_data_target_needs_cohort_plan(true, true, false,));
        assert!(!macho_local_data_target_needs_cohort_plan(
            false, true, false,
        ));
        assert!(!macho_local_data_target_requires_cohort_transition(
            true, b"stable", b"stable", false, true,
        ));
        assert!(!macho_local_data_target_requires_cohort_transition(
            true, b"stable", b"stable", true, false,
        ));
        assert!(macho_local_data_target_requires_cohort_transition(
            true, b"old", b"new", false, true,
        ));
        assert!(macho_local_data_target_requires_cohort_transition(
            true, b"old", b"new", true, false,
        ));
        assert!(!macho_local_data_target_requires_cohort_transition(
            true, b"old", b"new", false, false,
        ));
        assert!(!macho_local_data_target_requires_cohort_transition(
            false, b"old", b"new", true, true,
        ));
    }

    #[test]
    fn published_local_macho_const_subset_requires_exact_atoms_and_dead_omissions() {
        let retarget_competing_atom = |mut object: Vec<u8>| {
            let competing = (1_u32 | 3 << 25 | 1 << 27).to_le_bytes();
            let matches = object
                .windows(competing.len())
                .enumerate()
                .filter_map(|(offset, bytes)| (bytes == competing).then_some(offset))
                .collect::<Vec<_>>();
            let [offset] = matches.as_slice() else {
                panic!("expected one relocation to the competing local atom");
            };
            object[*offset..*offset + 4].copy_from_slice(&(3_u32 << 25 | 1 << 27).to_le_bytes());
            object
        };
        let previous =
            retarget_competing_atom(test_macho_local_data_retarget_object(b"old.0", 0x12));
        let current =
            retarget_competing_atom(test_macho_local_data_retarget_object(b"new.0", 0x12));
        let previous_file = object::File::parse(previous.as_slice()).unwrap();
        let current_file = object::File::parse(current.as_slice()).unwrap();
        let previous_const = previous_file
            .sections()
            .find(|section| {
                section.segment_name().ok().flatten() == Some("__TEXT")
                    && section.name().ok() == Some("__const")
            })
            .unwrap();
        assert!(
            !macho_atom_has_incoming_relocation(
                &previous_file,
                previous_const.index(),
                0x30..previous_const.size(),
            )
            .unwrap()
        );

        let mut output = test_macho_object_with_data_section_name(
            &[0; 16],
            previous_const.data().unwrap(),
            0,
            b"__const",
        );
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let output_const = output_file.section_by_name("__const").unwrap();
        let output_section = u8::try_from(output_const.index().0).unwrap();
        let output_value = output_const.address() + 0x12;
        output = add_test_macho_local_alias(output, b"old.0", output_section, output_value);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let direct_input = hex::encode("member.o");
        let owner = RelocationRecord {
            target_symbol_id: 0,
            written_value: Some(output_value),
            target_value: output_value,
            applied_target_value: Some(output_value),
            target_name: Some(hex::encode("old.0").into()),
            target: Some(RelocationTargetRecord {
                input_file: direct_input.clone().into(),
                input: direct_input.clone().into(),
                section_index: relocation_target_record_index(previous_const.index()).unwrap(),
                section_offset: 0x12,
            }),
            input_file: direct_input.clone().into(),
            input: direct_input.clone().into(),
            section_index: 0,
            relocation_offset: 0,
            output_offset: 0,
            size: 8,
            kind: 0,
            addend: 0,
        };
        let previous_source = previous_file
            .sections()
            .find(|section| section.segment_name().ok().flatten() == Some("__DATA"))
            .unwrap();
        let current_source = current_file
            .sections()
            .find(|section| section.segment_name().ok().flatten() == Some("__DATA"))
            .unwrap();
        let direct_previous_sections = [PatchSection {
            input: direct_input.clone(),
            section_index: patch_section_record_index(&previous_file, previous_source.index())
                .unwrap(),
            section_name: Some("__DATA,__const".to_owned()),
            input_size: previous_source.size(),
            output_offset: 0,
            output_size: previous_source.size(),
            data_hash: None,
            cstring_nul_boundaries_hash: None,
        }];
        let direct_current_sections = [PatchSection {
            input: direct_input.clone(),
            section_index: patch_section_record_index(&current_file, current_source.index())
                .unwrap(),
            section_name: Some("__DATA,__const".to_owned()),
            input_size: current_source.size(),
            output_offset: 0,
            output_size: current_source.size(),
            data_hash: None,
            cstring_nul_boundaries_hash: None,
        }];

        let supplement = supplemental_macho_local_const_cohort(
            &previous,
            &current,
            &previous_file,
            &current_file,
            &output,
            &output_file,
            &direct_previous_sections,
            &direct_current_sections,
            std::slice::from_ref(&owner),
            &direct_input,
            &direct_input,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(supplement.previous.len(), 1);
        assert_eq!(supplement.previous[0].name, b"old.0");
        assert_eq!(supplement.current[0].name, b"new.0");
        assert_eq!(supplement.previous[0].output_value, output_value);
        assert_eq!(supplement.current[0].output_value, output_value);
        assert!(macho_local_symbol_cohort_retains_published_sites(
            &supplement.previous,
            &supplement.current,
        ));
        let mut current_name_owner = owner.clone();
        current_name_owner.target_name = Some(hex::encode("new.0").into());
        assert!(
            supplemental_macho_local_const_cohort(
                &previous,
                &current,
                &previous_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&current_name_owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .is_ok(),
            "an exact owner refreshed to the paired current name must remain valid",
        );
        let mut unrelated_name_owner = owner.clone();
        unrelated_name_owner.target_name = Some(hex::encode("other.0").into());
        assert!(
            supplemental_macho_local_const_cohort(
                &previous,
                &current,
                &previous_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&unrelated_name_owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err()
            .contains("has no recorded output owner"),
        );
        assert!(
            supplemental_macho_local_const_cohort(
                &previous,
                &current,
                &previous_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                &[],
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err()
            .starts_with("published local Mach-O const atom `"),
        );
        let mut wrong_section_owner = owner.clone();
        wrong_section_owner.target.as_mut().unwrap().section_index -= 1;
        assert!(
            supplemental_macho_local_const_cohort(
                &previous,
                &current,
                &previous_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&wrong_section_owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err()
            .contains("has no recorded output owner"),
        );
        let mut verified = supplement.previous.clone();
        verify_previous_macho_local_symbol_cohort(
            &output,
            &output_file,
            &[],
            &mut verified,
            &supplement.output_sites,
        )
        .unwrap();

        let archive = |identifier: &[u8], object: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        };
        let previous_identifier = b"crate-hash.cgu.previous.rcgu.o";
        let current_identifier = b"crate-hash.cgu.current.rcgu.o";
        let previous_archive = archive(previous_identifier, &previous);
        let current_archive = archive(current_identifier, &current);
        let input_file = hex::encode("input.rlib");
        let ArchiveMemberMatch::Unique(previous_member) =
            patch_archive_member_bytes(&previous_archive, previous_identifier).unwrap()
        else {
            panic!("expected previous archive member");
        };
        let ArchiveMemberMatch::Unique(current_member) =
            patch_archive_member_bytes(&current_archive, current_identifier).unwrap()
        else {
            panic!("expected current archive member");
        };
        let previous_input =
            resolved_patch_input_ref(&input_file, &input_file, previous_member).unwrap();
        let current_input =
            resolved_patch_input_ref(&input_file, &input_file, current_member).unwrap();
        let mut plan_owner = owner.clone();
        let target = plan_owner.target.as_mut().unwrap();
        target.input_file = input_file.clone().into();
        target.input = previous_input.clone().into();
        let output_text = output_file.section_by_name("__text").unwrap();
        let matched = [MatchedPatchSection {
            previous: PatchSection {
                input: previous_input.clone(),
                section_index: patch_section_record_index(&previous_file, previous_source.index())
                    .unwrap(),
                section_name: Some("__DATA,__const".to_owned()),
                input_size: previous_source.size(),
                output_offset: output_text.file_range().unwrap().0,
                output_size: previous_source.size(),
                data_hash: Some(hash_bytes(previous_source.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input.clone(),
                section_index: patch_section_record_index(&current_file, current_source.index())
                    .unwrap(),
                section_name: Some("__DATA,__const".to_owned()),
                input_size: current_source.size(),
                output_offset: output_text.file_range().unwrap().0,
                output_size: current_source.size(),
                data_hash: Some(hash_bytes(current_source.data().unwrap())),
                cstring_nul_boundaries_hash: None,
            },
        }];
        let previous_resolver = PatchInputResolver::new(&previous_archive, true).unwrap();
        let current_resolver = PatchInputResolver::new(&current_archive, true).unwrap();
        let previous_input_bytes = previous_resolver
            .resolve(
                &input_file,
                &previous_input,
                PatchInputLookup::MatchArchiveMember,
            )
            .unwrap()
            .unwrap();
        let current_input_bytes = current_resolver
            .resolve(
                &input_file,
                &current_input,
                PatchInputLookup::MatchArchiveMember,
            )
            .unwrap()
            .unwrap();
        let plan = plan_macho_local_symbol_cohort(
            std::slice::from_ref(&plan_owner),
            &[],
            &[],
            &[],
            &input_file,
            &matched[0],
            &matched,
            &previous_resolver,
            &current_resolver,
            previous_input_bytes,
            current_input_bytes,
            &previous_file,
            &current_file,
            &output,
            &output_file,
            &[],
            &[],
            &DirectMachOCguLivenessProof::default(),
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(plan.previous.len(), 1);
        assert_eq!(plan.current.len(), 1);
        assert_eq!(plan.validated_local_symbol_renames.len(), 1);
        let validated_rename = &plan.validated_local_symbol_renames[0];
        let previous_ranges = patch_ranges_with_lookup(
            &previous_archive,
            &input_file,
            matched.iter().map(|section| section.previous.clone()),
            PatchInputLookup::MatchArchiveMember,
        )
        .unwrap()
        .unwrap();
        let current_ranges = patch_ranges_with_lookup(
            &current_archive,
            &input_file,
            matched.iter().map(|section| section.current.clone()),
            PatchInputLookup::MatchArchiveMember,
        )
        .unwrap()
        .unwrap();
        let relocation_site = |file: &object::File<'_>,
                               source: object::SectionIndex,
                               target_name: &[u8],
                               archive_identifier: Vec<u8>| {
            let target = file
                .symbols()
                .find(|symbol| symbol.name_bytes().ok() == Some(target_name))
                .unwrap();
            file.section_by_index(source)
                .unwrap()
                .relocations()
                .filter(|(_, relocation)| {
                    relocation.target() == object::RelocationTarget::Symbol(target.index())
                })
                .map(|(offset, _)| ValidatedMachOLocalRelocationSite {
                    archive_identifier: archive_identifier.clone(),
                    section_index: source.0,
                    relocation_offset: offset,
                    normalize_relocation_offset: false,
                    target_symbol_index: target.index().0,
                    hash_target_symbol: false,
                    hash_unmasked_target_offset: false,
                    exact_symbol_indices: Vec::new(),
                })
                .collect::<Vec<_>>()
        };
        let previous_retarget = relocation_site(
            &previous_file,
            previous_source.index(),
            b"old.0",
            validated_rename.previous.archive_identifier.clone(),
        );
        let current_retarget = relocation_site(
            &current_file,
            current_source.index(),
            b"new.0",
            validated_rename.current.archive_identifier.clone(),
        );
        assert!(!previous_retarget.is_empty());
        assert_eq!(previous_retarget.len(), current_retarget.len());
        assert_eq!(
            validated_rename.previous.archive_identifier,
            archive_member_patch_identifier(previous_identifier),
        );
        let previous_ignored_sections = fully_masked_macho_unwind_sections(
            &previous_file,
            previous_input_bytes.file_offset,
            &previous_ranges,
        )
        .unwrap();
        assert!(
            macho_object_semantic_patch_fingerprint_with_retargets(
                previous_input_bytes.bytes,
                previous_input_bytes.file_offset,
                &previous_ranges,
                &previous_ignored_sections,
                &HashSet::new(),
                &HashSet::new(),
                true,
                true,
                true,
                &previous_retarget.iter().collect::<Vec<_>>(),
                &[&validated_rename.previous],
            )
            .is_some(),
            "the exact member-local relocation and symbol pair must be consumable",
        );
        let fingerprint = |bytes: &[u8],
                           ranges: &[std::ops::Range<usize>],
                           retargets: &[ValidatedMachOLocalRelocationSite],
                           rename: &ValidatedMachOLocalSymbolSite| {
            archive_macho_masked_local_semantic_fingerprint_with_retargets_and_renames(
                bytes,
                ranges,
                &[],
                &HashSet::new(),
                retargets,
                std::slice::from_ref(rename),
            )
            .unwrap()
        };
        assert_ne!(
            archive_macho_masked_local_semantic_fingerprint_with_retargets(
                &previous_archive,
                &previous_ranges,
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
            archive_macho_masked_local_semantic_fingerprint_with_retargets(
                &current_archive,
                &current_ranges,
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
        );
        assert_eq!(
            fingerprint(
                &previous_archive,
                &previous_ranges,
                &[],
                &validated_rename.previous,
            ),
            fingerprint(
                &current_archive,
                &current_ranges,
                &[],
                &validated_rename.current,
            ),
            "a proven supplemental rename must normalize its masked incoming relocations",
        );
        let previous_fingerprint = fingerprint(
            &previous_archive,
            &previous_ranges,
            &previous_retarget,
            &validated_rename.previous,
        );
        assert!(previous_fingerprint.is_some());
        assert_eq!(
            previous_fingerprint,
            fingerprint(
                &current_archive,
                &current_ranges,
                &current_retarget,
                &validated_rename.current,
            ),
        );
        assert!(
            direct_macho_masked_local_semantic_fingerprint_with_retargets_and_renames(
                previous_input_bytes.bytes,
                &previous_ranges
                    .iter()
                    .map(|range| {
                        range.start - previous_input_bytes.file_offset
                            ..range.end - previous_input_bytes.file_offset
                    })
                    .collect::<Vec<_>>(),
                &HashSet::new(),
                &previous_retarget,
                std::slice::from_ref(&validated_rename.previous),
            )
            .unwrap()
            .is_none(),
            "direct-object proofs must reject archive-qualified sites",
        );
        let mut previous_direct_retarget = previous_retarget.clone();
        let mut current_direct_retarget = current_retarget.clone();
        for site in previous_direct_retarget
            .iter_mut()
            .chain(&mut current_direct_retarget)
        {
            site.archive_identifier.clear();
        }
        let mut previous_direct_rename = validated_rename.previous.clone();
        previous_direct_rename.archive_identifier.clear();
        let mut current_direct_rename = validated_rename.current.clone();
        current_direct_rename.archive_identifier.clear();
        let direct_ranges = |ranges: &[std::ops::Range<usize>], file_offset: usize| {
            ranges
                .iter()
                .map(|range| range.start - file_offset..range.end - file_offset)
                .collect::<Vec<_>>()
        };
        let previous_direct_fingerprint =
            direct_macho_masked_local_semantic_fingerprint_with_retargets_and_renames(
                previous_input_bytes.bytes,
                &direct_ranges(&previous_ranges, previous_input_bytes.file_offset),
                &HashSet::new(),
                &previous_direct_retarget,
                std::slice::from_ref(&previous_direct_rename),
            )
            .unwrap();
        assert!(previous_direct_fingerprint.is_some());
        assert_eq!(
            previous_direct_fingerprint,
            direct_macho_masked_local_semantic_fingerprint_with_retargets_and_renames(
                current_input_bytes.bytes,
                &direct_ranges(&current_ranges, current_input_bytes.file_offset),
                &HashSet::new(),
                &current_direct_retarget,
                std::slice::from_ref(&current_direct_rename),
            )
            .unwrap(),
            "direct unwind proofs must compose the exact retarget and local rename",
        );
        let direct_retargets = previous_direct_retarget
            .iter()
            .cloned()
            .zip(current_direct_retarget.iter().cloned())
            .map(|(previous, current)| ValidatedMachOLocalRelocationRetarget { previous, current })
            .collect::<Vec<_>>();
        let direct_rename = ValidatedMachOLocalSymbolRename {
            previous: previous_direct_rename,
            current: current_direct_rename,
        };
        assert!(
            archive_diff_allows_changed_macho_unwind_with_local_symbol_renames(
                &previous,
                &current,
                &direct_input,
                &[MatchedPatchSection {
                    previous: direct_previous_sections[0].clone(),
                    current: direct_current_sections[0].clone(),
                }],
                &PatchInputResolver::new(&current, false).unwrap(),
                &ChangedMachOArchiveUnwindMembers {
                    members: Vec::new(),
                    previous_common_members: Vec::new(),
                    current_common_members: Vec::new(),
                    retired_entries: Vec::new(),
                    current_sections: Vec::new(),
                    previous_input_ranges: Vec::new(),
                    current_input_ranges: Vec::new(),
                },
                &[],
                &[],
                &HashSet::new(),
                &direct_retargets,
                std::slice::from_ref(&direct_rename),
            )
            .unwrap(),
            "direct unwind composition must not require an unrelated definition migration",
        );
        let mut wrong_site = validated_rename.current.clone();
        wrong_site.section_index += 1;
        assert!(
            fingerprint(
                &current_archive,
                &current_ranges,
                &current_retarget,
                &wrong_site,
            )
            .is_none()
        );
        let mut changed_current_archive = current_archive.clone();
        let (current_const_offset, _) = current_file
            .sections()
            .find(|section| {
                section.segment_name().ok().flatten() == Some("__TEXT")
                    && section.name().ok() == Some("__const")
            })
            .unwrap()
            .file_range()
            .unwrap();
        changed_current_archive
            [current_input_bytes.file_offset + usize::try_from(current_const_offset).unwrap()] ^= 1;
        assert_ne!(
            previous_fingerprint,
            fingerprint(
                &changed_current_archive,
                &current_ranges,
                &current_retarget,
                &validated_rename.current,
            ),
            "a validated local rename must not hide unrelated atom bytes",
        );
        let mut partial_current_ranges = current_ranges.clone();
        partial_current_ranges[0].end -= 1;
        assert_ne!(
            previous_fingerprint,
            fingerprint(
                &current_archive,
                &partial_current_ranges,
                &[],
                &validated_rename.current,
            ),
            "a validated local rename requires full source-section masking",
        );
        assert!(
            archive_macho_masked_local_semantic_fingerprint_with_retargets_and_renames(
                &current_archive,
                &current_ranges,
                &[],
                &HashSet::new(),
                &[],
                &[
                    validated_rename.current.clone(),
                    validated_rename.current.clone(),
                ],
            )
            .unwrap()
            .is_none(),
            "duplicate validated rename identities must be rejected",
        );
        let current_symbol_value = macho_symbol_value_field_range(
            current_input_bytes.bytes,
            object::SymbolIndex(validated_rename.current.symbol_index),
        )
        .unwrap();
        let current_symbol_value = current_input_bytes.file_offset + current_symbol_value.start
            ..current_input_bytes.file_offset + current_symbol_value.end;
        let mut moved_current_archive = current_archive.clone();
        let moved_value = read_u64_le(&moved_current_archive[current_symbol_value.clone()])
            .unwrap()
            .checked_add(1)
            .unwrap();
        moved_current_archive[current_symbol_value.clone()]
            .copy_from_slice(&moved_value.to_le_bytes());
        assert_ne!(
            previous_fingerprint,
            fingerprint(
                &moved_current_archive,
                &current_ranges,
                &[],
                &validated_rename.current,
            ),
            "a validated local rename must bind the target section offset",
        );
        let mut changed_metadata_archive = current_archive.clone();
        let n_desc = current_symbol_value.start - 2..current_symbol_value.start;
        changed_metadata_archive[n_desc]
            .copy_from_slice(&object::macho::N_NO_DEAD_STRIP.to_le_bytes());
        assert_ne!(
            previous_fingerprint,
            fingerprint(
                &changed_metadata_archive,
                &current_ranges,
                &[],
                &validated_rename.current,
            ),
            "a validated local rename must bind target metadata",
        );

        let patches =
            apply_macho_local_symbol_cohort_plans(&[plan.clone()], &output, &mut Vec::new())
                .unwrap();
        let mut migrated = output.clone();
        apply_test_output_patches(&mut migrated, &patches);
        let migrated_file = object::File::parse(migrated.as_slice()).unwrap();
        assert!(
            migrated_file
                .symbols()
                .any(|symbol| symbol.name_bytes().ok() == Some(b"new.0"))
        );
        assert!(
            !migrated_file
                .symbols()
                .any(|symbol| symbol.name_bytes().ok() == Some(b"old.0"))
        );

        let referenced = test_macho_local_data_retarget_object(b"old.0", 0x12);
        let referenced_file = object::File::parse(referenced.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &referenced,
                &current,
                &referenced_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "unpublished local Mach-O const atom has an alias, root, or incoming relocation",
        );

        let subtractor_referenced = {
            let mut object = test_macho_local_data_retarget_object(b"old.0", 0x12);
            let competing = (1_u32 | 3 << 25 | 1 << 27).to_le_bytes();
            let matches = object
                .windows(competing.len())
                .enumerate()
                .filter_map(|(offset, bytes)| (bytes == competing).then_some(offset))
                .collect::<Vec<_>>();
            let [offset] = matches.as_slice() else {
                panic!("expected one relocation to the competing local atom");
            };
            object[offset - 4..*offset].fill(0);
            object[*offset..*offset + 4]
                .copy_from_slice(&(1_u32 | 3 << 25 | 1 << 27 | 1 << 28).to_le_bytes());
            object
        };
        let subtractor_referenced_file =
            object::File::parse(subtractor_referenced.as_slice()).unwrap();
        assert!(
            macho_atom_has_incoming_relocation(
                &subtractor_referenced_file,
                previous_const.index(),
                0x30..previous_const.size(),
            )
            .unwrap()
        );
        assert_eq!(
            macho_atom_incoming_relocation_from_sections(
                &subtractor_referenced_file,
                None,
                previous_const.index(),
                0x30..previous_const.size(),
            )
            .unwrap(),
            MachOAtomIncomingRelocation::Unknown,
            "a subtractor section load must not prove its symbol's atom live",
        );
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &subtractor_referenced,
                &current,
                &subtractor_referenced_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "unpublished local Mach-O const atom has an alias, root, or incoming relocation",
        );

        let mut interior_root = add_test_macho_local_alias(
            previous.clone(),
            b"_interior_root",
            u8::try_from(previous_const.index().0).unwrap(),
            previous_const.address() + 0x38,
        );
        let root_entry = test_macho_symbol_entry_offset(&interior_root, b"_interior_root");
        interior_root[root_entry + 4] |= object::macho::N_EXT;
        interior_root[root_entry + 6..root_entry + 8].copy_from_slice(
            &(object::macho::N_ALT_ENTRY | object::macho::N_NO_DEAD_STRIP).to_le_bytes(),
        );
        let interior_root_file = object::File::parse(interior_root.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &interior_root,
                &current,
                &interior_root_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "unpublished local Mach-O const atom has an alias, root, or incoming relocation",
        );

        let unreferenced_current = {
            let mut object = current.clone();
            let primary = (3_u32 << 25 | 1 << 27).to_le_bytes();
            let matches = object
                .windows(primary.len())
                .enumerate()
                .filter_map(|(offset, bytes)| {
                    (bytes == primary
                        && offset >= 4
                        && matches!(read_u32_le(&object[offset - 4..offset]), Some(0) | Some(8)))
                    .then_some(offset)
                })
                .collect::<Vec<_>>();
            assert_eq!(matches.len(), 2);
            for offset in matches {
                object[offset..offset + 4].copy_from_slice(&(1_u32 | 3 << 25).to_le_bytes());
            }
            object
        };
        let unreferenced_current_file =
            object::File::parse(unreferenced_current.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &previous,
                &unreferenced_current,
                &previous_file,
                &unreferenced_current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "published local Mach-O const atom is not referenced by the current object",
        );

        let mut global_referenced_current = add_test_macho_local_alias(
            current.clone(),
            b"_global_alias",
            u8::try_from(previous_const.index().0).unwrap(),
            previous_const.address() + 0x12,
        );
        let global_entry =
            test_macho_symbol_entry_offset(&global_referenced_current, b"_global_alias");
        global_referenced_current[global_entry + 4] |= object::macho::N_EXT;
        let primary = (3_u32 << 25 | 1 << 27).to_le_bytes();
        let matches = global_referenced_current
            .windows(primary.len())
            .enumerate()
            .filter_map(|(offset, bytes)| {
                (bytes == primary
                    && offset >= 4
                    && matches!(
                        read_u32_le(&global_referenced_current[offset - 4..offset]),
                        Some(0) | Some(8)
                    ))
                .then_some(offset)
            })
            .collect::<Vec<_>>();
        assert_eq!(matches.len(), 2);
        for offset in matches {
            global_referenced_current[offset..offset + 4]
                .copy_from_slice(&(3_u32 | 3 << 25 | 1 << 27).to_le_bytes());
        }
        let global_referenced_current_file =
            object::File::parse(global_referenced_current.as_slice()).unwrap();
        assert_eq!(
            macho_atom_incoming_relocation_from_sections(
                &global_referenced_current_file,
                None,
                previous_const.index(),
                0x12..0x30,
            )
            .unwrap(),
            MachOAtomIncomingRelocation::Unknown,
            "a public alias may resolve outside this object's subsection",
        );

        let section_referenced_current = {
            let mut object = current.clone();
            let primary = (3_u32 << 25 | 1 << 27).to_le_bytes();
            let matches = object
                .windows(primary.len())
                .enumerate()
                .filter_map(|(offset, bytes)| {
                    (bytes == primary
                        && offset >= 4
                        && matches!(read_u32_le(&object[offset - 4..offset]), Some(0) | Some(8)))
                    .then_some(offset)
                })
                .collect::<Vec<_>>();
            assert_eq!(matches.len(), 2);
            for offset in matches {
                object[offset..offset + 4].copy_from_slice(&(2_u32 | 3 << 25).to_le_bytes());
            }
            object
        };
        let section_referenced_current_file =
            object::File::parse(section_referenced_current.as_slice()).unwrap();
        assert_eq!(
            macho_atom_incoming_relocation_from_sections(
                &section_referenced_current_file,
                None,
                previous_const.index(),
                0x12..0x30,
            )
            .unwrap(),
            MachOAtomIncomingRelocation::Unknown,
            "loading a section must not prove either contained atom live",
        );
        assert_eq!(
            macho_atom_incoming_relocation_from_sections(
                &section_referenced_current_file,
                None,
                previous_const.index(),
                0x30..previous_const.size(),
            )
            .unwrap(),
            MachOAtomIncomingRelocation::Unknown,
            "loading a section must not prove either contained atom live",
        );
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &previous,
                &section_referenced_current,
                &previous_file,
                &section_referenced_current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "published local Mach-O const atom is not referenced by the current object",
        );

        let page_current_reference = {
            let mut object = current.clone();
            let primary = (3_u32 << 25 | 1 << 27).to_le_bytes();
            let matches = object
                .windows(primary.len())
                .enumerate()
                .filter_map(|(offset, bytes)| {
                    (bytes == primary
                        && offset >= 4
                        && matches!(read_u32_le(&object[offset - 4..offset]), Some(0) | Some(8)))
                    .then_some(offset)
                })
                .collect::<Vec<_>>();
            assert_eq!(matches.len(), 2);
            for offset in matches {
                object[offset..offset + 4]
                    .copy_from_slice(&(3_u32 << 25 | 1 << 27 | 3 << 28).to_le_bytes());
            }
            object
        };
        let page_current_file = object::File::parse(page_current_reference.as_slice()).unwrap();
        assert!(
            supplemental_macho_local_const_cohort(
                &previous,
                &page_current_reference,
                &previous_file,
                &page_current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap()
            .is_some(),
            "PAGE21/PAGEOFF12 symbol references must prove the target atom live",
        );

        let mut addend_source = [0_u8; 16];
        addend_source[..8].copy_from_slice(&(0x30_i64 - 0x12).to_le_bytes());
        let addend_referenced = retarget_competing_atom(
            test_macho_local_data_retarget_object_with_source(b"old.0", 0x12, &addend_source),
        );
        let addend_referenced_file = object::File::parse(addend_referenced.as_slice()).unwrap();
        assert!(
            supplemental_macho_local_const_cohort(
                &addend_referenced,
                &current,
                &addend_referenced_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap()
            .is_some(),
            "a symbol addend must not change the referenced GC subsection",
        );

        let mut indivisible = previous.clone();
        indivisible[24..28].fill(0);
        let indivisible_file = object::File::parse(indivisible.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &indivisible,
                &current,
                &indivisible_file,
                &current_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "unpublished local Mach-O const atoms require subsections-via-symbols",
        );

        let moved = retarget_competing_atom(test_macho_local_data_retarget_object(b"new.0", 0x13));
        let moved_file = object::File::parse(moved.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &previous,
                &moved,
                &previous_file,
                &moved_file,
                &output,
                &output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "published local Mach-O const cohort changed atom boundaries or metadata",
        );

        let mut changed_output = output.clone();
        let output_offset = macho_output_file_offset_for_address(&output_file, output_value, 1)
            .unwrap()
            .unwrap() as usize;
        changed_output[output_offset] ^= 1;
        let changed_output_file = object::File::parse(changed_output.as_slice()).unwrap();
        assert_eq!(
            supplemental_macho_local_const_cohort(
                &previous,
                &current,
                &previous_file,
                &current_file,
                &changed_output,
                &changed_output_file,
                &direct_previous_sections,
                &direct_current_sections,
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap_err(),
            "published local Mach-O const atom output bytes changed",
        );

        let no_local_previous = test_macho_object_with_text_const(b"text", b"old", false, false);
        let no_local_current = test_macho_object_with_text_const(b"text", b"new", false, false);
        let no_local_previous_file = object::File::parse(no_local_previous.as_slice()).unwrap();
        let no_local_current_file = object::File::parse(no_local_current.as_slice()).unwrap();
        assert!(
            supplemental_macho_local_const_cohort(
                &no_local_previous,
                &no_local_current,
                &no_local_previous_file,
                &no_local_current_file,
                &output,
                &output_file,
                &[],
                &[],
                std::slice::from_ref(&owner),
                &direct_input,
                &direct_input,
            )
            .unwrap()
            .unwrap()
            .is_none(),
            "candidate-free const sections must not introduce a new fallback",
        );
    }

    #[test]
    fn published_local_macho_cohort_requires_rooted_atom_reachability() {
        assert!(macho_local_cohort_symbol_is_root(
            object::macho::N_NO_DEAD_STRIP,
        ));
        assert!(!macho_local_cohort_symbol_is_root(
            object::macho::N_NO_DEAD_STRIP | object::macho::N_ALT_ENTRY,
        ));
        assert!(!macho_local_cohort_relocation_follows_target(
            object::macho::ARM64_RELOC_SUBTRACTOR,
        ));
        assert!(!macho_local_cohort_relocation_follows_target(
            object::macho::ARM64_RELOC_ADDEND,
        ));
        assert!(macho_local_cohort_relocation_follows_target(
            object::macho::ARM64_RELOC_UNSIGNED,
        ));
        let previous_member = PatchInputBytes {
            bytes: b"same",
            file_offset: 0,
            archive_identifier: Some(b"old"),
        };
        let current_member = PatchInputBytes {
            bytes: b"same",
            file_offset: 32,
            archive_identifier: Some(b"new"),
        };
        assert!(macho_local_cohort_source_member_is_unchanged(
            Some(previous_member),
            Some(current_member),
        ));
        let changed_member = PatchInputBytes {
            bytes: b"changed",
            ..current_member
        };
        assert!(!macho_local_cohort_source_member_is_unchanged(
            Some(previous_member),
            Some(changed_member),
        ));

        let section = object::SectionIndex(1);
        let boundaries = HashMap::from([(section, vec![0, 4, 8])]);
        let roots = HashSet::from([(section, 0)]);
        let disconnected_cycle = HashMap::from([
            ((section, 4), vec![(section, 8)]),
            ((section, 8), vec![(section, 4)]),
        ]);
        assert!(!macho_local_cohort_atom_graph_is_complete(
            &boundaries,
            &roots,
            &disconnected_cycle,
        ));
        let reachable = reachable_macho_local_cohort_atoms(&roots, &disconnected_cycle);
        assert!(required_macho_local_cohort_atoms_are_reachable(
            &[],
            &reachable,
        ));
        assert!(required_macho_local_cohort_atoms_are_reachable(
            &[(section, 0)],
            &reachable,
        ));
        assert!(
            !required_macho_local_cohort_atoms_are_reachable(&[(section, 4)], &reachable),
            "a changed current entry must not inherit liveness when its atom is unreachable",
        );

        let unreferenced_temporary_boundary = HashMap::from([((section, 0), Vec::new())]);
        assert!(!macho_local_cohort_atom_graph_is_complete(
            &HashMap::from([(section, vec![0, 4])]),
            &roots,
            &unreferenced_temporary_boundary,
        ));

        let rooted = HashMap::from([
            ((section, 0), vec![(section, 4)]),
            ((section, 4), vec![(section, 8)]),
        ]);
        assert!(macho_local_cohort_atom_graph_is_complete(
            &boundaries,
            &roots,
            &rooted,
        ));

        let mut recorded_roots = HashSet::from([(section, 0)]);
        let mut recorded_graph = HashMap::from([((section, 0), vec![(section, 4)])]);
        add_macho_local_cohort_roots_to_fixed_point(
            &mut recorded_roots,
            &mut recorded_graph,
            &[((section, 8), (section, 12)), ((section, 4), (section, 8))],
            |_| Ok(HashSet::new()),
        )
        .unwrap();
        assert!(
            reachable_macho_local_cohort_atoms(&recorded_roots, &recorded_graph)
                .contains(&(section, 12)),
            "recorded caller edges must reach a fixed point independent of input order",
        );

        let mut graph = HashMap::from([((section, 0), vec![(section, 4)])]);
        let mut mixed_roots = HashSet::from([(section, 0)]);
        add_macho_local_cohort_roots_to_fixed_point(
            &mut mixed_roots,
            &mut graph,
            &[((section, 8), (section, 12))],
            |reachable| {
                Ok(if reachable.contains(&(section, 4)) {
                    HashSet::from([(section, 8)])
                } else {
                    HashSet::new()
                })
            },
        )
        .unwrap();
        assert!(
            reachable_macho_local_cohort_atoms(&mixed_roots, &graph).contains(&(section, 12)),
            "recorded caller edges must propagate roots added by carried data",
        );
    }

    #[test]
    fn deferred_local_macho_cohort_liveness_requires_a_planned_whole_member_replan() {
        for replan in [
            WholeMemberMachOLocalCohortReplan::Skipped,
            WholeMemberMachOLocalCohortReplan::NoChange,
        ] {
            assert_eq!(
                validate_deferred_macho_local_cohort_liveness(true, replan).unwrap_err(),
                MACHO_LOCAL_COHORT_LIVENESS_REQUIRED,
            );
        }
        assert!(
            validate_deferred_macho_local_cohort_liveness(
                true,
                WholeMemberMachOLocalCohortReplan::Planned,
            )
            .is_ok()
        );
        assert!(
            validate_deferred_macho_local_cohort_liveness(
                false,
                WholeMemberMachOLocalCohortReplan::Skipped,
            )
            .is_ok()
        );
    }

    #[test]
    fn carried_macho_data_requires_an_exact_incoming_record() {
        let bytes = test_macho_object_with_text_relocation(&[0; 4], &[0; 8]);
        let file = object::File::parse(bytes.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let data = file.section_by_name("__data").unwrap();
        let (source_offset, relocation) = text.relocations().next().unwrap();
        let object::RelocationFlags::MachO {
            r_type,
            r_pcrel,
            r_length,
        } = relocation.flags()
        else {
            panic!("expected Mach-O relocation");
        };
        let input = "input";
        let owner = MatchedPatchSection {
            previous: PatchSection {
                input: input.to_owned(),
                section_index: patch_section_record_index(&file, text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: 0x100,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: input.to_owned(),
                section_index: patch_section_record_index(&file, text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: 0x100,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        };
        let target_value = 0x1000;
        let mut record = RelocationRecord {
            target_symbol_id: 7,
            written_value: Some(0),
            target_value,
            applied_target_value: Some(target_value),
            target_name: Some(hex::encode("_data").into()),
            target: Some(RelocationTargetRecord {
                input_file: input.into(),
                input: input.into(),
                section_index: relocation_target_record_index(data.index()).unwrap(),
                section_offset: 0,
            }),
            input_file: input.into(),
            input: input.into(),
            section_index: owner.previous.section_index,
            relocation_offset: source_offset,
            output_offset: owner.previous.output_offset + source_offset,
            size: 4,
            kind: encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
                r_address: source_offset as u32,
                r_symbolnum: 0,
                r_pcrel,
                r_length,
                r_extern: true,
                r_type,
            }),
            addend: relocation.addend(),
        };
        let exact = |record: &RelocationRecord| {
            macho_carried_data_incoming_record_is_exact(
                record,
                input,
                &owner,
                source_offset,
                &relocation,
                input,
                data.index(),
                0,
                b"_data",
                target_value,
                false,
            )
            .unwrap()
        };
        assert!(exact(&record));

        let original = record.clone();
        let mut rejects = Vec::new();
        record.input_file = "other".into();
        rejects.push(record.clone());
        record = original.clone();
        record.input = "other".into();
        rejects.push(record.clone());
        record = original.clone();
        record.section_index += 1;
        rejects.push(record.clone());
        record = original.clone();
        record.relocation_offset += 4;
        rejects.push(record.clone());
        record = original.clone();
        record.output_offset += 4;
        rejects.push(record.clone());
        record = original.clone();
        record.size = 8;
        rejects.push(record.clone());
        record = original.clone();
        let raw = decode_macho_aarch64_relocation_kind(record.kind).unwrap();
        record.kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_extern: false,
            ..raw
        });
        rejects.push(record.clone());
        record = original.clone();
        record.addend += 1;
        rejects.push(record.clone());
        record = original.clone();
        record.target_name = None;
        rejects.push(record.clone());
        record = original.clone();
        record.target_name = Some(hex::encode("_other").into());
        rejects.push(record.clone());
        record = original.clone();
        record.target_value += 1;
        rejects.push(record.clone());
        record = original.clone();
        record.applied_target_value = None;
        rejects.push(record.clone());
        record = original.clone();
        record.applied_target_value = Some(target_value + 1);
        rejects.push(record.clone());
        record = original.clone();
        record.written_value = None;
        rejects.push(record.clone());
        record = original.clone();
        record.target = None;
        rejects.push(record.clone());
        record = original.clone();
        record.target.as_mut().unwrap().input_file = "other".into();
        rejects.push(record.clone());
        record = original.clone();
        record.target.as_mut().unwrap().section_index += 1;
        rejects.push(record.clone());
        record = original.clone();
        record.target.as_mut().unwrap().section_offset = 1;
        rejects.push(record.clone());
        record = original;
        record.target.as_mut().unwrap().input = "other".into();
        rejects.push(record);
        assert!(rejects.iter().all(|record| !exact(record)));
    }

    #[test]
    fn carried_macho_data_requires_the_exact_previous_output_word() {
        let expected = 0x1234_5678_u64;
        let output = test_macho_object(&[0; 4], &expected.to_le_bytes(), 0);
        let file = object::File::parse(output.as_slice()).unwrap();
        let data = file.section_by_name("__data").unwrap();
        let (output_offset, _) = data.file_range().unwrap();
        assert!(macho_carried_data_output_word_is_exact(
            &output,
            output_offset,
            expected,
        ));
        assert!(!macho_carried_data_output_word_is_exact(
            &output,
            output_offset,
            expected + 1,
        ));
        assert!(!macho_carried_data_output_word_is_exact(
            &output,
            output.len() as u64,
            expected,
        ));
    }

    #[test]
    fn carried_macho_data_parser_is_scoped_to_regular_data() {
        let mut bytes = test_macho_local_data_retarget_object(b"local", 0x12);
        let mut data_name = [0; 16];
        data_name[..b"__data".len()].copy_from_slice(b"__data");
        let mut const_name = [0; 16];
        const_name[..b"__const".len()].copy_from_slice(b"__const");
        let mut data_segment = [0; 16];
        data_segment[..b"__DATA".len()].copy_from_slice(b"__DATA");
        let section_header = bytes
            .windows(32)
            .position(|window| window[..16] == const_name && window[16..] == data_segment)
            .unwrap();
        bytes[section_header..section_header + 16].copy_from_slice(&data_name);
        let file = object::File::parse(bytes.as_slice()).unwrap();
        let data = file.section_by_name("__data").unwrap();
        assert!(macho_carried_data_section_is_non_gc(&data));
        assert_eq!(
            macho_aarch64_unsigned_data_relocation_contexts(
                &file,
                &data,
                data.data().unwrap(),
                b"__DATA",
                b"__data",
            )
            .unwrap()
            .len(),
            2,
        );
        assert!(
            macho_aarch64_data_relocation_contexts(&file, &data, data.data().unwrap()).is_none()
        );

        let mut executable = bytes.clone();
        let flags_offset = section_header + 64;
        let flags = read_u32_le(&executable[flags_offset..flags_offset + 4]).unwrap();
        executable[flags_offset..flags_offset + 4]
            .copy_from_slice(&(flags | object::macho::S_ATTR_SOME_INSTRUCTIONS).to_le_bytes());
        let executable_file = object::File::parse(executable.as_slice()).unwrap();
        let executable_data = executable_file.section_by_name("__data").unwrap();
        assert!(!macho_carried_data_section_is_non_gc(&executable_data));

        let original = test_macho_local_data_retarget_object(b"local", 0x12);
        let original_file = object::File::parse(original.as_slice()).unwrap();
        let data_const = original_file
            .sections()
            .find(|section| {
                section.segment_name_bytes().ok().flatten() == Some(b"__DATA")
                    && section.name_bytes().ok() == Some(b"__const")
            })
            .unwrap();
        assert!(!macho_carried_data_section_is_non_gc(&data_const));
    }

    #[test]
    fn carried_macho_data_requires_one_reachable_global_on_one_base() {
        assert_eq!(macho_carried_data_global_root_base(&[]), None);
        assert_eq!(
            macho_carried_data_global_root_base(&[(0x1000, false), (0x1000, false)]),
            None,
        );
        assert_eq!(
            macho_carried_data_global_root_base(&[(0x1000, true), (0x1000, false)]),
            Some(0x1000),
        );
        assert_eq!(
            macho_carried_data_global_root_base(
                &[(0x1000, true), (0x1000, true), (0x1000, false),]
            ),
            Some(0x1000),
            "multiple independent callers are unambiguous",
        );
        assert_eq!(
            macho_carried_data_global_root_base(&[(0x1000, true), (0x2000, false)]),
            None,
        );
    }

    #[test]
    fn carried_macho_data_requires_an_exact_record_or_complete_rematerialization() {
        assert!(macho_carried_data_incoming_is_proven(1, false));
        assert!(macho_carried_data_incoming_is_proven(0, true));
        assert!(macho_carried_data_incoming_is_proven(2, true));
        assert!(!macho_carried_data_incoming_is_proven(0, false));
        assert!(!macho_carried_data_incoming_is_proven(2, false));
    }

    #[test]
    fn published_local_macho_cohort_rejects_occupied_or_exhausted_reserves() {
        let mut output = test_macho_object(&[0; 16], &[0; 16], 0);
        let entry = test_macho_symbol_entry_offset(&output, b"_text");
        output[entry + 4] = object::macho::N_SECT;
        let (mut output, reserves) = add_test_macho_symbol_table_reserves(output, 1, 32);
        let previous = vec![test_macho_local_cohort_entry(&output, b"_text")];
        let added = MachOLocalSymbolCohortEntry {
            name: b"local.added".to_vec(),
            n_desc: 0,
            output_section_index: previous[0].output_section_index,
            output_value: previous[0].output_value + 4,
            output_entry_offset: None,
            string_index: None,
        };
        let plan = MachOLocalSymbolCohortPlan {
            previous_input: "a".to_owned(),
            current_input: "b".to_owned(),
            previous: previous.clone(),
            current: [
                MachOLocalSymbolCohortEntry {
                    output_entry_offset: None,
                    string_index: None,
                    ..previous[0].clone()
                },
                added,
            ]
            .into(),
            validated_local_symbol_renames: Vec::new(),
        };

        let mut exhausted = reserves
            .iter()
            .filter(|range| {
                range.output_section_id == crate::output_section_id::STRTAB.as_usize() as u32
            })
            .cloned()
            .collect();
        assert!(
            apply_macho_local_symbol_cohort_plans(&[plan.clone()], &output, &mut exhausted)
                .err()
                .unwrap()
                .contains("insufficient incremental reserve for Mach-O local nlist")
        );

        let symbol_reserve = reserves
            .iter()
            .find(|range| {
                range.output_section_id == crate::output_section_id::SYMTAB_GLOBAL.as_usize() as u32
            })
            .unwrap();
        output[symbol_reserve.output_offset as usize] = 1;
        let pending_retirement = SectionPatch {
            output_offset: symbol_reserve.output_offset,
            size: 16,
            data: vec![0; 16],
            deferred_relocation: None,
            preserve_ranges: Vec::new(),
            adjustments: Vec::new(),
        };
        let staged_output = materialize_pending_macho_symbol_table_patches(
            &output,
            std::slice::from_ref(&pending_retirement),
        )
        .unwrap();
        let mut recycled = reserves.clone();
        assert!(
            apply_macho_local_symbol_cohort_plans(&[plan.clone()], &staged_output, &mut recycled,)
                .is_ok()
        );

        let mut occupied = reserves.clone();
        assert!(
            apply_macho_local_symbol_cohort_plans(&[plan], &output, &mut occupied)
                .err()
                .unwrap()
                .starts_with("Mach-O local symbol allocation for")
        );
        assert_eq!(occupied, reserves);
    }

    #[test]
    fn published_local_macho_cohorts_reject_cross_plan_name_collisions() {
        let mut output = test_macho_object(&[0; 16], &[0; 16], 0);
        for name in [b"_text".as_slice(), b"_data".as_slice()] {
            let entry = test_macho_symbol_entry_offset(&output, name);
            output[entry + 4] = object::macho::N_SECT;
        }
        let (output, mut reserves) = add_test_macho_symbol_table_reserves(output, 2, 64);
        let previous_text = test_macho_local_cohort_entry(&output, b"_text");
        let previous_data = test_macho_local_cohort_entry(&output, b"_data");
        let current = |previous: &MachOLocalSymbolCohortEntry| MachOLocalSymbolCohortEntry {
            name: b"local.same".to_vec(),
            output_entry_offset: None,
            string_index: None,
            ..previous.clone()
        };
        let plans = [
            MachOLocalSymbolCohortPlan {
                previous_input: "a1".to_owned(),
                current_input: "b1".to_owned(),
                previous: vec![previous_text.clone()],
                current: vec![current(&previous_text)],
                validated_local_symbol_renames: Vec::new(),
            },
            MachOLocalSymbolCohortPlan {
                previous_input: "a2".to_owned(),
                current_input: "b2".to_owned(),
                previous: vec![previous_data.clone()],
                current: vec![current(&previous_data)],
                validated_local_symbol_renames: Vec::new(),
            },
        ];
        assert_eq!(
            apply_macho_local_symbol_cohort_plans(&plans, &output, &mut reserves)
                .err()
                .unwrap(),
            "published local Mach-O cohorts collide by name"
        );

        let repeated = [
            MachOLocalSymbolCohortPlan {
                previous_input: "a1".to_owned(),
                current_input: "b1".to_owned(),
                previous: vec![previous_text.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"GCC_except_table0".to_vec(),
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_text.clone()
                }],
                validated_local_symbol_renames: Vec::new(),
            },
            MachOLocalSymbolCohortPlan {
                previous_input: "a2".to_owned(),
                current_input: "b2".to_owned(),
                previous: vec![previous_data.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"GCC_except_table0".to_vec(),
                    output_section_index: previous_text.output_section_index,
                    output_value: previous_text.output_value + 8,
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_data.clone()
                }],
                validated_local_symbol_renames: Vec::new(),
            },
        ];
        let mut repeated_reserves = reserves.clone();
        assert!(
            apply_macho_local_symbol_cohort_plans(&repeated, &output, &mut repeated_reserves,)
                .is_ok(),
            "ordinary repeated exception labels at distinct owned sites must compose",
        );

        let shared_previous = [
            MachOLocalSymbolCohortPlan {
                previous_input: "a1".to_owned(),
                current_input: "b1".to_owned(),
                previous: vec![previous_text.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"local.one".to_vec(),
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_text.clone()
                }],
                validated_local_symbol_renames: Vec::new(),
            },
            MachOLocalSymbolCohortPlan {
                previous_input: "a2".to_owned(),
                current_input: "b2".to_owned(),
                previous: vec![previous_text.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"local.two".to_vec(),
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_text.clone()
                }],
                validated_local_symbol_renames: Vec::new(),
            },
        ];
        assert_eq!(
            apply_macho_local_symbol_cohort_plans(&shared_previous, &output, &mut reserves)
                .err()
                .unwrap(),
            "published local Mach-O cohorts share an output nlist"
        );

        let shared_site = [
            MachOLocalSymbolCohortPlan {
                previous_input: "a1".to_owned(),
                current_input: "b1".to_owned(),
                previous: vec![previous_text.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"local.one".to_vec(),
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_text.clone()
                }],
                validated_local_symbol_renames: Vec::new(),
            },
            MachOLocalSymbolCohortPlan {
                previous_input: "a2".to_owned(),
                current_input: "b2".to_owned(),
                previous: vec![previous_data.clone()],
                current: vec![MachOLocalSymbolCohortEntry {
                    name: b"local.two".to_vec(),
                    output_section_index: previous_text.output_section_index,
                    output_value: previous_text.output_value,
                    output_entry_offset: None,
                    string_index: None,
                    ..previous_data
                }],
                validated_local_symbol_renames: Vec::new(),
            },
        ];
        assert_eq!(
            apply_macho_local_symbol_cohort_plans(&shared_site, &output, &mut reserves)
                .err()
                .unwrap(),
            "published local Mach-O cohorts alias an output site"
        );
    }

    #[test]
    fn published_local_macho_cohort_validates_owned_output_symbol_patches() {
        let mut output = test_macho_object(&[0; 16], &[0; 16], 0);
        let output_entry = test_macho_symbol_entry_offset(&output, b"_text");
        output[output_entry + 4] = object::macho::N_SECT;
        let previous = test_macho_local_cohort_entry(&output, b"_text");
        let current = MachOLocalSymbolCohortEntry {
            output_value: previous.output_value + 4,
            output_entry_offset: None,
            string_index: None,
            ..previous.clone()
        };
        let cohort = MachOLocalSymbolCohortPlan {
            previous_input: "a".to_owned(),
            current_input: "b".to_owned(),
            previous: vec![previous.clone()],
            current: vec![current.clone()],
            validated_local_symbol_renames: Vec::new(),
        };
        let owned = RelocationTargetSymbolPatch {
            target_name: hex::encode(b"_text"),
            previous_target_value: previous.output_value,
            target_value: current.output_value,
            allow_missing: true,
            source: "test",
        };
        assert!(
            macho_local_symbol_cohort_owns_output_symbol_patch(
                std::slice::from_ref(&cohort),
                &owned,
                &output,
            )
            .unwrap()
        );
        let conflicting = RelocationTargetSymbolPatch {
            target_value: 24,
            ..owned
        };
        assert_eq!(
            macho_local_symbol_cohort_owns_output_symbol_patch(&[cohort], &conflicting, &output,)
                .unwrap_err(),
            "published local Mach-O output-symbol patch conflicts with its cohort"
        );
    }

    #[test]
    fn published_local_macho_cohort_does_not_own_same_name_global_symbol_patch() {
        let output = test_macho_object(&[0; 16], &[0; 16], 0);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let global = output_file
            .symbols()
            .find(|symbol| symbol.name_bytes().ok() == Some(b"_text") && symbol.is_global())
            .unwrap();
        let section_index = u8::try_from(global.section_index().unwrap().0).unwrap();
        let output_value = global.address();
        drop(output_file);
        let output = add_test_macho_local_alias(output, b"_text", section_index, output_value);
        let output_file = object::File::parse(output.as_slice()).unwrap();
        let local = output_file
            .symbols()
            .find(|symbol| symbol.name_bytes().ok() == Some(b"_text") && !symbol.is_global())
            .unwrap();
        let local_range = macho_symbol_entry_range(
            &output,
            macho_symbol_table_offset_for_recycling(&output).unwrap(),
            local.index().0,
        )
        .unwrap();
        let previous = MachOLocalSymbolCohortEntry {
            name: b"_text".to_vec(),
            n_desc: 0,
            output_section_index: section_index,
            output_value,
            output_entry_offset: Some(local_range.start as u64),
            string_index: read_u32_le(&output[local_range.start..local_range.start + 4]),
        };
        let current = MachOLocalSymbolCohortEntry {
            output_value: output_value + 4,
            output_entry_offset: None,
            string_index: None,
            ..previous.clone()
        };
        let cohort = MachOLocalSymbolCohortPlan {
            previous_input: "a".to_owned(),
            current_input: "b".to_owned(),
            previous: vec![previous],
            current: vec![current],
            validated_local_symbol_renames: Vec::new(),
        };
        let global_patch = RelocationTargetSymbolPatch {
            target_name: hex::encode(b"_text"),
            previous_target_value: output_value,
            target_value: output_value + 4,
            allow_missing: false,
            source: "global test",
        };

        assert_eq!(
            macho_local_symbol_cohort_owns_output_symbol_patch(&[cohort], &global_patch, &output,)
                .unwrap_err(),
            "published local Mach-O output-symbol patch has ambiguous exact nlist ownership",
        );
    }

    #[test]
    fn published_local_macho_cohort_updates_the_final_reserved_range_owner() {
        let range = |offset| ReservedRangeRecord {
            output_section_id: crate::output_section_id::STRTAB.as_usize() as u32,
            alignment_exponent: 0,
            output_offset: offset,
            size: 1,
        };
        let mut changed_unwind = vec![range(1)];
        let mut added = vec![range(2)];
        let mut definition = vec![range(3)];
        let mut text = vec![range(4)];
        let mut base = vec![range(5)];
        select_macho_local_symbol_cohort_reserved_ranges(
            Some(&mut changed_unwind),
            Some(&mut added),
            Some(&mut definition),
            Some(&mut text),
            &mut base,
        )
        .push(range(6));
        assert_eq!(changed_unwind, vec![range(1), range(6)]);
        assert_eq!(added, vec![range(2)]);
        assert_eq!(definition, vec![range(3)]);
        assert_eq!(text, vec![range(4)]);
        assert_eq!(base, vec![range(5)]);
    }

    fn test_macho_chained_fixup_table(page_start: u16) -> Vec<u8> {
        let mut table = vec![0; 128];
        let starts_offset = 32;
        let segment_offset = 24;
        let segment_start = starts_offset + segment_offset;
        write_macho_chained_fixup_u32(&mut table, 0, 0).unwrap();
        write_macho_chained_fixup_u32(&mut table, 4, starts_offset as u32).unwrap();
        write_macho_chained_fixup_u32(
            &mut table,
            starts_offset,
            crate::macho::DEFAULT_SEGMENT_COUNT as u32,
        )
        .unwrap();
        write_macho_chained_fixup_u32(
            &mut table,
            starts_offset + 4 * (MACHO_DATA_SEGMENT_CHAIN_INDEX + 1),
            segment_offset as u32,
        )
        .unwrap();
        write_macho_chained_fixup_u32(&mut table, segment_start, 24).unwrap();
        write_macho_chained_fixup_u16(
            &mut table,
            segment_start + 4,
            crate::macho::MACHO_PAGE_SIZE as u16,
        )
        .unwrap();
        write_macho_chained_fixup_u16(
            &mut table,
            segment_start + 6,
            MACHO_CHAINED_PTR_FORMAT_64_OFFSET,
        )
        .unwrap();
        write_macho_chained_fixup_u64(&mut table, segment_start + 8, 0x4000).unwrap();
        write_macho_chained_fixup_u16(&mut table, segment_start + 20, 1).unwrap();
        write_macho_chained_fixup_u16(&mut table, segment_start + 22, page_start).unwrap();
        table
    }

    #[test]
    fn macho_chained_fixup_slots_follow_next_strides() {
        let data_address = crate::macho::MACHO_START_MEM_ADDRESS + 0x4000;
        let data_file_offset = 0x100;
        let mut output = vec![0; data_file_offset + crate::macho::MACHO_PAGE_SIZE as usize];
        let first = encode_incremental_macho_chained_rebase(data_address + 0x100, 4).unwrap();
        let second = encode_incremental_macho_chained_rebase(data_address + 0x200, 0).unwrap();
        output[data_file_offset + 0x20..data_file_offset + 0x28]
            .copy_from_slice(&first.to_le_bytes());
        output[data_file_offset + 0x30..data_file_offset + 0x38]
            .copy_from_slice(&second.to_le_bytes());

        let slots = read_macho_chained_fixup_slots(
            &output,
            &test_macho_chained_fixup_table(0x20),
            data_address,
            crate::macho::MACHO_PAGE_SIZE,
            data_file_offset as u64,
            crate::macho::MACHO_PAGE_SIZE,
        )
        .unwrap();

        assert_eq!(
            slots
                .iter()
                .map(|slot| (slot.address, slot.output_offset, slot.value))
                .collect::<Vec<_>>(),
            vec![
                (data_address + 0x20, (data_file_offset + 0x20) as u64, first),
                (
                    data_address + 0x30,
                    (data_file_offset + 0x30) as u64,
                    second
                ),
            ]
        );
    }

    #[test]
    fn macho_chained_fixup_slots_allow_trailing_data_pages() {
        let data_address = crate::macho::MACHO_START_MEM_ADDRESS + 0x4000;
        let data_file_offset = 0x100;
        let mut output = vec![0; data_file_offset + crate::macho::MACHO_PAGE_SIZE as usize];
        let value = encode_incremental_macho_chained_rebase(data_address + 0x100, 0).unwrap();
        output[data_file_offset + 0x20..data_file_offset + 0x28]
            .copy_from_slice(&value.to_le_bytes());

        let slots = read_macho_chained_fixup_slots(
            &output,
            &test_macho_chained_fixup_table(0x20),
            data_address,
            crate::macho::MACHO_PAGE_SIZE * 3,
            data_file_offset as u64,
            crate::macho::MACHO_PAGE_SIZE,
        )
        .unwrap();

        assert_eq!(slots.len(), 1);
        assert_eq!(slots[0].address, data_address + 0x20);
    }

