    #[test]
    fn replacement_macho_unwind_entries_require_exact_owned_ranges() {
        let entry = |function_offset, length, encoding| crate::macho_writer::UnwindInfoEntry {
            function_offset,
            length,
            encoding,
            personality_offset: None,
            lsda_offset: None,
        };
        let previous = vec![
            entry(0x100, 0x20, ADDED_MACHO_UNWIND_MODE_DWARF),
            entry(0x120, 0xe0, 0),
            entry(0x200, 0x30, 0x0200_0000),
        ];
        let retired = MachOUnwindFunctionIdentity {
            function_offset: 0x100,
            length: 0x20,
        };
        let replacement = entry(0x100, 0x28, 0x0400_0000);

        assert_eq!(
            merge_macho_unwind_info_entries(previous.clone(), &[retired], vec![replacement])
                .unwrap(),
            vec![replacement, previous[2]],
        );
        assert!(
            merge_macho_unwind_info_entries(
                previous.clone(),
                &[MachOUnwindFunctionIdentity {
                    function_offset: 0x100,
                    length: 0x18,
                }],
                vec![replacement],
            )
            .unwrap_err()
            .contains("partially overlaps"),
        );
        assert!(
            merge_macho_unwind_info_entries(
                previous.clone(),
                &[MachOUnwindFunctionIdentity {
                    function_offset: 0x180,
                    length: 0x10,
                }],
                vec![replacement],
            )
            .unwrap_err()
            .contains("does not match exactly one"),
        );
        assert!(
            merge_macho_unwind_info_entries(
                previous.clone(),
                &[retired, retired],
                vec![replacement],
            )
            .unwrap_err()
            .contains("duplicate identity"),
        );
        assert!(
            merge_macho_unwind_info_entries(
                vec![previous[0], previous[0], previous[2]],
                &[retired],
                vec![replacement],
            )
            .unwrap_err()
            .contains("does not match exactly one"),
        );
        assert!(
            merge_macho_unwind_info_entries(
                previous,
                &[retired],
                vec![entry(0x1f0, 0x20, 0x0400_0000)],
            )
            .unwrap_err()
            .contains("overlaps an existing live entry"),
        );
    }

    #[test]
    fn macho_archive_unwind_versions_accept_exact_producer_reserves() {
        let mut output = test_macho_unwind_output(0x1000);
        let section_end = output.eh_frame_offset + output.eh_frame_size;
        let full_link_start = output.eh_frame_offset;
        let incremental_start = full_link_start + 8;
        let common_members = vec![MachOArchiveMemberIdentity {
            normalized_identifier: b"common.rcgu.o".to_vec(),
            object_hash: "a".repeat(blake3::OUT_LEN * 2),
        }];
        let version = |start| MachOArchiveUnwindVersionState {
            common_members: common_members.clone(),
            eh_frame_reserve: MachOEhFrameReserveState {
                start,
                end: section_end,
            },
        };

        validate_macho_archive_unwind_version_output(&output.bytes, &version(full_link_start))
            .unwrap();
        validate_macho_archive_unwind_version_output(&output.bytes, &version(incremental_start))
            .unwrap();
        let alignment = crate::alignment::Alignment { exponent: 3 };
        for terminator_offset in [5_u64, 6, 7] {
            let mut producer_output = output.bytes.clone();
            let entry_start = output.eh_frame_offset as usize;
            producer_output[entry_start..entry_start + 4]
                .copy_from_slice(&u32::try_from(terminator_offset - 4).unwrap().to_le_bytes());
            producer_output[entry_start + 4..entry_start + terminator_offset as usize].fill(1);
            let terminator_start = output.eh_frame_offset + terminator_offset;
            let full_link_start = alignment.align_up(terminator_start);
            let incremental_start = alignment.align_up(terminator_start + 4);
            validate_macho_archive_unwind_version_output(
                &producer_output,
                &version(full_link_start),
            )
            .unwrap();
            validate_macho_archive_unwind_version_output(
                &producer_output,
                &version(incremental_start),
            )
            .unwrap();
        }
        for invalid_start in [full_link_start + 4, full_link_start + 16] {
            assert!(
                validate_macho_archive_unwind_version_output(
                    &output.bytes,
                    &version(invalid_start),
                )
                .unwrap_err()
                .contains("producer state")
            );
        }

        let target_patches = vec![
            StoredOutputPatch {
                output_offset: full_link_start,
                data: vec![0; 4],
            },
            StoredOutputPatch {
                output_offset: output.unwind_info_offset,
                data: vec![0; 0x1000],
            },
        ];
        scratch_apply_macho_archive_unwind_transition(
            &output.bytes,
            &target_patches,
            &version(full_link_start),
            &version(incremental_start),
        )
        .unwrap();
        let full_link_reserve = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: full_link_start,
            size: section_end - full_link_start,
        }];
        let incremental_reserve = vec![ReservedRangeRecord {
            output_offset: incremental_start,
            size: section_end - incremental_start,
            ..full_link_reserve[0].clone()
        }];
        assert_eq!(
            transition_macho_eh_frame_reserve(
                &full_link_reserve,
                version(full_link_start).eh_frame_reserve,
                version(incremental_start).eh_frame_reserve,
            )
            .unwrap(),
            incremental_reserve,
        );
        assert_eq!(
            transition_macho_eh_frame_reserve(
                &incremental_reserve,
                version(incremental_start).eh_frame_reserve,
                version(full_link_start).eh_frame_reserve,
            )
            .unwrap(),
            full_link_reserve,
        );

        output.bytes[full_link_start as usize + 4] = 1;
        assert!(
            validate_macho_archive_unwind_version_output(
                &output.bytes,
                &version(incremental_start),
            )
            .unwrap_err()
            .contains("suffix is not zero")
        );
    }

    #[test]
    fn changed_macho_archive_unwind_members_record_exact_replacement_proof() {
        let previous_object = test_observed_049_macho_unwind_object(false);
        let current_object = test_observed_049_macho_unwind_object(true);
        let input_file_path = hex::encode("input.rlib");
        let archive = |identifier: &[u8], object: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            let bytes = builder.into_inner().unwrap();
            let mut entries = ArchiveIterator::from_archive_bytes(&bytes).unwrap();
            let ArchiveEntry::Regular(member) = entries.next().unwrap().unwrap() else {
                panic!("expected regular archive member");
            };
            let input_ref = resolved_patch_input_ref(
                &input_file_path,
                &input_file_path,
                PatchInputBytes {
                    bytes: member.entry_data,
                    file_offset: member.data_offset,
                    archive_identifier: Some(member.ident.as_slice()),
                },
            )
            .unwrap();
            (bytes, input_ref)
        };
        let previous_identifier = b"crate-hash.codegen.previous.rcgu.o";
        let current_identifier = b"crate-hash.codegen.current.rcgu.o";
        let (previous_archive, previous_input) = archive(previous_identifier, &previous_object);
        let (current_archive, current_input) = archive(current_identifier, &current_object);

        let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
        let current_file = object::File::parse(current_object.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let output = test_macho_unwind_output(0x1000);
        let matched = vec![MatchedPatchSection {
            previous: PatchSection {
                input: previous_input,
                section_index: patch_section_record_index(&previous_file, previous_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: previous_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input,
                section_index: patch_section_record_index(&current_file, current_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let current_resolver = PatchInputResolver::new(&current_archive, true).unwrap();
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();

        let changed = changed_macho_archive_unwind_members(
            &previous_archive,
            &input_file_path,
            &matched,
            &[],
            &current_resolver,
            &output_file,
            &[],
        )
        .unwrap()
        .unwrap();
        assert_eq!(changed.members.len(), 1);
        assert_eq!(changed.previous_input_ranges.len(), 2);
        assert_eq!(changed.current_input_ranges.len(), 2);
        assert_eq!(changed.retired_entries.len(), 1);
        assert_eq!(
            changed.previous_common_members,
            vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(previous_identifier),
                object_hash: hash_bytes(&previous_object),
            }]
        );
        assert_eq!(
            changed.current_common_members,
            vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(current_identifier),
                object_hash: hash_bytes(&current_object),
            }]
        );
        assert!(
            changed.retired_entries.windows(2).all(|pair| {
                pair[0].function_offset + pair[0].length <= pair[1].function_offset
            })
        );

        let excluded = changed_macho_archive_unwind_members(
            &previous_archive,
            &input_file_path,
            &matched,
            &[],
            &current_resolver,
            &output_file,
            &[archive_member_patch_identifier(current_identifier)],
        )
        .unwrap()
        .unwrap();
        assert!(excluded.members.is_empty());
        assert!(excluded.retired_entries.is_empty());
        assert!(excluded.previous_input_ranges.is_empty());
        assert!(excluded.current_input_ranges.is_empty());

        let mismatched_previous_identifier = b"crate-hash.previous.previous.rcgu.o";
        let mismatched_current_identifier = b"crate-hash.current.current.rcgu.o";
        let (mismatched_previous_archive, mismatched_previous_input) =
            archive(mismatched_previous_identifier, &previous_object);
        let (mismatched_current_archive, mismatched_current_input) =
            archive(mismatched_current_identifier, &current_object);
        let mut mismatched = matched.clone();
        mismatched[0].previous.input = mismatched_previous_input;
        mismatched[0].current.input = mismatched_current_input;
        let mismatched_resolver =
            PatchInputResolver::new(&mismatched_current_archive, true).unwrap();
        let excluded = changed_macho_archive_unwind_members(
            &mismatched_previous_archive,
            &input_file_path,
            &mismatched,
            &[],
            &mismatched_resolver,
            &output_file,
            &[archive_member_patch_identifier(
                mismatched_current_identifier,
            )],
        )
        .unwrap()
        .unwrap();
        assert!(excluded.members.is_empty());

        let previous_only_excluded = changed_macho_archive_unwind_members(
            &mismatched_previous_archive,
            &input_file_path,
            &mismatched,
            &[],
            &mismatched_resolver,
            &output_file,
            &[archive_member_patch_identifier(
                mismatched_previous_identifier,
            )],
        )
        .unwrap();
        let Err(previous_only_excluded) = previous_only_excluded else {
            panic!("previous-only exclusion unexpectedly skipped the current member");
        };
        assert_eq!(
            previous_only_excluded,
            "changed Mach-O unwind member identity changed"
        );
    }

    #[test]
    fn changed_macho_unwind_uses_persisted_section_mapping() {
        let object = test_observed_049_macho_unwind_object(false);
        let file = object::File::parse(object.as_slice()).unwrap();
        let unwind = added_macho_archive_unwind(&file).unwrap().unwrap().unwrap();
        let text = file.section_by_name("__text").unwrap();
        let section_index = patch_section_record_index(&file, text.index()).unwrap();
        let output = test_macho_unwind_output(0x1000);
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
        let input_file_path = hex::encode("input.rlib");
        let input = "member.rcgu.o";
        let mut sections = Vec::new();
        let record = SectionRecord {
            input_file: input_file_path.clone().into(),
            input: input.into(),
            section_index,
            output_offset: output.text_offset + 0x100,
            size: text.size(),
        };

        assert_eq!(
            macho_unwind_function_identities(input, &unwind, &sections, &output_file).unwrap_err(),
            "changed Mach-O unwind function section has no previous output mapping",
        );
        supplement_macho_unwind_section_mappings(
            &input_file_path,
            input,
            &unwind,
            &file,
            std::slice::from_ref(&record),
            &mut sections,
        )
        .unwrap()
        .unwrap();

        let identities =
            macho_unwind_function_identities(input, &unwind, &sections, &output_file).unwrap();
        assert_eq!(identities.len(), 1);
        assert_eq!(identities[0].length, 0x258);

        let current_input = "current.rcgu.o";
        let mut current_sections = Vec::new();
        supplement_current_macho_unwind_section_mappings(
            &input_file_path,
            input,
            current_input,
            &unwind,
            &file,
            &file,
            std::slice::from_ref(&record),
            &[],
            &mut current_sections,
        )
        .unwrap()
        .unwrap();
        assert_eq!(current_sections.len(), 1);
        assert_eq!(current_sections[0].input, current_input);
        assert_eq!(current_sections[0].output_offset, record.output_offset);

        let mut changed_object = object.clone();
        let (text_offset, _) = text.file_range().unwrap();
        changed_object[text_offset as usize] ^= 1;
        let changed_file = object::File::parse(changed_object.as_slice()).unwrap();
        let mut changed_sections = Vec::new();
        supplement_current_macho_unwind_section_mappings(
            &input_file_path,
            input,
            current_input,
            &unwind,
            &file,
            &changed_file,
            std::slice::from_ref(&record),
            &[],
            &mut changed_sections,
        )
        .unwrap()
        .unwrap();
        assert!(changed_sections.is_empty());
    }

    #[test]
    fn changed_macho_archive_unwind_proof_composes_with_member_set_changes() {
        let previous_object = test_observed_049_macho_unwind_object(false);
        let mut current_object = previous_object.clone();
        let (compact_length_offset, eh_frame_length_offset, text_offset) = {
            let file = object::File::parse(current_object.as_slice()).unwrap();
            let compact = file.section_by_name("__compact_unwind").unwrap();
            let eh_frame = file.section_by_name("__eh_frame").unwrap();
            let (compact_offset, _) = compact.file_range().unwrap();
            let (eh_frame_offset, _) = eh_frame.file_range().unwrap();
            (
                compact_offset as usize
                    + compact
                        .data()
                        .unwrap()
                        .windows(4)
                        .position(|bytes| bytes == 0x258_u32.to_le_bytes())
                        .unwrap(),
                eh_frame_offset as usize
                    + eh_frame
                        .data()
                        .unwrap()
                        .windows(8)
                        .position(|bytes| bytes == 0x258_u64.to_le_bytes())
                        .unwrap(),
                file.section_by_name("__text")
                    .unwrap()
                    .file_range()
                    .unwrap()
                    .0 as usize,
            )
        };
        current_object[compact_length_offset..compact_length_offset + 4]
            .copy_from_slice(&0x250_u32.to_le_bytes());
        current_object[eh_frame_length_offset..eh_frame_length_offset + 8]
            .copy_from_slice(&0x250_u64.to_le_bytes());
        current_object[text_offset] ^= 1;
        let local_entry = macho_symbol_value_field_range(&current_object, object::SymbolIndex(1))
            .unwrap()
            .start
            - 8;
        assert_eq!(current_object[local_entry + 4] & object::macho::N_EXT, 0);
        current_object[local_entry + 4] |= object::macho::N_STAB;

        let removed_object = test_macho_object(b"removed", b"data", 0);
        let previous_identifier = b"crate-hash.codegen.previous.rcgu.o";
        let current_identifier = b"crate-hash.codegen.current.rcgu.o";
        let removed_identifier = b"crate-hash.removed.previous.rcgu.o";
        let archive = |members: &[(&[u8], &[u8])]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, object) in members {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), object.len() as u64),
                        *object,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let previous_archive = archive(&[
            (previous_identifier, previous_object.as_slice()),
            (removed_identifier, removed_object.as_slice()),
        ]);
        let current_archive = archive(&[(current_identifier, current_object.as_slice())]);
        let input_file_path = hex::encode("input.rlib");
        let input_ref = |archive: &[u8], identifier: &[u8]| {
            let ArchiveMemberMatch::Unique(member) =
                patch_archive_member_bytes(archive, identifier).unwrap()
            else {
                panic!("expected unique archive member");
            };
            resolved_patch_input_ref(&input_file_path, &input_file_path, member).unwrap()
        };
        let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
        let current_file = object::File::parse(current_object.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let output = test_macho_unwind_output(0x1000);
        let matched = vec![MatchedPatchSection {
            previous: PatchSection {
                input: input_ref(&previous_archive, previous_identifier),
                section_index: patch_section_record_index(&previous_file, previous_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: previous_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: input_ref(&current_archive, current_identifier),
                section_index: patch_section_record_index(&current_file, current_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let current_resolver = PatchInputResolver::new(&current_archive, true).unwrap();
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
        let retired_identifiers = vec![archive_member_patch_identifier(removed_identifier)];
        let changed = changed_macho_archive_unwind_members(
            &previous_archive,
            &input_file_path,
            &matched,
            &[],
            &current_resolver,
            &output_file,
            &retired_identifiers,
        )
        .unwrap()
        .unwrap();

        assert!(
            !archive_diff_allows_changed_macho_unwind(
                &previous_archive,
                &current_archive,
                &input_file_path,
                &matched,
                &current_resolver,
                &changed,
                &[],
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
            "ordinary unwind replacement must not ignore removed members or local symbols",
        );
        assert!(
            archive_diff_allows_changed_macho_unwind(
                &previous_archive,
                &current_archive,
                &input_file_path,
                &matched,
                &current_resolver,
                &changed,
                &retired_identifiers,
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
            "retirement proof should ignore only the retired member and masked local definition",
        );

        let reverse_matched = matched
            .iter()
            .map(|section| MatchedPatchSection {
                previous: section.current.clone(),
                current: section.previous.clone(),
            })
            .collect::<Vec<_>>();
        let reverse_resolver = PatchInputResolver::new(&previous_archive, true).unwrap();
        let reverse_changed = changed_macho_archive_unwind_members(
            &current_archive,
            &input_file_path,
            &reverse_matched,
            &[],
            &reverse_resolver,
            &output_file,
            &[],
        )
        .unwrap()
        .unwrap();
        assert!(
            !archive_diff_allows_changed_macho_unwind(
                &current_archive,
                &previous_archive,
                &input_file_path,
                &reverse_matched,
                &reverse_resolver,
                &reverse_changed,
                &[],
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
            "ordinary unwind replacement must not ignore added members or local symbols",
        );
        assert!(
            archive_diff_allows_changed_macho_unwind(
                &current_archive,
                &previous_archive,
                &input_file_path,
                &reverse_matched,
                &reverse_resolver,
                &reverse_changed,
                &[],
                &retired_identifiers,
                &HashSet::new(),
                &[],
            )
            .unwrap(),
            "addition proof should ignore only the added member and masked local definition",
        );
    }

    #[test]
    fn matched_macho_definition_resolution_refreshes_member_input() {
        let object = test_macho_object(b"text", b"data", 0);
        let previous_identifier = b"crate-hash.codegen.previous.rcgu.o";
        let current_identifier = b"crate-hash.codegen.current.rcgu.o";
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(current_identifier.to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let archive = builder.into_inner().unwrap();
        let mut entries = ArchiveIterator::from_archive_bytes(&archive).unwrap();
        let ArchiveEntry::Regular(member) = entries.next().unwrap().unwrap() else {
            panic!("expected regular archive member");
        };
        let input_file_path = hex::encode("input.rlib");
        let stale_input = resolved_patch_input_ref(
            &input_file_path,
            &input_file_path,
            PatchInputBytes {
                bytes: member.entry_data,
                file_offset: member.data_offset,
                archive_identifier: Some(previous_identifier),
            },
        )
        .unwrap();
        let current_input = resolved_patch_input_ref(
            &input_file_path,
            &input_file_path,
            PatchInputBytes {
                bytes: member.entry_data,
                file_offset: member.data_offset,
                archive_identifier: Some(current_identifier),
            },
        )
        .unwrap();
        assert_ne!(stale_input, current_input);

        let file = object::File::parse(object.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let output = test_macho_unwind_output(0x1000);
        let matched = vec![MatchedPatchSection {
            previous: PatchSection {
                input: stale_input.clone(),
                section_index: patch_section_record_index(&file, text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: stale_input,
                section_index: patch_section_record_index(&file, text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let current_resolver = PatchInputResolver::new(&archive, true).unwrap();
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();

        let resolution = matched_macho_definition_resolution(
            &input_file_path,
            b"_text",
            &matched,
            &current_resolver,
            &output_file,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(resolution.target.unwrap().input.as_str(), current_input);
    }

    #[test]
    fn changed_macho_archive_unwind_activation_replaces_existing_entries() {
        let previous_object = test_observed_049_macho_unwind_object(false);
        let replace_unwind_length =
            |mut object: Vec<u8>, previous_length: u32, current_length: u32| {
                let (compact_length_offset, eh_frame_length_offset, text_offset) = {
                    let file = object::File::parse(object.as_slice()).unwrap();
                    let compact = file.section_by_name("__compact_unwind").unwrap();
                    let eh_frame = file.section_by_name("__eh_frame").unwrap();
                    let (compact_offset, _) = compact.file_range().unwrap();
                    let (eh_frame_offset, _) = eh_frame.file_range().unwrap();
                    let compact_length = compact
                        .data()
                        .unwrap()
                        .windows(4)
                        .position(|bytes| bytes == previous_length.to_le_bytes())
                        .unwrap();
                    let eh_frame_length = eh_frame
                        .data()
                        .unwrap()
                        .windows(8)
                        .position(|bytes| bytes == u64::from(previous_length).to_le_bytes())
                        .unwrap();
                    (
                        compact_offset as usize + compact_length,
                        eh_frame_offset as usize + eh_frame_length,
                        file.section_by_name("__text")
                            .unwrap()
                            .file_range()
                            .unwrap()
                            .0 as usize,
                    )
                };
                object[compact_length_offset..compact_length_offset + 4]
                    .copy_from_slice(&current_length.to_le_bytes());
                object[eh_frame_length_offset..eh_frame_length_offset + 8]
                    .copy_from_slice(&u64::from(current_length).to_le_bytes());
                object[text_offset] ^= 1;
                object
            };
        let mut current_object =
            replace_unwind_length(previous_object.clone(), 0x258_u32, 0x250_u32);
        let local_entry = macho_symbol_value_field_range(&current_object, object::SymbolIndex(1))
            .unwrap()
            .start
            - 8;
        assert_eq!(current_object[local_entry + 4] & object::macho::N_EXT, 0);
        current_object[local_entry + 4] |= object::macho::N_STAB;
        let next_object = replace_unwind_length(current_object.clone(), 0x250_u32, 0x248_u32);
        let common_identifier = b"crate-hash.common.session.rcgu.o";
        let common_object = test_macho_local_data_retarget_object(b"l_anon.common", 0x12);

        let input_file_path = hex::encode("input.rlib");
        let archive = |identifier: &[u8], object: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder
                .append(
                    &ar::Header::new(common_identifier.to_vec(), common_object.len() as u64),
                    common_object.as_slice(),
                )
                .unwrap();
            let bytes = builder.into_inner().unwrap();
            let mut entries = ArchiveIterator::from_archive_bytes(&bytes).unwrap();
            let ArchiveEntry::Regular(member) = entries.next().unwrap().unwrap() else {
                panic!("expected regular archive member");
            };
            let input_ref = resolved_patch_input_ref(
                &input_file_path,
                &input_file_path,
                PatchInputBytes {
                    bytes: member.entry_data,
                    file_offset: member.data_offset,
                    archive_identifier: Some(member.ident.as_slice()),
                },
            )
            .unwrap();
            (bytes, input_ref)
        };
        let (previous_archive, previous_input) = archive(
            b"crate-hash.codegen.previous.rcgu.o",
            previous_object.as_slice(),
        );
        let (current_archive, current_input) = archive(
            b"crate-hash.codegen.current.rcgu.o",
            current_object.as_slice(),
        );
        let (next_archive, next_input) =
            archive(b"crate-hash.codegen.next.rcgu.o", next_object.as_slice());
        let previous_file = object::File::parse(previous_object.as_slice()).unwrap();
        let current_file = object::File::parse(current_object.as_slice()).unwrap();
        let next_file = object::File::parse(next_object.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();
        let next_text = next_file.section_by_name("__text").unwrap();

        let mut output = test_macho_unwind_output(0x1000);
        let (previous_member, mut previous_sections) = test_added_macho_unwind_member(false);
        previous_sections[0].output_offset = output.text_offset + 0x100;
        let mut reserves = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: output.eh_frame_offset,
            size: output.eh_frame_size,
        }];
        let initial = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&previous_member),
                &[0],
                &previous_sections,
                &output_file,
                &[],
                &[],
                &mut reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        apply_test_section_patches(&mut output.bytes, &initial.patches);
        let reserve_after_initial = reserves[0].clone();

        let matched = vec![MatchedPatchSection {
            previous: PatchSection {
                input: previous_input,
                section_index: patch_section_record_index(&previous_file, previous_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: previous_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: previous_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: current_input.clone(),
                section_index: patch_section_record_index(&current_file, current_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let current_sections = matched
            .iter()
            .map(|section| section.current.clone())
            .collect::<Vec<_>>();
        let current_resolver = PatchInputResolver::new(&current_archive, true).unwrap();
        let common_file = object::File::parse(common_object.as_slice()).unwrap();
        let common_source = common_file
            .sections()
            .find(|section| {
                section.name_bytes().ok() == Some(b"__const".as_slice())
                    && section.segment_name_bytes().ok().flatten() == Some(b"__DATA".as_slice())
            })
            .unwrap();
        let common_site = |target_symbol_index| ValidatedMachOLocalRelocationSite {
            archive_identifier: archive_member_patch_identifier(common_identifier),
            section_index: common_source.index().0,
            relocation_offset: 0,
            normalize_relocation_offset: false,
            target_symbol_index,
            hash_target_symbol: false,
            hash_unmasked_target_offset: false,
            exact_symbol_indices: Vec::new(),
        };
        let common_retarget = ValidatedMachOLocalRelocationRetarget {
            previous: common_site(0),
            current: common_site(1),
        };
        let excluded_current = changed_macho_archive_unwind_activation(
            &previous_archive,
            &current_archive,
            &input_file_path,
            &matched,
            &[],
            &current_sections,
            &current_resolver,
            &output.bytes,
            &[],
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[archive_member_patch_identifier(
                b"crate-hash.codegen.current.rcgu.o",
            )],
            &HashSet::new(),
            &[],
        )
        .unwrap()
        .unwrap();
        assert!(excluded_current.is_none());
        let activation = changed_macho_archive_unwind_activation(
            &previous_archive,
            &current_archive,
            &input_file_path,
            &matched,
            &[],
            &current_sections,
            &current_resolver,
            &output.bytes,
            &[],
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[],
            &HashSet::new(),
            std::slice::from_ref(&common_retarget),
        )
        .unwrap()
        .unwrap()
        .unwrap();

        assert_eq!(activation.patches.len(), 2);
        assert_eq!(
            activation.remaining_reserved_ranges,
            vec![ReservedRangeRecord {
                output_offset: reserve_after_initial.output_offset + 72,
                size: reserve_after_initial.size - 72,
                ..reserve_after_initial
            }]
        );
        let unwind_info = activation
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.unwind_info_offset)
            .unwrap();
        let live_entries = crate::macho_writer::parse_macho_unwind_info(&unwind_info.data)
            .unwrap()
            .into_iter()
            .filter(|entry| entry.encoding != 0)
            .collect::<Vec<_>>();
        assert_eq!(live_entries.len(), 1);
        assert_eq!(live_entries[0].length, 0x250);
        let previous_version_output = output.bytes.clone();
        apply_test_section_patches(&mut output.bytes, &activation.patches);
        let current_version_output = output.bytes.clone();
        assert_eq!(
            eh_frame_terminator_offset(
                &output.bytes[output.eh_frame_offset as usize
                    ..(output.eh_frame_offset + output.eh_frame_size) as usize]
            ),
            Some(144)
        );

        let unwind_transaction = activation.unwind_transaction.clone().unwrap();
        let forward_patches = activation
            .patches
            .iter()
            .map(|patch| stored_output_patch(patch, &previous_version_output).unwrap())
            .collect::<Vec<_>>();
        let rollback_patches = forward_patches
            .iter()
            .map(|patch| StoredOutputPatch {
                output_offset: patch.output_offset,
                data: previous_version_output
                    [patch.output_offset as usize..patch.output_offset as usize + patch.data.len()]
                    .to_vec(),
            })
            .collect::<Vec<_>>();
        let mut historical_state = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![unwind_transaction.forward.common_members[0].clone()],
            active: false,
            sections: vec![file_patch_section_state(&matched[0].current)],
            relocations: Vec::new(),
            symbol_resolutions: Vec::new(),
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: Vec::new(),
            forward_patches,
            rollback_patches,
            unwind_transaction: Some(unwind_transaction.clone()),
        };
        let changed_for_direction =
            |previous_common_members, current_common_members| ChangedMachOArchiveUnwindMembers {
                members: Vec::new(),
                previous_common_members,
                current_common_members,
                retired_entries: Vec::new(),
                current_sections: Vec::new(),
                previous_input_ranges: Vec::new(),
                current_input_ranges: Vec::new(),
            };
        let forward_change = changed_for_direction(
            unwind_transaction.rollback.common_members.clone(),
            unwind_transaction.forward.common_members.clone(),
        );
        let rollback_change = changed_for_direction(
            unwind_transaction.forward.common_members.clone(),
            unwind_transaction.rollback.common_members.clone(),
        );
        let round_trip_state = |state: &MachOArchiveActivationState| {
            parse_macho_archive_member_states(
                &input_file_path,
                &render_macho_archive_member_states(std::slice::from_ref(state)),
            )
            .unwrap()
            .pop()
            .unwrap()
        };
        let fixed_current_matched = vec![MatchedPatchSection {
            previous: matched[0].current.clone(),
            current: matched[0].current.clone(),
        }];
        let fixed_current_sections = vec![fixed_current_matched[0].current.clone()];
        let mut fixed_retirement = historical_state.clone();
        fixed_retirement.active = false;
        let fixed_retirement = changed_macho_archive_unwind_activation_with_local_symbol_renames(
            &current_archive,
            &current_archive,
            &input_file_path,
            &fixed_current_matched,
            &[],
            &fixed_current_sections,
            &current_resolver,
            &current_version_output,
            &[],
            &activation.remaining_reserved_ranges,
            &[],
            &[],
            Some(&fixed_retirement),
            &[],
            &[],
            &HashSet::new(),
            &[],
            &[],
        )
        .unwrap();
        let Err(fixed_retirement) = fixed_retirement else {
            panic!("fixed common unwind unexpectedly skipped retirement ownership");
        };
        assert!(fixed_retirement.contains("was not consumed"));

        let previous_resolver = PatchInputResolver::new(&previous_archive, true).unwrap();
        let fixed_previous_matched = vec![MatchedPatchSection {
            previous: matched[0].previous.clone(),
            current: matched[0].previous.clone(),
        }];
        let fixed_previous_sections = vec![fixed_previous_matched[0].current.clone()];
        let mut fixed_reactivation = historical_state.clone();
        fixed_reactivation.active = true;
        let fixed_reactivation = changed_macho_archive_unwind_activation_with_local_symbol_renames(
            &previous_archive,
            &previous_archive,
            &input_file_path,
            &fixed_previous_matched,
            &[],
            &fixed_previous_sections,
            &previous_resolver,
            &previous_version_output,
            &[],
            &reserves,
            &[],
            &[],
            Some(&fixed_reactivation),
            &[],
            &[],
            &HashSet::new(),
            &[],
            &[],
        )
        .unwrap();
        let Err(fixed_reactivation) = fixed_reactivation else {
            panic!("fixed common unwind unexpectedly skipped reactivation ownership");
        };
        assert!(fixed_reactivation.contains("was not consumed"));

        let mut legacy_unwind_state = historical_state.clone();
        legacy_unwind_state.unwind_transaction = None;
        assert!(
            macho_archive_transaction_touches_unwind_output(
                &legacy_unwind_state,
                &current_version_output,
            )
            .unwrap(),
            "legacy unwind ownership was not classified fail-closed",
        );
        assert!(
            validate_historical_macho_archive_unwind_planning(Some(&historical_state), false)
                .unwrap_err()
                .contains("fresh archive activation"),
            "a fresh added cohort bypassed historical unwind ownership",
        );
        let mut historical_output = current_version_output.clone();
        let mut historical_reserves = activation.remaining_reserved_ranges.clone();
        for _ in 0..2 {
            historical_state.active = false;
            historical_state = round_trip_state(&historical_state);
            historical_reserves = reuse_historical_macho_archive_unwind_transaction(
                &historical_state,
                &rollback_change,
                &historical_output,
                &historical_reserves,
            )
            .unwrap();
            apply_test_section_patches(
                &mut historical_output,
                &section_patches_from_stored(&historical_state.rollback_patches),
            );
            assert_eq!(historical_output, previous_version_output);
            assert_eq!(
                historical_reserves,
                vec![ReservedRangeRecord {
                    output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
                    alignment_exponent: 3,
                    output_offset: unwind_transaction.rollback.eh_frame_reserve.start,
                    size: unwind_transaction.rollback.eh_frame_reserve.end
                        - unwind_transaction.rollback.eh_frame_reserve.start,
                }]
            );

            historical_state.active = true;
            historical_state = round_trip_state(&historical_state);
            historical_reserves = reuse_historical_macho_archive_unwind_transaction(
                &historical_state,
                &forward_change,
                &historical_output,
                &historical_reserves,
            )
            .unwrap();
            apply_test_section_patches(
                &mut historical_output,
                &section_patches_from_stored(&historical_state.forward_patches),
            );
            assert_eq!(historical_output, current_version_output);
            assert_eq!(historical_reserves, activation.remaining_reserved_ranges);
        }

        let mut refreshed_proof = historical_state.clone();
        let unrelated_offset = output.text_offset as usize;
        refreshed_proof.forward_patches.push(StoredOutputPatch {
            output_offset: unrelated_offset as u64,
            data: vec![current_version_output[unrelated_offset]],
        });
        refreshed_proof.rollback_patches.push(StoredOutputPatch {
            output_offset: unrelated_offset as u64,
            data: vec![previous_version_output[unrelated_offset]],
        });
        let mut refreshed_output = current_version_output.clone();
        refreshed_output[unrelated_offset] ^= 1;
        refresh_active_macho_archive_forward_patches(&mut refreshed_proof, &refreshed_output)
            .unwrap();
        assert_eq!(
            refreshed_proof.forward_patches.last().unwrap().data,
            refreshed_output[unrelated_offset..unrelated_offset + 1],
        );
        assert_eq!(
            refreshed_proof.unwind_transaction,
            Some(unwind_transaction.clone())
        );

        let (unwind_info_offset, unwind_info_size, mut other_entries, text_end) = {
            let file = object::File::parse(refreshed_output.as_slice()).unwrap();
            let unwind_info = file.section_by_name("__unwind_info").unwrap();
            let (offset, size) = unwind_info.file_range().unwrap();
            let entries =
                crate::macho_writer::parse_macho_unwind_info(unwind_info.data().unwrap()).unwrap();
            let text = file.section_by_name("__text").unwrap();
            let text_end = added_macho_archive_image_offset(text.address() + text.size()).unwrap();
            (offset as usize, size as usize, entries, text_end)
        };
        other_entries
            .iter_mut()
            .find(|entry| entry.encoding != 0)
            .unwrap()
            .encoding ^= 1;
        let mut other_unwind_info = vec![0; unwind_info_size];
        crate::macho_writer::serialize_macho_unwind_info(
            &mut other_unwind_info,
            other_entries,
            text_end,
        )
        .unwrap();
        assert_ne!(
            other_unwind_info,
            refreshed_output[unwind_info_offset..unwind_info_offset + unwind_info_size],
        );
        assert!(crate::macho_writer::parse_macho_unwind_info(&other_unwind_info).is_ok());
        let mut interleaved_output = refreshed_output.clone();
        interleaved_output[unwind_info_offset..unwind_info_offset + unwind_info_size]
            .copy_from_slice(&other_unwind_info);
        let interleaved_file = object::File::parse(interleaved_output.as_slice()).unwrap();
        assert_eq!(
            macho_eh_frame_reserve_state(&interleaved_file, &activation.remaining_reserved_ranges,)
                .unwrap()
                .unwrap(),
            unwind_transaction.forward.eh_frame_reserve,
        );
        let before_interleaved_refresh = refreshed_proof.clone();
        assert!(
            refresh_active_macho_archive_forward_patches(
                &mut refreshed_proof,
                &interleaved_output,
            )
            .unwrap_err()
            .contains("unwind transaction bytes changed")
        );
        assert_eq!(refreshed_proof, before_interleaved_refresh);

        let mut invalidated_output = refreshed_output.clone();
        let eh_frame = object::File::parse(invalidated_output.as_slice())
            .unwrap()
            .section_by_name("__eh_frame")
            .unwrap()
            .file_range()
            .unwrap();
        let eh_patch = refreshed_proof
            .forward_patches
            .iter()
            .find(|patch| {
                let end = patch.output_offset + patch.data.len() as u64;
                patch.output_offset < eh_frame.0 + eh_frame.1 && eh_frame.0 < end
            })
            .unwrap();
        let invalidated_offset = eh_patch.output_offset as usize + eh_patch.data.len() - 1;
        invalidated_output[invalidated_offset] = 1;
        let before_invalid_refresh = refreshed_proof.clone();
        assert!(
            refresh_active_macho_archive_forward_patches(
                &mut refreshed_proof,
                &invalidated_output,
            )
            .unwrap_err()
            .contains("unwind transaction bytes changed")
        );
        assert_eq!(refreshed_proof, before_invalid_refresh);

        historical_state.active = false;
        let reject = |candidate: MachOArchiveActivationState| {
            let state_before = candidate.clone();
            let output_before = current_version_output.clone();
            let reserves_before = activation.remaining_reserved_ranges.clone();
            assert!(
                reuse_historical_macho_archive_unwind_transaction(
                    &candidate,
                    &rollback_change,
                    &current_version_output,
                    &activation.remaining_reserved_ranges,
                )
                .is_err()
            );
            assert_eq!(candidate, state_before);
            assert_eq!(current_version_output, output_before);
            assert_eq!(activation.remaining_reserved_ranges, reserves_before);
        };

        let mut wrong_hash = historical_state.clone();
        wrong_hash
            .unwind_transaction
            .as_mut()
            .unwrap()
            .rollback
            .common_members[0]
            .object_hash = "f".repeat(blake3::OUT_LEN * 2);
        reject(wrong_hash);

        let mut wrong_identifier = historical_state.clone();
        wrong_identifier
            .unwind_transaction
            .as_mut()
            .unwrap()
            .rollback
            .common_members[0]
            .normalized_identifier = b"other.common.rcgu.o".to_vec();
        reject(wrong_identifier);

        let mut wrong_source = historical_state.clone();
        wrong_source.forward_patches[0].data[0] ^= 1;
        reject(wrong_source);

        let current_file = object::File::parse(current_version_output.as_slice()).unwrap();
        let unwind_info = current_file.section_by_name("__unwind_info").unwrap();
        let (unwind_info_offset, unwind_info_size) = unwind_info.file_range().unwrap();
        let unwind_index = historical_state
            .forward_patches
            .iter()
            .position(|patch| {
                patch.output_offset == unwind_info_offset
                    && patch.data.len() as u64 == unwind_info_size
            })
            .unwrap();
        let mut partial_unwind = historical_state.clone();
        partial_unwind.forward_patches[unwind_index].data.pop();
        partial_unwind.rollback_patches[unwind_index].data.pop();
        reject(partial_unwind);

        let mut missing_unwind = historical_state.clone();
        missing_unwind.forward_patches.remove(unwind_index);
        missing_unwind.rollback_patches.remove(unwind_index);
        reject(missing_unwind);

        let mut duplicate_unwind = historical_state.clone();
        duplicate_unwind
            .forward_patches
            .push(duplicate_unwind.forward_patches[unwind_index].clone());
        duplicate_unwind
            .rollback_patches
            .push(duplicate_unwind.rollback_patches[unwind_index].clone());
        reject(duplicate_unwind);

        let eh_frame = current_file.section_by_name("__eh_frame").unwrap();
        let (eh_frame_offset, eh_frame_size) = eh_frame.file_range().unwrap();
        let eh_index = historical_state
            .rollback_patches
            .iter()
            .position(|patch| {
                let end = patch.output_offset + patch.data.len() as u64;
                patch.output_offset < eh_frame_offset + eh_frame_size && eh_frame_offset < end
            })
            .unwrap();
        let mut nonzero_suffix = historical_state.clone();
        *nonzero_suffix.rollback_patches[eh_index]
            .data
            .last_mut()
            .unwrap() = 1;
        reject(nonzero_suffix);

        let mut noncanonical_start = historical_state.clone();
        noncanonical_start
            .unwind_transaction
            .as_mut()
            .unwrap()
            .rollback
            .eh_frame_reserve
            .start += 8;
        reject(noncanonical_start);

        let mut wrong_end = historical_state.clone();
        wrong_end
            .unwind_transaction
            .as_mut()
            .unwrap()
            .rollback
            .eh_frame_reserve
            .end -= 8;
        reject(wrong_end);

        let mut missing_proof = historical_state.clone();
        missing_proof.unwind_transaction = None;
        reject(missing_proof);

        let ambiguous = ChangedMachODefinitionActivation {
            state_updates: vec![
                MachOArchiveActivationStateUpdate::Replace(0, historical_state.clone()),
                MachOArchiveActivationStateUpdate::Replace(1, historical_state.clone()),
            ],
            symbol_resolutions: Vec::new(),
            output_patches: Vec::new(),
            added_names: Vec::new(),
            retired_names: Vec::new(),
            recycled_names: Vec::new(),
            remaining_reserved_ranges: Vec::new(),
        };
        assert!(ambiguous.changed_unwind_ownership_state().is_err());

        let next_matched = vec![MatchedPatchSection {
            previous: PatchSection {
                input: current_input.clone(),
                section_index: patch_section_record_index(&current_file, current_text.index())
                    .unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: current_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: current_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            current: PatchSection {
                input: next_input,
                section_index: patch_section_record_index(&next_file, next_text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: next_text.size(),
                output_offset: output.text_offset + 0x100,
                output_size: next_text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        }];
        let next_sections = next_matched
            .iter()
            .map(|section| section.current.clone())
            .collect::<Vec<_>>();
        let next_resolver = PatchInputResolver::new(&next_archive, true).unwrap();
        let next_activation = changed_macho_archive_unwind_activation(
            &current_archive,
            &next_archive,
            &input_file_path,
            &next_matched,
            &[],
            &next_sections,
            &next_resolver,
            &output.bytes,
            &[],
            &activation.remaining_reserved_ranges,
            &[],
            &[],
            false,
            &[],
            &[],
            &HashSet::new(),
            &[],
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(next_activation.patches.len(), 2);
        assert_eq!(
            next_activation.remaining_reserved_ranges,
            vec![ReservedRangeRecord {
                output_offset: reserve_after_initial.output_offset + 144,
                size: reserve_after_initial.size - 144,
                ..reserve_after_initial.clone()
            }]
        );
        let next_eh_frame = next_activation
            .patches
            .iter()
            .find(|patch| {
                patch.output_offset == reserve_after_initial.output_offset + 64 && patch.size == 76
            })
            .unwrap();
        assert_eq!(next_eh_frame.data.len(), 76);
        let next_unwind_info = next_activation
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.unwind_info_offset)
            .unwrap();
        let next_live_entries =
            crate::macho_writer::parse_macho_unwind_info(&next_unwind_info.data)
                .unwrap()
                .into_iter()
                .filter(|entry| entry.encoding != 0)
                .collect::<Vec<_>>();
        assert_eq!(next_live_entries.len(), 1);
        assert_eq!(next_live_entries[0].length, 0x248);
        apply_test_section_patches(&mut output.bytes, &next_activation.patches);
        assert_eq!(
            eh_frame_terminator_offset(
                &output.bytes[output.eh_frame_offset as usize
                    ..(output.eh_frame_offset + output.eh_frame_size) as usize]
            ),
            Some(216)
        );

        let mut unrelated_change = current_object;
        unrelated_change[24] ^= 1;
        let (unrelated_archive, _) = archive(
            b"crate-hash.codegen.current.rcgu.o",
            unrelated_change.as_slice(),
        );
        let unrelated_resolver = PatchInputResolver::new(&unrelated_archive, true).unwrap();
        let unrelated = changed_macho_archive_unwind_activation(
            &previous_archive,
            &unrelated_archive,
            &input_file_path,
            &matched,
            &[],
            &current_sections,
            &unrelated_resolver,
            &output.bytes,
            &[],
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[],
            &HashSet::new(),
            &[],
        )
        .unwrap();
        assert!(matches!(
            unrelated,
                Err(reason)
                    if reason.starts_with(
                        "changed Mach-O archive member differs outside text and unwind metadata"
                    )
        ));
    }

    #[test]
    fn changed_archive_unwind_activation_composes_with_resolution_migration() {
        let add_migrated_definition = |mut object: Vec<u8>| {
            let file = object::File::parse(object.as_slice()).unwrap();
            let text = file.section_by_name("__text").unwrap();
            let text_section = u8::try_from(text.index().0).unwrap();
            let text_value = text.address();
            drop(file);
            object = add_test_macho_local_alias(object, b"_migrated", text_section, text_value);
            let entry = test_macho_symbol_entry_offset(&object, b"_migrated");
            object[entry + 4] |= object::macho::N_EXT;
            object
        };
        let retire_migrated_definition = |object: Vec<u8>| {
            let file = object::File::parse(object.as_slice()).unwrap();
            let symbol_index = file
                .symbols()
                .find(|symbol| symbol.name_bytes().ok() == Some(b"_migrated"))
                .unwrap()
                .index()
                .0;
            retire_test_macho_symbol(object, symbol_index)
        };
        let replace_unwind_length =
            |mut object: Vec<u8>, previous_length: u32, current_length: u32| {
                let (compact_length_offset, eh_frame_length_offset, text_offset) = {
                    let file = object::File::parse(object.as_slice()).unwrap();
                    let compact = file.section_by_name("__compact_unwind").unwrap();
                    let eh_frame = file.section_by_name("__eh_frame").unwrap();
                    let (compact_offset, _) = compact.file_range().unwrap();
                    let (eh_frame_offset, _) = eh_frame.file_range().unwrap();
                    let compact_length = compact
                        .data()
                        .unwrap()
                        .windows(4)
                        .position(|bytes| bytes == previous_length.to_le_bytes())
                        .unwrap();
                    let eh_frame_length = eh_frame
                        .data()
                        .unwrap()
                        .windows(8)
                        .position(|bytes| bytes == u64::from(previous_length).to_le_bytes())
                        .unwrap();
                    (
                        compact_offset as usize + compact_length,
                        eh_frame_offset as usize + eh_frame_length,
                        file.section_by_name("__text")
                            .unwrap()
                            .file_range()
                            .unwrap()
                            .0 as usize,
                    )
                };
                object[compact_length_offset..compact_length_offset + 4]
                    .copy_from_slice(&current_length.to_le_bytes());
                object[eh_frame_length_offset..eh_frame_length_offset + 8]
                    .copy_from_slice(&u64::from(current_length).to_le_bytes());
                object[text_offset] ^= 1;
                object
            };

        let previous_defined =
            add_migrated_definition(test_observed_049_macho_unwind_object(false));
        let previous_retired = retire_migrated_definition(previous_defined.clone());
        let current_changed = retire_migrated_definition(replace_unwind_length(
            previous_defined.clone(),
            0x258,
            0x250,
        ));
        let input_file_path = hex::encode("input.rlib");
        let source_identifier = b"crate.source.rcgu.o";
        let destination_identifier = b"crate.destination.rcgu.o";
        let archive = |source: &[u8], destination: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, member) in [
                (source_identifier.as_slice(), source),
                (destination_identifier.as_slice(), destination),
            ] {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), member.len() as u64),
                        member,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let previous_archive = archive(&previous_defined, &previous_retired);
        let current_archive = archive(&current_changed, &previous_defined);
        let input_ref = |bytes: &[u8], identifier: &[u8]| {
            let ArchiveMemberMatch::Unique(member) =
                patch_archive_member_bytes(bytes, identifier).unwrap()
            else {
                panic!("expected one archive member");
            };
            resolved_patch_input_ref(&input_file_path, &input_file_path, member).unwrap()
        };
        let previous_source = input_ref(&previous_archive, source_identifier);
        let previous_destination = input_ref(&previous_archive, destination_identifier);
        let current_source = input_ref(&current_archive, source_identifier);
        let current_destination = input_ref(&current_archive, destination_identifier);
        let previous_file = object::File::parse(previous_defined.as_slice()).unwrap();
        let current_file = object::File::parse(current_changed.as_slice()).unwrap();
        let previous_text = previous_file.section_by_name("__text").unwrap();
        let current_text = current_file.section_by_name("__text").unwrap();

        let mut output = test_macho_unwind_output(0x1000);
        let (previous_member, mut previous_sections) = test_added_macho_unwind_member(false);
        previous_sections[0].output_offset = output.text_offset + 0x100;
        let mut reserves = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: output.eh_frame_offset,
            size: output.eh_frame_size,
        }];
        let initial = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&previous_member),
                &[0],
                &previous_sections,
                &output_file,
                &[],
                &[],
                &mut reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        apply_test_section_patches(&mut output.bytes, &initial.patches);

        let section = |input: String, output_offset: u64, current: bool| {
            let (file, text) = if current {
                (&current_file, &current_text)
            } else {
                (&previous_file, &previous_text)
            };
            PatchSection {
                input,
                section_index: patch_section_record_index(file, text.index()).unwrap(),
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            }
        };
        let matched = vec![
            MatchedPatchSection {
                previous: section(previous_source.clone(), output.text_offset + 0x100, false),
                current: section(current_source, output.text_offset + 0x100, true),
            },
            MatchedPatchSection {
                previous: section(previous_destination, output.text_offset + 0x200, false),
                current: section(
                    current_destination.clone(),
                    output.text_offset + 0x200,
                    false,
                ),
            },
        ];
        let current_sections = matched
            .iter()
            .map(|section| section.current.clone())
            .collect::<Vec<_>>();
        let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
        let previous_value =
            macho_output_address_for_file_offset(&output_file, output.text_offset + 0x100).unwrap();
        let input = state("args", &output.bytes, &[("input.rlib", &previous_archive)])
            .input_files
            .remove(0);
        assert_eq!(input.path, input_file_path);
        let mut resolutions = vec![MachOSymbolResolutionRecord {
            name: hex::encode("_migrated").into(),
            direct_value: Some(previous_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input.path.clone().into(),
                input: previous_source.into(),
                section_index: relocation_target_record_index(previous_text.index()).unwrap(),
                section_offset: 0,
            }),
        }];
        let updates = update_macho_symbol_resolutions_for_input(
            &mut resolutions,
            &input,
            &current_archive,
            false,
            Some((&matched, &output.bytes)),
        )
        .unwrap()
        .unwrap();
        assert_eq!(updates.moves.len(), 1);
        assert_eq!(
            updates.moves[0].current_target.input.as_str(),
            current_destination,
        );
        let migrated =
            migrated_macho_archive_definition_names(&input.path, &updates.moves).unwrap();
        assert_eq!(migrated, HashSet::from([b"_migrated".to_vec()]));
        let current_resolver = PatchInputResolver::new(&current_archive, true).unwrap();

        let without_migration = changed_macho_archive_unwind_activation(
            &previous_archive,
            &current_archive,
            &input.path,
            &matched,
            &[],
            &current_sections,
            &current_resolver,
            &output.bytes,
            &resolutions,
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[],
            &HashSet::new(),
            &[],
        )
        .unwrap();
        assert!(without_migration.is_err());
        let activation = changed_macho_archive_unwind_activation(
            &previous_archive,
            &current_archive,
            &input.path,
            &matched,
            &[],
            &current_sections,
            &current_resolver,
            &output.bytes,
            &resolutions,
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[],
            &migrated,
            &[],
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(activation.patches.len(), 2);

        let mut unrelated_source = current_changed;
        unrelated_source[24] ^= 1;
        let unrelated_archive = archive(&unrelated_source, &previous_defined);
        let unrelated = changed_macho_archive_unwind_activation(
            &previous_archive,
            &unrelated_archive,
            &input.path,
            &matched,
            &[],
            &current_sections,
            &PatchInputResolver::new(&unrelated_archive, true).unwrap(),
            &output.bytes,
            &resolutions,
            &reserves,
            &[],
            &[],
            false,
            &[],
            &[],
            &migrated,
            &[],
        )
        .unwrap();
        assert!(unrelated.is_err());
    }

    #[test]
    fn added_macho_archive_unwind_activation_advances_terminator_and_rolls_back() {
        let (mut member, mut sections) = test_added_macho_unwind_member(false);
        let compact = member
            .unwind
            .as_mut()
            .unwrap()
            .compact_unwind
            .as_mut()
            .unwrap();
        compact.entries[0].encoding |=
            ADDED_MACHO_UNWIND_PERSONALITY_MASK | ADDED_MACHO_UNWIND_HAS_LSDA;
        let mut output = test_macho_unwind_output(0x1000);
        sections[0].output_offset = output.text_offset + 0x100;

        let undersized_reserve = ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: output.eh_frame_offset,
            size: 72,
        };
        let mut undersized_reserves = vec![undersized_reserve.clone()];
        let undersized = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut undersized_reserves,
            )
            .unwrap()
        };
        assert!(matches!(
            undersized,
            Err(reason) if reason.contains("reserve is not adjacent to the current terminator")
        ));
        assert_eq!(undersized_reserves, [undersized_reserve]);

        let original_reserve = ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: output.eh_frame_offset,
            size: 152,
        };
        let mut reserves = vec![original_reserve.clone()];

        let mut nonzero_output = output.bytes.clone();
        nonzero_output[output.eh_frame_offset as usize + 75] = 1;
        let mut nonzero_reserves = reserves.clone();
        let nonzero = {
            let output_file = object::File::parse(nonzero_output.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut nonzero_reserves,
            )
            .unwrap()
        };
        assert!(matches!(
            nonzero,
            Err(reason) if reason.contains("outside the section or nonzero")
        ));
        assert_eq!(nonzero_reserves, reserves);

        let first = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        assert_eq!(first.patches.len(), 2);
        let first_eh_frame = first
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.eh_frame_offset)
            .unwrap();
        assert_eq!(first_eh_frame.size, 76);
        let first_unwind_info = first
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.unwind_info_offset)
            .unwrap();
        let first_unwind_entries =
            crate::macho_writer::parse_macho_unwind_info(&first_unwind_info.data).unwrap();
        let first_live_entry = first_unwind_entries
            .iter()
            .find(|entry| entry.encoding != 0)
            .unwrap();
        assert_eq!(
            first_live_entry.encoding & ADDED_MACHO_UNWIND_MODE_MASK,
            ADDED_MACHO_UNWIND_MODE_DWARF
        );
        assert_eq!(
            first_live_entry.encoding
                & (ADDED_MACHO_UNWIND_PERSONALITY_MASK | ADDED_MACHO_UNWIND_HAS_LSDA),
            0
        );
        assert_eq!(first_live_entry.personality_offset, None);
        assert_eq!(first_live_entry.lsda_offset, None);
        assert_eq!(
            reserves,
            vec![ReservedRangeRecord {
                output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
                alignment_exponent: 3,
                output_offset: output.eh_frame_offset + 80,
                size: 72,
            }]
        );
        apply_test_section_patches(&mut output.bytes, &first.patches);
        assert_eq!(
            eh_frame_terminator_offset(
                &output.bytes[output.eh_frame_offset as usize
                    ..(output.eh_frame_offset + output.eh_frame_size) as usize]
            ),
            Some(72)
        );

        let overlap_reserves = reserves.clone();
        let overlap_result = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut reserves,
            )
            .unwrap()
        };
        let overlap = match overlap_result {
            Err(reason) => reason,
            Ok(_) => panic!("expected overlapping unwind activation to fail"),
        };
        assert!(overlap.contains("overlaps an existing live entry"));
        assert_eq!(reserves, overlap_reserves);

        sections[0].output_offset = output.text_offset + 0x400;
        let second = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        let second_eh_frame = second
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.eh_frame_offset + 72)
            .unwrap();
        assert_eq!(second_eh_frame.size, 76);
        assert!(reserves.is_empty());
        apply_test_section_patches(&mut output.bytes, &second.patches);
        assert_eq!(
            eh_frame_terminator_offset(
                &output.bytes[output.eh_frame_offset as usize
                    ..(output.eh_frame_offset + output.eh_frame_size) as usize]
            ),
            Some(144)
        );

        let mut gapped = test_macho_unwind_output(0x1000);
        let gapped_eh_frame = gapped.eh_frame_offset as usize;
        gapped.bytes[gapped_eh_frame..gapped_eh_frame + 4].copy_from_slice(&8_u32.to_le_bytes());
        let mut gapped_reserves = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: gapped.eh_frame_offset + 88,
            size: 72,
        }];
        sections[0].output_offset = gapped.text_offset + 0x100;
        let gapped_activation = {
            let output_file = object::File::parse(gapped.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut gapped_reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        assert!(
            gapped_activation
                .patches
                .iter()
                .any(|patch| patch.output_offset == gapped.eh_frame_offset + 12 && patch.size == 76)
        );
        assert_eq!(
            gapped_reserves,
            vec![ReservedRangeRecord {
                output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
                alignment_exponent: 3,
                output_offset: gapped.eh_frame_offset + 88,
                size: 72,
            }]
        );
        apply_test_section_patches(&mut gapped.bytes, &gapped_activation.patches);
        assert_eq!(
            eh_frame_terminator_offset(
                &gapped.bytes[gapped.eh_frame_offset as usize
                    ..(gapped.eh_frame_offset + gapped.eh_frame_size) as usize]
            ),
            Some(84)
        );

        let too_small = test_macho_unwind_output(32);
        let mut insufficient_capacity_reserves = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: too_small.eh_frame_offset,
            size: 80,
        }];
        sections[0].output_offset = too_small.text_offset + 0x100;
        let before_failure = insufficient_capacity_reserves.clone();
        let failure_result = {
            let output_file = object::File::parse(too_small.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                &[],
                &[],
                &mut insufficient_capacity_reserves,
            )
            .unwrap()
        };
        let failure = match failure_result {
            Err(reason) => reason,
            Ok(_) => panic!("expected unwind-info capacity failure"),
        };
        assert!(failure.contains("__unwind_info allocation too small"));
        assert_eq!(insufficient_capacity_reserves, before_failure);
        assert_eq!(
            eh_frame_terminator_offset(
                &too_small.bytes[too_small.eh_frame_offset as usize
                    ..(too_small.eh_frame_offset + too_small.eh_frame_size) as usize]
            ),
            Some(0)
        );
    }

    #[test]
    fn added_macho_archive_unwind_activation_materializes_personality_and_lsda() {
        let (member, mut sections) = test_added_macho_unwind_member(true);
        let output = test_macho_unwind_output(0x1000);
        sections[0].output_offset = output.text_offset + 0x100;
        sections[1].output_offset = output.gcc_except_table_offset;
        let mut reserves = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::EH_FRAME.as_usize() as u32,
            alignment_exponent: 3,
            output_offset: output.eh_frame_offset,
            size: 0x180,
        }];
        let resolution = MachOSymbolResolutionRecord {
            name: hex::encode(b"_rust_eh_personality").into(),
            direct_value: Some(crate::macho::MACHO_START_MEM_ADDRESS + 0x700),
            got_address: Some(crate::macho::MACHO_START_MEM_ADDRESS + 0x780),
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: None,
        };
        let activation = {
            let output_file = object::File::parse(output.bytes.as_slice()).unwrap();
            added_macho_archive_unwind_activation(
                std::slice::from_ref(&member),
                &[0],
                &sections,
                &output_file,
                std::slice::from_ref(&resolution),
                &[],
                &mut reserves,
            )
            .unwrap()
            .unwrap()
            .unwrap()
        };
        let eh_frame_patch = activation
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.eh_frame_offset)
            .unwrap();
        assert_eq!(eh_frame_patch.size, 172);
        let unwind_info_patch = activation
            .patches
            .iter()
            .find(|patch| patch.output_offset == output.unwind_info_offset)
            .unwrap();
        let entries =
            crate::macho_writer::parse_macho_unwind_info(&unwind_info_patch.data).unwrap();
        let live_entries = entries
            .iter()
            .filter(|entry| entry.encoding != 0)
            .collect::<Vec<_>>();
        assert_eq!(live_entries.len(), 2);
        assert!(live_entries.iter().any(|entry| {
            entry.personality_offset == Some(0x780) && entry.lsda_offset.is_some()
        }));

        let eh_frame = member.unwind.as_ref().unwrap().eh_frame.as_ref().unwrap();
        let personality = eh_frame
            .cies
            .iter()
            .find_map(|cie| cie.personality.as_ref())
            .unwrap();
        let personality_value = read_u32_le(
            &eh_frame_patch.data[personality.input_offset..personality.input_offset + 4],
        )
        .unwrap() as i32;
        let personality_field_address = crate::macho::MACHO_START_MEM_ADDRESS
            + output.eh_frame_offset
            + personality.input_offset as u64;
        assert_eq!(
            personality_value,
            (i128::from(resolution.got_address.unwrap())
                + i128::from(personality.relocation.explicit_addend)
                - i128::from(personality_field_address)) as i32
        );
        let lsda = eh_frame
            .fdes
            .iter()
            .find_map(|fde| fde.lsda.as_ref())
            .unwrap();
        let lsda_value =
            read_u64_le(&eh_frame_patch.data[lsda.input_offset..lsda.input_offset + 8]).unwrap();
        let AddedMachOArchiveUnwindTarget::Section(lsda_target) = &lsda.target else {
            panic!("expected section-defined LSDA target");
        };
        let signed_field_value = i64::from_le_bytes(lsda.relocation.field_value.to_le_bytes());
        let expected_lsda_value = i128::from(
            crate::macho::MACHO_START_MEM_ADDRESS
                + output.gcc_except_table_offset
                + lsda_target.section_offset,
        ) + i128::from(signed_field_value)
            + i128::from(lsda.relocation.explicit_addend)
            - i128::from(crate::macho::MACHO_START_MEM_ADDRESS + output.eh_frame_offset);
        assert_eq!(
            i128::from(i64::from_le_bytes(lsda_value.to_le_bytes())),
            expected_lsda_value
        );
    }

    fn test_added_macho_unwind_member(
        with_personality: bool,
    ) -> (AddedMachOArchiveTextMember, Vec<PatchSection>) {
        let bytes = test_observed_049_macho_unwind_object(with_personality);
        let file = object::File::parse(bytes.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let gcc_except_table = file.section_by_name("__gcc_except_tab").unwrap();
        let unwind = added_macho_archive_unwind(&file).unwrap().unwrap().unwrap();
        let input = "added.o".to_owned();
        let text_section_index = patch_section_record_index(&file, text.index()).unwrap();
        let sections = vec![
            PatchSection {
                input: input.clone(),
                section_index: text_section_index,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: text.size(),
                output_offset: 0,
                output_size: text.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            PatchSection {
                input: input.clone(),
                section_index: patch_section_record_index(&file, gcc_except_table.index()).unwrap(),
                section_name: Some("__TEXT,__gcc_except_tab".to_owned()),
                input_size: gcc_except_table.size(),
                output_offset: 0,
                output_size: gcc_except_table.size(),
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
        ];
        (
            AddedMachOArchiveTextMember {
                input,
                sections: Vec::new(),
                unwind: Some(unwind),
                text_section_index,
                text_object_section_index: relocation_target_record_index(text.index()).unwrap(),
                definitions: vec![AddedMachOArchiveDefinition {
                    name: b"_function0".to_vec(),
                    offset: 0,
                    desc: 0,
                    private_external: false,
                }],
                referenced_names: Vec::new(),
            },
            sections,
        )
    }

    struct TestMachOUnwindOutput {
        bytes: Vec<u8>,
        text_offset: u64,
        gcc_except_table_offset: u64,
        eh_frame_offset: u64,
        eh_frame_size: u64,
        unwind_info_offset: u64,
    }

    fn test_macho_unwind_output(unwind_info_size: usize) -> TestMachOUnwindOutput {
        const HEADER_SIZE: usize = 32;
        const SEGMENT_COMMAND_SIZE: usize = 72;
        const SECTION_SIZE: usize = 80;
        const SECTION_COUNT: usize = 4;
        const TEXT_SIZE: usize = 0x800;
        const GCC_EXCEPT_TABLE_SIZE: usize = 0x100;
        const EH_FRAME_SIZE: usize = 0x200;

        let commands_size = SEGMENT_COMMAND_SIZE + SECTION_COUNT * SECTION_SIZE;
        let text_offset = HEADER_SIZE + commands_size;
        let gcc_except_table_offset = text_offset + TEXT_SIZE;
        let eh_frame_offset = gcc_except_table_offset + GCC_EXCEPT_TABLE_SIZE;
        let unwind_info_offset = eh_frame_offset + EH_FRAME_SIZE;
        let file_size = unwind_info_offset + unwind_info_size;
        let image_start = crate::macho::MACHO_START_MEM_ADDRESS;
        let mut bytes = Vec::with_capacity(file_size);

        push_u32(&mut bytes, object::macho::MH_MAGIC_64);
        push_u32(&mut bytes, object::macho::CPU_TYPE_ARM64 as u32);
        push_u32(&mut bytes, object::macho::CPU_SUBTYPE_ARM64_ALL as u32);
        push_u32(&mut bytes, object::macho::MH_EXECUTE);
        push_u32(&mut bytes, 1);
        push_u32(&mut bytes, commands_size as u32);
        push_u32(&mut bytes, 0);
        push_u32(&mut bytes, 0);

        push_u32(&mut bytes, object::macho::LC_SEGMENT_64);
        push_u32(&mut bytes, commands_size as u32);
        push_fixed_name(&mut bytes, b"__TEXT");
        push_u64(&mut bytes, image_start);
        push_u64(&mut bytes, file_size as u64);
        push_u64(&mut bytes, 0);
        push_u64(&mut bytes, file_size as u64);
        push_u32(&mut bytes, 5);
        push_u32(&mut bytes, 5);
        push_u32(&mut bytes, SECTION_COUNT as u32);
        push_u32(&mut bytes, 0);

        for (name, offset, size, flags) in [
            (
                b"__text".as_slice(),
                text_offset,
                TEXT_SIZE,
                object::macho::S_REGULAR
                    | object::macho::S_ATTR_PURE_INSTRUCTIONS
                    | object::macho::S_ATTR_SOME_INSTRUCTIONS,
            ),
            (
                b"__gcc_except_tab".as_slice(),
                gcc_except_table_offset,
                GCC_EXCEPT_TABLE_SIZE,
                object::macho::S_REGULAR,
            ),
            (
                b"__eh_frame".as_slice(),
                eh_frame_offset,
                EH_FRAME_SIZE,
                object::macho::S_COALESCED,
            ),
            (
                b"__unwind_info".as_slice(),
                unwind_info_offset,
                unwind_info_size,
                object::macho::S_REGULAR,
            ),
        ] {
            push_macho_section(
                &mut bytes,
                name,
                b"__TEXT",
                image_start + offset as u64,
                size,
                offset,
                flags,
            );
        }
        bytes.resize(file_size, 0);
        TestMachOUnwindOutput {
            bytes,
            text_offset: text_offset as u64,
            gcc_except_table_offset: gcc_except_table_offset as u64,
            eh_frame_offset: eh_frame_offset as u64,
            eh_frame_size: EH_FRAME_SIZE as u64,
            unwind_info_offset: unwind_info_offset as u64,
        }
    }

    struct TestMachOImportOutput {
        bytes: Vec<u8>,
        text_offset: u64,
        stub_address: u64,
        got_address: u64,
    }

    fn test_macho_import_output() -> TestMachOImportOutput {
        const HEADER_SIZE: usize = 32;
        const SEGMENT_COMMAND_SIZE: usize = 72;
        const SECTION_SIZE: usize = 80;
        const SECTION_COUNT: usize = 3;
        const TEXT_SIZE: usize = 0x100;
        const STUB_SIZE: usize = 0x30;
        const GOT_SIZE: usize = 0x40;

        let commands_size = SEGMENT_COMMAND_SIZE + SECTION_COUNT * SECTION_SIZE;
        let text_offset = HEADER_SIZE + commands_size;
        let stubs_offset = text_offset + TEXT_SIZE;
        let got_offset = (stubs_offset + STUB_SIZE + 7) & !7;
        let file_size = got_offset + GOT_SIZE;
        let image_start = crate::macho::MACHO_START_MEM_ADDRESS;
        let stub_address = image_start + stubs_offset as u64;
        let got_address = image_start + got_offset as u64;
        let mut bytes = Vec::with_capacity(file_size);

        push_u32(&mut bytes, object::macho::MH_MAGIC_64);
        push_u32(&mut bytes, object::macho::CPU_TYPE_ARM64 as u32);
        push_u32(&mut bytes, object::macho::CPU_SUBTYPE_ARM64_ALL as u32);
        push_u32(&mut bytes, object::macho::MH_EXECUTE);
        push_u32(&mut bytes, 1);
        push_u32(&mut bytes, commands_size as u32);
        push_u32(&mut bytes, 0);
        push_u32(&mut bytes, 0);

        push_u32(&mut bytes, object::macho::LC_SEGMENT_64);
        push_u32(&mut bytes, commands_size as u32);
        push_fixed_name(&mut bytes, b"__TEXT");
        push_u64(&mut bytes, image_start);
        push_u64(&mut bytes, file_size as u64);
        push_u64(&mut bytes, 0);
        push_u64(&mut bytes, file_size as u64);
        push_u32(&mut bytes, 7);
        push_u32(&mut bytes, 5);
        push_u32(&mut bytes, SECTION_COUNT as u32);
        push_u32(&mut bytes, 0);

        for (name, segment, offset, size, flags) in [
            (
                b"__text".as_slice(),
                b"__TEXT".as_slice(),
                text_offset,
                TEXT_SIZE,
                object::macho::S_REGULAR
                    | object::macho::S_ATTR_PURE_INSTRUCTIONS
                    | object::macho::S_ATTR_SOME_INSTRUCTIONS,
            ),
            (
                b"__stubs".as_slice(),
                b"__TEXT".as_slice(),
                stubs_offset,
                STUB_SIZE,
                object::macho::S_SYMBOL_STUBS,
            ),
            (
                b"__got".as_slice(),
                b"__DATA_CONST".as_slice(),
                got_offset,
                GOT_SIZE,
                object::macho::S_NON_LAZY_SYMBOL_POINTERS,
            ),
        ] {
            push_macho_section(
                &mut bytes,
                name,
                segment,
                image_start + offset as u64,
                size,
                offset,
                flags,
            );
        }
        bytes.resize(file_size, 0);
        let place_page = stub_address & !linker_utils::elf::PAGE_MASK_4KB;
        let target_page = got_address & !linker_utils::elf::PAGE_MASK_4KB;
        let page_delta = ((i128::from(target_page) - i128::from(place_page)) >> 12) as i64;
        let immediate = (page_delta as u64) & 0x1f_ffff;
        let adrp = 0x9000_0000
            | 16
            | (((immediate & 0x3) as u32) << 29)
            | ((((immediate >> 2) & 0x7_ffff) as u32) << 5);
        let page_offset = got_address & linker_utils::elf::PAGE_MASK_4KB;
        let ldr = 0xf940_0000 | (((page_offset / 8) as u32) << 10) | (16 << 5) | 16;
        bytes[stubs_offset..stubs_offset + 4].copy_from_slice(&adrp.to_le_bytes());
        bytes[stubs_offset + 4..stubs_offset + 8].copy_from_slice(&ldr.to_le_bytes());
        bytes[stubs_offset + 8..stubs_offset + 12].copy_from_slice(&0xd61f_0200_u32.to_le_bytes());

        TestMachOImportOutput {
            bytes,
            text_offset: text_offset as u64,
            stub_address,
            got_address,
        }
    }

    fn apply_test_section_patches(output: &mut [u8], patches: &[SectionPatch]) {
        for patch in patches {
            let start = patch.output_offset as usize;
            let end = start + patch.data.len();
            output[start..end].copy_from_slice(&patch.data);
        }
    }

    fn test_added_macho_unwind_relocation(
        width: u8,
        field_value: u64,
        explicit_addend: i64,
        primary_type: u8,
        primary_pcrel: bool,
        has_subtractor: bool,
    ) -> AddedMachOArchiveUnwindRelocation {
        let length = width.ilog2() as u8;
        let subtractor = AddedMachOArchiveRawRelocation {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: false,
            r_length: length,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_SUBTRACTOR,
        };
        let primary = AddedMachOArchiveRawRelocation {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: primary_pcrel,
            r_length: length,
            r_extern: true,
            r_type: primary_type,
        };
        AddedMachOArchiveUnwindRelocation {
            input_offset: 0,
            width,
            explicit_addend,
            field_value,
            raw: if has_subtractor {
                vec![subtractor, primary]
            } else {
                vec![primary]
            },
            subtractor_target: has_subtractor.then_some(AddedMachOArchiveUnwindTarget::Section(
                AddedMachOArchiveUnwindSectionPosition {
                    section_index: 0,
                    section_offset: 0,
                },
            )),
        }
    }

    #[derive(Clone, Copy)]
    enum TestMachOCompactFixture {
        None,
        NativeOnly,
        Mixed,
    }

    struct TestMachOUnwindFixture {
        bytes: Vec<u8>,
        personality_field_offset: Option<usize>,
        first_pc_field_offset: Option<usize>,
        first_lsda_field_offset: Option<usize>,
        cie_fde_encoding_offset: Option<usize>,
        cie_augmentation_size_offset: Option<usize>,
        first_pc_primary_relocation_word_offset: Option<usize>,
    }

    #[derive(Clone, Copy)]
    struct TestMachORelocation {
        offset: u32,
        symbol: u32,
        pcrel: bool,
        length: u8,
        external: bool,
        r_type: u8,
    }

    fn test_macho_unwind_object(
        compact_fixture: TestMachOCompactFixture,
        include_eh_frame: bool,
    ) -> TestMachOUnwindFixture {
        const HEADER_SIZE: usize = 32;
        const SEGMENT_COMMAND_SIZE: usize = 72;
        const SECTION_SIZE: usize = 80;
        const SYMTAB_COMMAND_SIZE: usize = 24;
        const NLIST_64_SIZE: usize = 16;

        let mut compact_unwind = Vec::new();
        let mut compact_relocation_groups = Vec::new();
        if !matches!(compact_fixture, TestMachOCompactFixture::None) {
            compact_unwind.extend_from_slice(&0_u64.to_le_bytes());
            compact_unwind.extend_from_slice(&0x20_u32.to_le_bytes());
            compact_unwind.extend_from_slice(&0x0200_0000_u32.to_le_bytes());
            compact_unwind.extend_from_slice(&[0; 16]);
            compact_relocation_groups.push(vec![TestMachORelocation {
                offset: 0,
                symbol: 0,
                pcrel: false,
                length: 3,
                external: true,
                r_type: object::macho::ARM64_RELOC_UNSIGNED,
            }]);
        }
        if matches!(compact_fixture, TestMachOCompactFixture::Mixed) {
            compact_unwind.extend_from_slice(&0_u64.to_le_bytes());
            compact_unwind.extend_from_slice(&0x20_u32.to_le_bytes());
            compact_unwind
                .extend_from_slice(&(ADDED_MACHO_UNWIND_MODE_DWARF | 0x123).to_le_bytes());
            compact_unwind.extend_from_slice(&[0; 16]);
            compact_relocation_groups.push(vec![
                test_macho_addend_relocation(0x20, 0x20, 3),
                TestMachORelocation {
                    offset: 0x20,
                    symbol: 0,
                    pcrel: false,
                    length: 3,
                    external: true,
                    r_type: object::macho::ARM64_RELOC_UNSIGNED,
                },
            ]);
        }

        let mut eh_frame = Vec::new();
        let mut eh_relocation_groups = Vec::new();
        let mut personality_field_offset = None;
        let mut first_pc_field_offset = None;
        let mut first_lsda_field_offset = None;
        let mut cie_fde_encoding_section_offset = None;
        let mut cie_augmentation_size_section_offset = None;
        if include_eh_frame {
            let cie_start = eh_frame.len();
            push_u32(&mut eh_frame, 0);
            push_u32(&mut eh_frame, 0);
            eh_frame.push(1);
            eh_frame.extend_from_slice(b"zPLR\0");
            eh_frame.extend_from_slice(&[1, 0x78, 30]);
            cie_augmentation_size_section_offset = Some(eh_frame.len());
            eh_frame.push(7);
            eh_frame.push(0x9b);
            personality_field_offset = Some(eh_frame.len());
            eh_frame.extend_from_slice(&0_u32.to_le_bytes());
            eh_frame.push(0x1b);
            cie_fde_encoding_section_offset = Some(eh_frame.len());
            eh_frame.push(0x1b);
            eh_frame.extend_from_slice(&[0x0c, 0x1f, 0]);
            write_test_eh_frame_length(&mut eh_frame, cie_start);

            let fde_start = eh_frame.len();
            push_u32(&mut eh_frame, 0);
            push_u32(&mut eh_frame, (fde_start + 4 - cie_start) as u32);
            first_pc_field_offset = Some(eh_frame.len());
            eh_frame.extend_from_slice(&0_u32.to_le_bytes());
            eh_frame.extend_from_slice(&0x20_u32.to_le_bytes());
            eh_frame.push(4);
            first_lsda_field_offset = Some(eh_frame.len());
            eh_frame.extend_from_slice(&0_u32.to_le_bytes());
            write_test_eh_frame_length(&mut eh_frame, fde_start);

            let second_fde_start = eh_frame.len();
            push_u32(&mut eh_frame, 0);
            push_u32(&mut eh_frame, (second_fde_start + 4 - cie_start) as u32);
            let second_pc_offset = eh_frame.len();
            eh_frame.extend_from_slice(&0_u32.to_le_bytes());
            eh_frame.extend_from_slice(&0x20_u32.to_le_bytes());
            eh_frame.push(4);
            eh_frame.extend_from_slice(&0_u32.to_le_bytes());
            write_test_eh_frame_length(&mut eh_frame, second_fde_start);

            let wide_cie_start = eh_frame.len();
            push_u32(&mut eh_frame, 0);
            push_u32(&mut eh_frame, 0);
            eh_frame.push(1);
            eh_frame.extend_from_slice(b"zR\0");
            eh_frame.extend_from_slice(&[1, 0x78, 30, 1, 0x10, 0]);
            write_test_eh_frame_length(&mut eh_frame, wide_cie_start);

            let wide_fde_start = eh_frame.len();
            push_u32(&mut eh_frame, 0);
            push_u32(&mut eh_frame, (wide_fde_start + 4 - wide_cie_start) as u32);
            let wide_pc_offset = eh_frame.len();
            eh_frame.extend_from_slice(&0_u64.to_le_bytes());
            eh_frame.extend_from_slice(&0x20_u64.to_le_bytes());
            eh_frame.push(0);
            write_test_eh_frame_length(&mut eh_frame, wide_fde_start);
            push_u32(&mut eh_frame, 0);

            let eh_symbol = 4;
            let personality_symbol = 5;
            eh_relocation_groups.push(vec![TestMachORelocation {
                offset: personality_field_offset.unwrap() as u32,
                symbol: personality_symbol,
                pcrel: true,
                length: 2,
                external: true,
                r_type: object::macho::ARM64_RELOC_POINTER_TO_GOT,
            }]);
            eh_relocation_groups.push(vec![
                test_macho_addend_relocation(first_pc_field_offset.unwrap() as u32, 0x20, 2),
                test_macho_subtractor_relocation(
                    first_pc_field_offset.unwrap() as u32,
                    eh_symbol,
                    2,
                ),
                test_macho_unsigned_relocation(first_pc_field_offset.unwrap() as u32, 0, 2),
            ]);
            eh_relocation_groups.push(vec![
                test_macho_addend_relocation(first_lsda_field_offset.unwrap() as u32, 4, 2),
                test_macho_subtractor_relocation(
                    first_lsda_field_offset.unwrap() as u32,
                    eh_symbol,
                    2,
                ),
                test_macho_unsigned_relocation(first_lsda_field_offset.unwrap() as u32, 3, 2),
            ]);
            eh_relocation_groups.push(vec![
                test_macho_subtractor_relocation(second_pc_offset as u32, eh_symbol, 2),
                test_macho_unsigned_relocation(second_pc_offset as u32, 2, 2),
            ]);
            eh_relocation_groups.push(vec![
                test_macho_subtractor_relocation(wide_pc_offset as u32, eh_symbol, 3),
                test_macho_unsigned_relocation(wide_pc_offset as u32, 0, 3),
            ]);
        }

        compact_relocation_groups.sort_by_key(|group| std::cmp::Reverse(group[0].offset));
        eh_relocation_groups.sort_by_key(|group| std::cmp::Reverse(group[0].offset));
        let compact_relocations = compact_relocation_groups
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let eh_relocations = eh_relocation_groups
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();

        let text = vec![0; 0x80];
        let gcc_except_table = vec![0; 0x10];
        let has_compact = !compact_unwind.is_empty();
        let section_count = 2 + usize::from(has_compact) + usize::from(include_eh_frame);
        let commands_size =
            SEGMENT_COMMAND_SIZE + section_count * SECTION_SIZE + SYMTAB_COMMAND_SIZE;
        let text_offset = HEADER_SIZE + commands_size;
        let gcc_except_table_offset = text_offset + text.len();
        let compact_unwind_offset = gcc_except_table_offset + gcc_except_table.len();
        let eh_frame_offset = compact_unwind_offset + compact_unwind.len();
        let compact_relocation_offset = (eh_frame_offset + eh_frame.len()).next_multiple_of(8);
        let eh_relocation_offset = compact_relocation_offset + compact_relocations.len() * 8;
        let symoff = (eh_relocation_offset + eh_relocations.len() * 8).next_multiple_of(8);
        let symbol_count = 4 + usize::from(include_eh_frame) * 2;
        let stroff = symoff + symbol_count * NLIST_64_SIZE;

        let mut strings = vec![0];
        let mut add_string = |name: &[u8]| {
            let offset = strings.len() as u32;
            strings.extend_from_slice(name);
            strings.push(0);
            offset
        };
        let function0_name = add_string(b"_function0");
        let function1_name = add_string(b"_function1");
        let function2_name = add_string(b"_function2");
        let lsda_name = add_string(b"_lsda");
        let eh_frame_name = include_eh_frame.then(|| add_string(b"_eh_frame"));
        let personality_name = include_eh_frame.then(|| add_string(b"_rust_eh_personality"));

        let text_address = 0;
        let gcc_except_table_address = text.len() as u64;
        let compact_unwind_address = gcc_except_table_address + gcc_except_table.len() as u64;
        let eh_frame_address = compact_unwind_address + compact_unwind.len() as u64;
        let segment_size =
            text.len() + gcc_except_table.len() + compact_unwind.len() + eh_frame.len();
        let eh_frame_section_index = include_eh_frame.then_some(3_u8 + u8::from(has_compact));

        let mut bytes = Vec::new();
        push_u32(&mut bytes, object::macho::MH_MAGIC_64);
        push_u32(&mut bytes, object::macho::CPU_TYPE_ARM64 as u32);
        push_u32(&mut bytes, object::macho::CPU_SUBTYPE_ARM64_ALL as u32);
        push_u32(&mut bytes, object::macho::MH_OBJECT);
        push_u32(&mut bytes, 2);
        push_u32(&mut bytes, commands_size as u32);
        push_u32(&mut bytes, object::macho::MH_SUBSECTIONS_VIA_SYMBOLS);
        push_u32(&mut bytes, 0);

        push_u32(&mut bytes, object::macho::LC_SEGMENT_64);
        push_u32(
            &mut bytes,
            (SEGMENT_COMMAND_SIZE + section_count * SECTION_SIZE) as u32,
        );
        push_fixed_name(&mut bytes, b"");
        push_u64(&mut bytes, 0);
        push_u64(&mut bytes, segment_size as u64);
        push_u64(&mut bytes, text_offset as u64);
        push_u64(&mut bytes, segment_size as u64);
        push_u32(&mut bytes, 7);
        push_u32(&mut bytes, 7);
        push_u32(&mut bytes, section_count as u32);
        push_u32(&mut bytes, 0);

        push_macho_section_with_relocations(
            &mut bytes,
            b"__text",
            b"__TEXT",
            text_address,
            text.len(),
            text_offset,
            0,
            0,
            object::macho::S_REGULAR
                | object::macho::S_ATTR_PURE_INSTRUCTIONS
                | object::macho::S_ATTR_SOME_INSTRUCTIONS,
        );
        push_macho_section_with_relocations(
            &mut bytes,
            b"__gcc_except_tab",
            b"__TEXT",
            gcc_except_table_address,
            gcc_except_table.len(),
            gcc_except_table_offset,
            0,
            0,
            object::macho::S_REGULAR,
        );
        if has_compact {
            push_macho_section_with_relocations(
                &mut bytes,
                b"__compact_unwind",
                b"__LD",
                compact_unwind_address,
                compact_unwind.len(),
                compact_unwind_offset,
                compact_relocation_offset,
                compact_relocations.len(),
                object::macho::S_REGULAR | object::macho::S_ATTR_DEBUG,
            );
        }
        if include_eh_frame {
            push_macho_section_with_relocations(
                &mut bytes,
                b"__eh_frame",
                b"__TEXT",
                eh_frame_address,
                eh_frame.len(),
                eh_frame_offset,
                eh_relocation_offset,
                eh_relocations.len(),
                object::macho::S_COALESCED,
            );
        }

        push_u32(&mut bytes, object::macho::LC_SYMTAB);
        push_u32(&mut bytes, SYMTAB_COMMAND_SIZE as u32);
        push_u32(&mut bytes, symoff as u32);
        push_u32(&mut bytes, symbol_count as u32);
        push_u32(&mut bytes, stroff as u32);
        push_u32(&mut bytes, strings.len() as u32);

        assert_eq!(bytes.len(), text_offset);
        bytes.extend_from_slice(&text);
        bytes.extend_from_slice(&gcc_except_table);
        bytes.extend_from_slice(&compact_unwind);
        bytes.extend_from_slice(&eh_frame);
        bytes.resize(compact_relocation_offset, 0);
        for relocation in &compact_relocations {
            push_test_macho_relocation(&mut bytes, *relocation);
        }
        assert_eq!(bytes.len(), eh_relocation_offset);
        let mut first_pc_primary_relocation_word_offset = None;
        for relocation in &eh_relocations {
            let word_offset = bytes.len() + 4;
            if Some(relocation.offset as usize) == first_pc_field_offset
                && relocation.r_type == object::macho::ARM64_RELOC_UNSIGNED
            {
                first_pc_primary_relocation_word_offset = Some(word_offset);
            }
            push_test_macho_relocation(&mut bytes, *relocation);
        }

        bytes.resize(symoff, 0);
        push_macho_symbol(&mut bytes, function0_name, 1, text_address);
        push_macho_local_symbol(&mut bytes, function1_name, 1, text_address + 0x20);
        push_macho_local_symbol(&mut bytes, function2_name, 1, text_address + 0x40);
        push_macho_local_symbol(&mut bytes, lsda_name, 2, gcc_except_table_address);
        if include_eh_frame {
            push_macho_local_symbol(
                &mut bytes,
                eh_frame_name.unwrap(),
                eh_frame_section_index.unwrap(),
                eh_frame_address,
            );
            push_macho_undefined_symbol(&mut bytes, personality_name.unwrap());
        }
        bytes.extend_from_slice(&strings);

        TestMachOUnwindFixture {
            bytes,
            personality_field_offset,
            first_pc_field_offset,
            first_lsda_field_offset,
            cie_fde_encoding_offset: cie_fde_encoding_section_offset
                .map(|offset| eh_frame_offset + offset),
            cie_augmentation_size_offset: cie_augmentation_size_section_offset
                .map(|offset| eh_frame_offset + offset),
            first_pc_primary_relocation_word_offset,
        }
    }

