    fn write_test_eh_frame_length(bytes: &mut [u8], entry_start: usize) {
        let length = u32::try_from(bytes.len() - entry_start - 4).unwrap();
        bytes[entry_start..entry_start + 4].copy_from_slice(&length.to_le_bytes());
    }

    fn test_macho_addend_relocation(offset: u32, addend: i32, length: u8) -> TestMachORelocation {
        TestMachORelocation {
            offset,
            symbol: (addend as u32) & 0x00ff_ffff,
            pcrel: false,
            length,
            external: false,
            r_type: object::macho::ARM64_RELOC_ADDEND,
        }
    }

    fn test_macho_subtractor_relocation(
        offset: u32,
        symbol: u32,
        length: u8,
    ) -> TestMachORelocation {
        TestMachORelocation {
            offset,
            symbol,
            pcrel: false,
            length,
            external: true,
            r_type: object::macho::ARM64_RELOC_SUBTRACTOR,
        }
    }

    fn test_macho_unsigned_relocation(offset: u32, symbol: u32, length: u8) -> TestMachORelocation {
        TestMachORelocation {
            offset,
            symbol,
            pcrel: false,
            length,
            external: true,
            r_type: object::macho::ARM64_RELOC_UNSIGNED,
        }
    }

    fn push_test_macho_relocation(bytes: &mut Vec<u8>, relocation: TestMachORelocation) {
        push_u32(bytes, relocation.offset);
        push_u32(
            bytes,
            relocation.symbol
                | u32::from(relocation.pcrel) << 24
                | u32::from(relocation.length) << 25
                | u32::from(relocation.external) << 27
                | u32::from(relocation.r_type) << 28,
        );
    }

    fn set_test_macho_text_relocation_type(bytes: &mut [u8], relocation_type: u8) {
        let previous = 1_u32
            | 1 << 24
            | 2 << 25
            | 1 << 27
            | u32::from(object::macho::ARM64_RELOC_PAGE21) << 28;
        let current = previous & 0x0fff_ffff | u32::from(relocation_type) << 28;
        let matches = bytes
            .windows(4)
            .enumerate()
            .filter_map(|(offset, bytes)| (bytes == previous.to_le_bytes()).then_some(offset))
            .collect::<Vec<_>>();
        let [offset] = matches.as_slice() else {
            panic!("expected one test Mach-O text relocation, found {matches:?}");
        };
        bytes[*offset..*offset + 4].copy_from_slice(&current.to_le_bytes());
    }

    fn set_test_macho_text_relocation_offset(bytes: &mut [u8], relocation_offset: u32) {
        let relocation = 1_u32
            | 1 << 24
            | 2 << 25
            | 1 << 27
            | u32::from(object::macho::ARM64_RELOC_PAGE21) << 28;
        let matches = bytes
            .windows(4)
            .enumerate()
            .filter_map(|(offset, bytes)| (bytes == relocation.to_le_bytes()).then_some(offset))
            .collect::<Vec<_>>();
        let [offset] = matches.as_slice() else {
            panic!("expected one test Mach-O text relocation, found {matches:?}");
        };
        let address = offset.checked_sub(4).unwrap();
        bytes[address..address + 4].copy_from_slice(&relocation_offset.to_le_bytes());
    }

    fn duplicate_test_macho_text_relocations(mut bytes: Vec<u8>, count: usize) -> Vec<u8> {
        const HEADER_SIZE: usize = 32;
        const SEGMENT_COMMAND_SIZE: usize = 72;
        const SECTION_RELOCATION_OFFSET: usize = 56;
        const SECTION_RELOCATION_COUNT_OFFSET: usize = 60;

        assert!(count > 0);
        let command_count = read_u32_le(&bytes[16..20]).unwrap();
        let mut command_offset = HEADER_SIZE;
        let mut segment_command = None;
        let mut symtab_command = None;
        for _ in 0..command_count {
            let command = read_u32_le(&bytes[command_offset..command_offset + 4]).unwrap();
            let command_size =
                read_u32_le(&bytes[command_offset + 4..command_offset + 8]).unwrap() as usize;
            match command {
                object::macho::LC_SEGMENT_64 => segment_command = Some(command_offset),
                object::macho::LC_SYMTAB => symtab_command = Some(command_offset),
                _ => {}
            }
            command_offset += command_size;
        }
        let text_section = segment_command.unwrap() + SEGMENT_COMMAND_SIZE;
        let relocation_offset = read_u32_le(
            &bytes[text_section + SECTION_RELOCATION_OFFSET
                ..text_section + SECTION_RELOCATION_OFFSET + 4],
        )
        .unwrap() as usize;
        assert_eq!(
            read_u32_le(
                &bytes[text_section + SECTION_RELOCATION_COUNT_OFFSET
                    ..text_section + SECTION_RELOCATION_COUNT_OFFSET + 4],
            )
            .unwrap(),
            1,
        );
        let relocation_flags =
            read_u32_le(&bytes[relocation_offset + 4..relocation_offset + 8]).unwrap();
        let mut extra = Vec::with_capacity((count - 1) * 8);
        for index in 1..count {
            push_u32(&mut extra, u32::try_from(index * 4).unwrap());
            push_u32(&mut extra, relocation_flags);
        }
        let extra_len = extra.len();
        bytes.splice(relocation_offset + 8..relocation_offset + 8, extra);
        bytes[text_section + SECTION_RELOCATION_COUNT_OFFSET
            ..text_section + SECTION_RELOCATION_COUNT_OFFSET + 4]
            .copy_from_slice(&u32::try_from(count).unwrap().to_le_bytes());

        let symtab_command = symtab_command.unwrap();
        for field in [8, 16] {
            let value =
                read_u32_le(&bytes[symtab_command + field..symtab_command + field + 4]).unwrap();
            bytes[symtab_command + field..symtab_command + field + 4].copy_from_slice(
                &value
                    .checked_add(u32::try_from(extra_len).unwrap())
                    .unwrap()
                    .to_le_bytes(),
            );
        }
        bytes
    }

    fn set_test_macho_symbol_desc(bytes: &mut [u8], name: &[u8], n_desc: u16) {
        let entry = test_macho_symbol_entry_offset(bytes, name);
        bytes[entry + 6..entry + 8].copy_from_slice(&n_desc.to_le_bytes());
    }

    fn set_first_test_macho_text_relocation_flags(
        bytes: &mut [u8],
        symbol: u32,
        external: bool,
        r_type: u8,
    ) {
        const TEXT_SECTION_RELOCATION_OFFSET: usize = 32 + 72 + 56;
        let relocation_offset =
            read_u32_le(&bytes[TEXT_SECTION_RELOCATION_OFFSET..TEXT_SECTION_RELOCATION_OFFSET + 4])
                .unwrap() as usize;
        let flags =
            symbol | 1 << 24 | 2 << 25 | u32::from(external) << 27 | u32::from(r_type) << 28;
        bytes[relocation_offset + 4..relocation_offset + 8].copy_from_slice(&flags.to_le_bytes());
    }

