    #[test]
    fn local_macho_text_target_ownership_rejects_moved_unrooted_symbol_population() {
        let previous_identifier = b"uv-hash.cgu.old.rcgu.o";
        let current_identifier = b"uv-hash.cgu.new.rcgu.o";
        let enable_subsections = |mut object: Vec<u8>| {
            object[24..28]
                .copy_from_slice(&object::macho::MH_SUBSECTIONS_VIA_SYMBOLS.to_le_bytes());
            object
        };

        let mut fixture = local_text_target_transition_fixture(
            b"l_a.1",
            b"l_b.2",
            b"A-target",
            b"B-target",
            0,
            4,
        );
        publish_stable_local_transition_symbols(&mut fixture, b"l_a.1", 0, b"l_b.2", 4);
        fixture.previous = mutate_test_macho_archive_member(
            &fixture.previous,
            previous_identifier,
            enable_subsections,
        );
        fixture.current =
            mutate_test_macho_archive_member(&fixture.current, current_identifier, |mut object| {
                object = enable_subsections(object);
                let entry = test_macho_symbol_entry_offset(&object, b"l_a.1");
                object[entry + 8..entry + 16].copy_from_slice(&10_u64.to_le_bytes());
                object
            });
        assert!(
            apply_local_text_target_transition(&fixture, vec![fixture.relocation.clone()], true,)
                .unwrap_err()
                .starts_with(MACHO_LOCAL_COHORT_LIVENESS_REQUIRED),
        );

        let population_change = |name: &'static [u8], n_desc: u16| {
            let mut added = local_text_target_transition_fixture(
                b"l_a.1",
                b"l_b.2",
                b"A-target",
                b"B-target",
                0,
                4,
            );
            publish_stable_local_transition_symbols(&mut added, b"l_a.1", 0, b"l_b.2", 4);
            added.previous = mutate_test_macho_archive_member(
                &added.previous,
                previous_identifier,
                enable_subsections,
            );
            added.current = mutate_test_macho_archive_member(
                &added.current,
                current_identifier,
                |mut object| {
                    object = enable_subsections(object);
                    let entry = test_macho_symbol_entry_offset(&object, b"l_a.1");
                    object[entry + 8..entry + 16].copy_from_slice(&10_u64.to_le_bytes());
                    object = add_test_macho_local_alias(object, name, 2, 11);
                    let entry = test_macho_symbol_entry_offset(&object, name);
                    object[entry + 6..entry + 8].copy_from_slice(&n_desc.to_le_bytes());
                    object
                },
            );
            added
        };
        let added = population_change(b"new.dead", 0);
        assert!(
            apply_local_text_target_transition(&added, vec![added.relocation.clone()], true)
                .unwrap_err()
                .starts_with(MACHO_LOCAL_COHORT_LIVENESS_REQUIRED),
        );

        for n_desc in [
            object::macho::N_WEAK_DEF,
            object::macho::N_NO_DEAD_STRIP,
            object::macho::N_ALT_ENTRY,
        ] {
            let hostile = population_change(b"ltmp7", n_desc);
            let reason = apply_local_text_target_transition(
                &hostile,
                vec![hostile.relocation.clone()],
                true,
            )
            .unwrap_err();
            assert!(
                reason.starts_with(MACHO_LOCAL_COHORT_LIVENESS_REQUIRED)
                    || reason
                        == "renamed local Mach-O text target is present in the output symbol table",
                "unexpected rejection reason: {reason}",
            );
        }
    }

    #[test]
