    #[test]
    fn archive_migration_names_require_distinct_exact_member_owners() {
        let input_file = hex::encode("libexample.rlib");
        let member = test_macho_object(b"text", b"data", 0);
        let archive = |identifier: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), member.len() as u64),
                    member.as_slice(),
                )
                .unwrap();
            builder.into_inner().unwrap()
        };
        let previous_archive = archive(b"crate-old.source.rcgu.o");
        let current_archive = archive(b"crate-new.destination.rcgu.o");
        let input_ref = |bytes: &[u8], identifier: &[u8]| {
            let ArchiveMemberMatch::Unique(input) =
                patch_archive_member_bytes(bytes, identifier).unwrap()
            else {
                panic!("expected one archive member");
            };
            resolved_patch_input_ref(&input_file, &input_file, input).unwrap()
        };
        let previous_input = input_ref(&previous_archive, b"crate-old.source.rcgu.o");
        let current_input = input_ref(&current_archive, b"crate-new.destination.rcgu.o");
        let target = |input: String| RelocationTargetRecord {
            input_file: input_file.clone().into(),
            input: input.into(),
            section_index: 1,
            section_offset: 0,
        };
        let moved = MachOSymbolResolutionMove {
            name: hex::encode("_migrated").into(),
            previous_value: 0x1000,
            current_value: 0x2000,
            previous_target: target(previous_input.clone()),
            current_target: target(current_input),
        };
        assert_eq!(
            migrated_macho_archive_definition_names(&input_file, &[moved.clone()]).unwrap(),
            HashSet::from([b"_migrated".to_vec()]),
        );
        let same_owner = MachOSymbolResolutionMove {
            current_target: target(previous_input),
            ..moved
        };
        assert!(
            migrated_macho_archive_definition_names(&input_file, &[same_owner])
                .unwrap()
                .is_empty(),
        );
    }

    #[test]
    fn changed_archive_unwind_fingerprint_composes_with_resolution_move() {
        let input_file = hex::encode("libexample.rlib");
        let defined = test_macho_object(b"text", b"data", 0);
        let retired = retire_test_macho_symbol(defined.clone(), 0);
        let source_identifier = b"crate.source.rcgu.o";
        let destination_identifier = b"crate.destination.rcgu.o";
        let archive = |source: &[u8], destination: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, member) in [
                (source_identifier.as_slice(), source),
                (destination_identifier.as_slice(), destination),
            ] {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), member.len() as u64),
                        member,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let previous = archive(&defined, &retired);
        let current = archive(&retired, &defined);
        let input_ref = |bytes: &[u8], identifier: &[u8]| {
            let ArchiveMemberMatch::Unique(input) =
                patch_archive_member_bytes(bytes, identifier).unwrap()
            else {
                panic!("expected one archive member");
            };
            resolved_patch_input_ref(&input_file, &input_file, input).unwrap()
        };
        let previous_source = input_ref(&previous, source_identifier);
        let previous_destination = input_ref(&previous, destination_identifier);
        let current_source = input_ref(&current, source_identifier);
        let current_destination = input_ref(&current, destination_identifier);
        let file = object::File::parse(defined.as_slice()).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let section = |input: String| PatchSection {
            input,
            section_index: patch_section_record_index(&file, text.index()).unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: text.size(),
            output_offset: 0,
            output_size: text.size(),
            data_hash: None,
            cstring_nul_boundaries_hash: None,
        };
        let matched = vec![
            MatchedPatchSection {
                previous: section(previous_source.clone()),
                current: section(current_source),
            },
            MatchedPatchSection {
                previous: section(previous_destination),
                current: section(current_destination.clone()),
            },
        ];
        let target = |input: String| RelocationTargetRecord {
            input_file: input_file.clone().into(),
            input: input.into(),
            section_index: 1,
            section_offset: 0,
        };
        let moved = MachOSymbolResolutionMove {
            name: hex::encode("_text").into(),
            previous_value: 0x1000,
            current_value: 0x2000,
            previous_target: target(previous_source),
            current_target: target(current_destination),
        };
        let migrated = migrated_macho_archive_definition_names(&input_file, &[moved]).unwrap();
        let changed = ChangedMachOArchiveUnwindMembers {
            members: Vec::new(),
            previous_common_members: Vec::new(),
            current_common_members: Vec::new(),
            retired_entries: Vec::new(),
            current_sections: Vec::new(),
            previous_input_ranges: Vec::new(),
            current_input_ranges: Vec::new(),
        };
        let current_resolver = PatchInputResolver::new(&current, true).unwrap();

        assert!(
            !archive_diff_allows_changed_macho_unwind(
                &previous,
                &current,
                &input_file,
                &matched,
                &current_resolver,
                &changed,
                &[],
                &[],
                &HashSet::new(),
                &[],
            )
            .unwrap(),
        );
        assert!(
            archive_diff_allows_changed_macho_unwind(
                &previous,
                &current,
                &input_file,
                &matched,
                &current_resolver,
                &changed,
                &[],
                &[],
                &migrated,
                &[],
            )
            .unwrap(),
        );

        let archive_with_duplicate = |source: &[u8], destination: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, member) in [
                (source_identifier.as_slice(), source),
                (destination_identifier.as_slice(), destination),
                (b"crate.duplicate.rcgu.o".as_slice(), defined.as_slice()),
            ] {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), member.len() as u64),
                        member,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let duplicate_previous = archive_with_duplicate(&defined, &retired);
        let duplicate_current = archive_with_duplicate(&retired, &defined);
        let previous_source = input_ref(&duplicate_previous, source_identifier);
        let previous_destination = input_ref(&duplicate_previous, destination_identifier);
        let current_source = input_ref(&duplicate_current, source_identifier);
        let current_destination = input_ref(&duplicate_current, destination_identifier);
        let duplicate_matched = vec![
            MatchedPatchSection {
                previous: section(previous_source.clone()),
                current: section(current_source),
            },
            MatchedPatchSection {
                previous: section(previous_destination),
                current: section(current_destination.clone()),
            },
        ];
        let duplicate_move = MachOSymbolResolutionMove {
            name: hex::encode("_text").into(),
            previous_value: 0x1000,
            current_value: 0x2000,
            previous_target: target(previous_source),
            current_target: target(current_destination),
        };
        let duplicate_migrated =
            migrated_macho_archive_definition_names(&input_file, &[duplicate_move]).unwrap();
        assert!(
            !archive_diff_allows_changed_macho_unwind(
                &duplicate_previous,
                &duplicate_current,
                &input_file,
                &duplicate_matched,
                &PatchInputResolver::new(&duplicate_current, true).unwrap(),
                &changed,
                &[],
                &[],
                &duplicate_migrated,
                &[],
            )
            .unwrap(),
            "a name-wide migration exception requires one exact definition per archive",
        );
    }

    #[test]
    fn direct_macho_cgu_migration_retargets_absolute_relocation() {
        let (inputs, sections, resolutions, output) = direct_macho_cgu_migration_fixture();
        let mut plan = plan_direct_macho_cgu_migrations(
            &inputs,
            &[],
            &direct_macho_changed_input_files(&inputs),
            &sections,
            &resolutions,
            &output,
            &[],
            &[],
            false,
        )
        .unwrap()
        .unwrap();
        let moved = plan.moves[0].clone();
        let output_offset = sections[0].output_offset + 0x200;
        let mut relocations = vec![RelocationRecord {
            target_symbol_id: 1,
            written_value: Some(moved.previous_value),
            target_value: moved.previous_value,
            applied_target_value: Some(moved.previous_value),
            target_name: Some(moved.name.clone()),
            target: Some(moved.previous_target.clone()),
            input_file: "caller.o".into(),
            input: "caller.o".into(),
            section_index: 1,
            relocation_offset: 0,
            output_offset,
            size: 8,
            kind: encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
                r_address: 0,
                r_symbolnum: 0,
                r_pcrel: false,
                r_length: 3,
                r_extern: true,
                r_type: object::macho::ARM64_RELOC_UNSIGNED,
            }),
            addend: 0,
        }];

        apply_direct_macho_cgu_relocation_migrations(&mut relocations, &mut plan, &output).unwrap();
        assert_eq!(relocations[0].target_value, moved.current_value);
        assert_eq!(relocations[0].target, Some(moved.current_target));
        assert_eq!(plan.output_patches.len(), 1);
        assert_eq!(
            plan.output_patches[0].data,
            moved.current_value.to_le_bytes()
        );
        assert!(plan.relocation_record_owners.contains("caller.o"));
    }

    fn test_macho_data_object(
        data: &[u8],
        added_text: Option<&[u8]>,
        added_text_symbol: bool,
    ) -> Vec<u8> {
        const HEADER_SIZE: usize = 32;
        const SEGMENT_COMMAND_SIZE: usize = 72;
        const SECTION_SIZE: usize = 80;
        const SYMTAB_COMMAND_SIZE: usize = 24;
        const NLIST_64_SIZE: usize = 16;

        let section_count = 1 + usize::from(added_text.is_some());
        let symbol_count = 1 + usize::from(added_text.is_some()) + usize::from(added_text_symbol);
        let commands_size =
            SEGMENT_COMMAND_SIZE + section_count * SECTION_SIZE + SYMTAB_COMMAND_SIZE;
        let data_offset = HEADER_SIZE + commands_size;
        let text_offset = data_offset + data.len();
        let text_len = added_text.map_or(0, <[u8]>::len);
        let symoff = (text_offset + text_len).next_multiple_of(8);
        let stroff = symoff + symbol_count * NLIST_64_SIZE;
        let strings = b"\0_data\0ltmp0\0_added_text\0";
        let mut bytes = Vec::new();

        push_u32(&mut bytes, object::macho::MH_MAGIC_64);
        push_u32(&mut bytes, object::macho::CPU_TYPE_ARM64 as u32);
        push_u32(&mut bytes, object::macho::CPU_SUBTYPE_ARM64_ALL as u32);
        push_u32(&mut bytes, object::macho::MH_OBJECT);
        push_u32(&mut bytes, 2);
        push_u32(&mut bytes, commands_size as u32);
        push_u32(&mut bytes, object::macho::MH_SUBSECTIONS_VIA_SYMBOLS);
        push_u32(&mut bytes, 0);

        push_u32(&mut bytes, object::macho::LC_SEGMENT_64);
        push_u32(
            &mut bytes,
            (SEGMENT_COMMAND_SIZE + section_count * SECTION_SIZE) as u32,
        );
        push_fixed_name(&mut bytes, b"");
        push_u64(&mut bytes, 0);
        push_u64(&mut bytes, (data.len() + text_len) as u64);
        push_u64(&mut bytes, data_offset as u64);
        push_u64(&mut bytes, (data.len() + text_len) as u64);
        push_u32(&mut bytes, 7);
        push_u32(&mut bytes, 7);
        push_u32(&mut bytes, section_count as u32);
        push_u32(&mut bytes, 0);

        push_macho_section(
            &mut bytes,
            b"__data",
            b"__DATA",
            0,
            data.len(),
            data_offset,
            object::macho::S_REGULAR,
        );
        if let Some(text) = added_text {
            push_macho_section(
                &mut bytes,
                b"__text",
                b"__TEXT",
                data.len() as u64,
                text.len(),
                text_offset,
                object::macho::S_REGULAR
                    | object::macho::S_ATTR_PURE_INSTRUCTIONS
                    | object::macho::S_ATTR_SOME_INSTRUCTIONS,
            );
        }

        push_u32(&mut bytes, object::macho::LC_SYMTAB);
        push_u32(&mut bytes, SYMTAB_COMMAND_SIZE as u32);
        push_u32(&mut bytes, symoff as u32);
        push_u32(&mut bytes, symbol_count as u32);
        push_u32(&mut bytes, stroff as u32);
        push_u32(&mut bytes, strings.len() as u32);

        assert_eq!(bytes.len(), data_offset);
        bytes.extend_from_slice(data);
        if let Some(text) = added_text {
            bytes.extend_from_slice(text);
        }
        bytes.resize(symoff, 0);
        push_macho_symbol(&mut bytes, 1, 1, 0);
        if added_text.is_some() {
            push_macho_local_symbol(&mut bytes, 7, 2, data.len() as u64);
        }
        if added_text_symbol {
            push_macho_symbol(&mut bytes, 13, 2, data.len() as u64);
        }
        bytes.extend_from_slice(strings);
        bytes
    }

    fn push_macho_section(
        bytes: &mut Vec<u8>,
        name: &[u8],
        segment: &[u8],
        address: u64,
        size: usize,
        offset: usize,
        flags: u32,
    ) {
        push_fixed_name(bytes, name);
        push_fixed_name(bytes, segment);
        push_u64(bytes, address);
        push_u64(bytes, size as u64);
        push_u32(bytes, offset as u32);
        push_u32(bytes, 2);
        push_u32(bytes, 0);
        push_u32(bytes, 0);
        push_u32(bytes, flags);
        push_u32(bytes, 0);
        push_u32(bytes, 0);
        push_u32(bytes, 0);
    }

    #[allow(clippy::too_many_arguments)]
    fn push_macho_section_with_relocations(
        bytes: &mut Vec<u8>,
        name: &[u8],
        segment: &[u8],
        address: u64,
        size: usize,
        offset: usize,
        relocation_offset: usize,
        relocation_count: usize,
        flags: u32,
    ) {
        push_fixed_name(bytes, name);
        push_fixed_name(bytes, segment);
        push_u64(bytes, address);
        push_u64(bytes, size as u64);
        push_u32(bytes, offset as u32);
        push_u32(bytes, 2);
        push_u32(bytes, relocation_offset as u32);
        push_u32(bytes, relocation_count as u32);
        push_u32(bytes, flags);
        push_u32(bytes, 0);
        push_u32(bytes, 0);
        push_u32(bytes, 0);
    }

    fn push_macho_symbol(bytes: &mut Vec<u8>, name_offset: u32, section: u8, value: u64) {
        push_u32(bytes, name_offset);
        bytes.push(object::macho::N_SECT | object::macho::N_EXT);
        bytes.push(section);
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        push_u64(bytes, value);
    }

    fn push_macho_undefined_symbol(bytes: &mut Vec<u8>, name_offset: u32) {
        push_u32(bytes, name_offset);
        bytes.push(object::macho::N_UNDF | object::macho::N_EXT);
        bytes.push(0);
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        push_u64(bytes, 0);
    }

    fn push_macho_local_symbol(bytes: &mut Vec<u8>, name_offset: u32, section: u8, value: u64) {
        push_u32(bytes, name_offset);
        bytes.push(object::macho::N_SECT);
        bytes.push(section);
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        push_u64(bytes, value);
    }

    fn push_fixed_name(bytes: &mut Vec<u8>, name: &[u8]) {
        assert!(name.len() <= 16);
        bytes.extend_from_slice(name);
        bytes.resize(bytes.len() + 16 - name.len(), 0);
    }

    fn push_u32(bytes: &mut Vec<u8>, value: u32) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    fn push_u64(bytes: &mut Vec<u8>, value: u64) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    #[test]
    fn unchanged_normalized_archive_patch_state_accepts_only_unlinked_churn() {
        let archive = |invocation: &[u8], metadata: &[u8], object: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(b"lib.rmeta".to_vec(), metadata.len() as u64),
                    metadata,
                )
                .unwrap();
            builder
                .append(
                    &ar::Header::new(
                        [b"crate-hash.cgu.".as_slice(), invocation, b".rcgu.o"].concat(),
                        object.len() as u64,
                    ),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        };
        let input_path = hex::encode("libarchive.rlib");
        let section = PatchSection {
            input: hex::encode("libarchive.rlib\0crate-hash.cgu.old.rcgu.o\00:1"),
            section_index: 1,
            section_name: Some(".data".to_owned()),
            input_size: 4,
            output_offset: 64,
            output_size: 8,
            data_hash: Some(hash_bytes(&[1, 2, 3, 4])),
            cstring_nul_boundaries_hash: None,
        };
        let previous = archive(b"old", b"previous metadata", &growable_data_elf());
        let current = archive(b"new", b"new metadata", &growable_data_elf());
        let previous_patch = PreviousPatchState {
            fingerprint: patch_fingerprint(&previous, input_path.as_str(), [section.clone()])
                .unwrap()
                .unwrap(),
            archive_member_patch_fingerprints: None,
            sections: vec![section.clone()],
        };
        let input = FileState {
            path: input_path,
            content: FileContentState::from_bytes(&previous),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };

        let state = classify_normalized_rust_archive_patch_state(&input, &current, &previous_patch)
            .unwrap();
        assert!(matches!(
            &state,
            NormalizedRustArchivePatchState::Unchanged(_)
        ));
        if let NormalizedRustArchivePatchState::Unchanged(patch) = state {
            assert_eq!(patch.fingerprint, previous_patch.fingerprint);
            assert_eq!(patch.sections.len(), 1);
        }

        let mismatched_previous_patch = PreviousPatchState {
            fingerprint: "mismatched fingerprint".to_owned(),
            archive_member_patch_fingerprints: None,
            sections: vec![section.clone()],
        };
        let mismatched_state = classify_normalized_rust_archive_patch_state(
            &input,
            &current,
            &mismatched_previous_patch,
        )
        .unwrap();
        assert!(matches!(
            &mismatched_state,
            NormalizedRustArchivePatchState::Unknown
        ));

        let mut changed_object = growable_data_elf();
        changed_object[0x40] = 9;
        let changed = archive(b"current", b"new metadata", &changed_object);
        let changed_state =
            classify_normalized_rust_archive_patch_state(&input, &changed, &previous_patch)
                .unwrap();
        assert!(matches!(
            &changed_state,
            NormalizedRustArchivePatchState::MatchedButNotUnchanged(_)
        ));
        if let NormalizedRustArchivePatchState::MatchedButNotUnchanged(matched) = changed_state {
            assert_eq!(matched.sections.len(), 1);
            assert_eq!(matched.changed_sections.len(), 1);
        }
    }

    #[test]
    fn normalized_archive_refresh_does_not_reuse_retired_or_malformed_member_ranges() {
        let archive = |identifier: &[u8], object: &[u8]| {
            let mut builder = ar::Builder::new(Vec::new());
            builder
                .append(
                    &ar::Header::new(b"lib.rmeta".to_vec(), 8),
                    b"metadata".as_slice(),
                )
                .unwrap();
            builder
                .append(
                    &ar::Header::new(identifier.to_vec(), object.len() as u64),
                    object,
                )
                .unwrap();
            builder.into_inner().unwrap()
        };
        let input_path = hex::encode("libarchive.rlib");
        let object = growable_data_elf();
        let a1_identifier = b"crate.cgu.0.a1.rcgu.o";
        let a2_identifier = b"crate.cgu.0.this-is-a-much-longer-a2-invocation.rcgu.o";
        let a1 = archive(a1_identifier, &object);
        let a2 = archive(a2_identifier, &object);
        let ArchiveMemberMatch::Unique(a1_member) =
            patch_archive_member_bytes(&a1, a1_identifier).unwrap()
        else {
            panic!("expected A1 Rust archive member");
        };
        let section = PatchSection {
            input: resolved_patch_input_ref(&input_path, &input_path, a1_member).unwrap(),
            section_index: 1,
            section_name: Some(".data".to_owned()),
            input_size: 4,
            output_offset: 64,
            output_size: 8,
            data_hash: Some(hash_bytes(&object[0x40..0x44])),
            cstring_nul_boundaries_hash: None,
        };
        let previous_patch = PreviousPatchState {
            fingerprint: patch_fingerprint(&a1, input_path.as_str(), [section.clone()])
                .unwrap()
                .unwrap(),
            archive_member_patch_fingerprints: None,
            sections: vec![section],
        };
        let input = FileState {
            path: input_path.clone(),
            content: FileContentState::from_bytes(&a1),
            snapshot_identity: None,
            rustc_link_content_digest: None,
            rustc_raw_object_manifest: None,
            patch: None,
        };

        let NormalizedRustArchivePatchState::Unchanged(a2_patch) =
            classify_normalized_rust_archive_patch_state(&input, &a2, &previous_patch).unwrap()
        else {
            panic!("expected A2 normalized archive match");
        };
        let ArchiveMemberMatch::Unique(a2_member) =
            patch_archive_member_bytes(&a2, a2_identifier).unwrap()
        else {
            panic!("expected A2 Rust archive member");
        };
        let a2_ref = parse_patch_input_ref(&input_path, &a2_patch.sections[0].input)
            .unwrap()
            .unwrap();
        assert_eq!(a2_ref.identifier, a2_identifier);
        assert_eq!(
            a2_ref.range,
            a2_member.file_offset..a2_member.file_offset + a2_member.bytes.len()
        );

        let a2_previous_patch = PreviousPatchState {
            fingerprint: a2_patch.fingerprint.clone(),
            archive_member_patch_fingerprints: a2_patch.archive_member_patch_fingerprints.clone(),
            sections: a2_patch
                .sections
                .iter()
                .map(|section| PatchSection {
                    input: section.input.clone(),
                    section_index: section.section_index,
                    section_name: section.section_name.clone(),
                    input_size: section.input_size,
                    output_offset: section.output_offset,
                    output_size: section.output_size,
                    data_hash: section.data_hash.clone(),
                    cstring_nul_boundaries_hash: section.cstring_nul_boundaries_hash.clone(),
                })
                .collect(),
        };
        let retired = archive(b"crate.cgu.1.b.rcgu.o", &vec![b'x'; object.len()]);
        assert!(matches!(
            classify_normalized_rust_archive_patch_state(&input, &retired, &a2_previous_patch)
                .unwrap(),
            NormalizedRustArchivePatchState::Unknown
        ));

        let malformed = archive(b"crate.cgu.0.b.rcgu.o", b"not an object");
        assert!(matches!(
            classify_normalized_rust_archive_patch_state(&input, &malformed, &a2_previous_patch)
                .unwrap(),
            NormalizedRustArchivePatchState::Unknown
        ));
    }

    #[test]
    fn archive_member_identifiers_track_member_set() {
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(b"first.o".to_vec(), 5),
                b"first".as_slice(),
            )
            .unwrap();
        builder
            .append(
                &ar::Header::new(b"second.o".to_vec(), 6),
                b"second".as_slice(),
            )
            .unwrap();
        let archive = builder.into_inner().unwrap();

        assert_eq!(
            archive_member_identifiers(&archive).unwrap().unwrap(),
            vec![b"first.o".to_vec(), b"second.o".to_vec()]
        );
        assert!(
            archive_member_identifiers(b"not an archive")
                .unwrap()
                .is_none()
        );
        assert_eq!(
            archive_member_patch_identifier(b"crate-hash.cgu.session.rcgu.o"),
            b"crate-hash.cgu.rcgu.o".to_vec()
        );
        assert_eq!(
            archive_member_patch_identifier(b"crate-hash.cgu.0.session.rcgu.o"),
            b"crate-hash.cgu.0.rcgu.o".to_vec()
        );
        assert_eq!(
            archive_member_patch_identifier(b"foreign-member.o"),
            b"foreign-member.o".to_vec()
        );
    }

    #[test]
    fn added_archive_members_require_a_unique_normalized_ordered_superset() {
        let archive = |members: &[(&[u8], &[u8])]| {
            let mut builder = ar::Builder::new(Vec::new());
            for (identifier, data) in members {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), data.len() as u64),
                        *data,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        };
        let previous = archive(&[(b"crate.cgu.0.old.rcgu.o", b"root")]);
        let current = archive(&[
            (b"crate.cgu.0.new.rcgu.o", b"changed"),
            (b"crate.cgu.1.new.rcgu.o", b"added"),
        ]);
        assert_eq!(
            added_archive_member_identifiers(&previous, &current, true).unwrap(),
            Some(vec![b"crate.cgu.1.new.rcgu.o".to_vec()])
        );

        let duplicate = archive(&[
            (b"crate.cgu.0.new.rcgu.o", b"changed"),
            (b"crate.cgu.0.other.rcgu.o", b"duplicate"),
        ]);
        assert_eq!(
            added_archive_member_identifiers(&previous, &duplicate, true).unwrap(),
            None
        );

        let previous = archive(&[
            (b"crate.cgu.0.old.rcgu.o", b"zero"),
            (b"crate.cgu.2.old.rcgu.o", b"two"),
            (b"crate.cgu.4.old.rcgu.o", b"four"),
            (b"crate.cgu.6.old.rcgu.o", b"six"),
        ]);
        let four_added = archive(&[
            (b"crate.cgu.0.new.rcgu.o", b"zero"),
            (b"crate.cgu.1.new.rcgu.o", b"added"),
            (b"crate.cgu.2.new.rcgu.o", b"two"),
            (b"crate.cgu.3.new.rcgu.o", b"added"),
            (b"crate.cgu.4.new.rcgu.o", b"four"),
            (b"crate.cgu.5.new.rcgu.o", b"added"),
            (b"crate.cgu.6.new.rcgu.o", b"six"),
            (b"crate.cgu.7.new.rcgu.o", b"added"),
        ]);
        assert_eq!(
            added_archive_member_identifiers(&previous, &four_added, true).unwrap(),
            Some(vec![
                b"crate.cgu.1.new.rcgu.o".to_vec(),
                b"crate.cgu.3.new.rcgu.o".to_vec(),
                b"crate.cgu.5.new.rcgu.o".to_vec(),
                b"crate.cgu.7.new.rcgu.o".to_vec(),
            ])
        );
        assert_eq!(
            archive_member_identifier_delta(&previous, &four_added, true).unwrap(),
            Some(ArchiveMemberIdentifierDelta {
                added: vec![
                    b"crate.cgu.1.new.rcgu.o".to_vec(),
                    b"crate.cgu.3.new.rcgu.o".to_vec(),
                    b"crate.cgu.5.new.rcgu.o".to_vec(),
                    b"crate.cgu.7.new.rcgu.o".to_vec(),
                ],
                removed: Vec::new(),
            })
        );

        let removed = archive(&[
            (b"crate.cgu.0.new.rcgu.o", b"zero"),
            (b"crate.cgu.4.new.rcgu.o", b"four"),
            (b"crate.cgu.6.new.rcgu.o", b"six"),
            (b"crate.cgu.7.new.rcgu.o", b"added"),
            (b"crate.cgu.8.new.rcgu.o", b"added"),
        ]);
        assert_eq!(
            added_archive_member_identifiers(&previous, &removed, true).unwrap(),
            None
        );
        assert_eq!(
            archive_member_identifier_delta(&previous, &removed, true).unwrap(),
            Some(ArchiveMemberIdentifierDelta {
                added: vec![
                    b"crate.cgu.7.new.rcgu.o".to_vec(),
                    b"crate.cgu.8.new.rcgu.o".to_vec(),
                ],
                removed: vec![b"crate.cgu.2.old.rcgu.o".to_vec()],
            })
        );

        let reordered = archive(&[
            (b"crate.cgu.2.new.rcgu.o", b"two"),
            (b"crate.cgu.0.new.rcgu.o", b"zero"),
            (b"crate.cgu.4.new.rcgu.o", b"four"),
            (b"crate.cgu.6.new.rcgu.o", b"six"),
            (b"crate.cgu.7.new.rcgu.o", b"added"),
        ]);
        assert_eq!(
            added_archive_member_identifiers(&previous, &reordered, true).unwrap(),
            None
        );
        assert_eq!(
            archive_member_identifier_delta(&previous, &reordered, true).unwrap(),
            None
        );
    }

    #[test]
    fn owned_macho_archive_removal_requires_a_complete_active_cohort() {
        let transaction = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![
                MachOArchiveMemberIdentity {
                    normalized_identifier: b"crate.cgu.1.rcgu.o".to_vec(),
                    object_hash: "a".repeat(blake3::OUT_LEN * 2),
                },
                MachOArchiveMemberIdentity {
                    normalized_identifier: b"crate.cgu.2.rcgu.o".to_vec(),
                    object_hash: "b".repeat(blake3::OUT_LEN * 2),
                },
            ],
            active: true,
            sections: Vec::new(),
            relocations: Vec::new(),
            symbol_resolutions: Vec::new(),
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: Vec::new(),
            forward_patches: vec![StoredOutputPatch {
                output_offset: 64,
                data: vec![1; 4],
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: 64,
                data: vec![0; 4],
            }],
            unwind_transaction: None,
        };
        let dormant = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: b"crate.cgu.3.rcgu.o".to_vec(),
                object_hash: "c".repeat(blake3::OUT_LEN * 2),
            }],
            active: false,
            ..transaction.clone()
        };
        let second_dormant = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: b"crate.cgu.4.rcgu.o".to_vec(),
                object_hash: "d".repeat(blake3::OUT_LEN * 2),
            }],
            active: false,
            forward_patches: vec![StoredOutputPatch {
                output_offset: 128,
                data: vec![2; 4],
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: 128,
                data: vec![0; 4],
            }],
            ..transaction.clone()
        };
        let patch = FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: vec![transaction, dormant, second_dormant],
            sections: Vec::new(),
            raw_sections: None,
        };

        let ownership = owned_macho_archive_removal_indices(
            "libcrate.rlib",
            &patch,
            &[],
            &[
                b"crate.cgu.1.session.rcgu.o".to_vec(),
                b"crate.cgu.2.session.rcgu.o".to_vec(),
            ],
        )
        .unwrap();
        assert_eq!(ownership.tracked_indices, vec![0]);
        assert!(ownership.initially_owned_identifiers.is_empty());
        assert!(
            owned_macho_archive_removal_indices(
                "libcrate.rlib",
                &patch,
                &[],
                &[b"crate.cgu.1.session.rcgu.o".to_vec()],
            )
            .unwrap_err()
            .contains("split an activation cohort")
        );
        let ownership = owned_macho_archive_removal_indices(
            "libcrate.rlib",
            &patch,
            &[],
            &[b"crate.cgu.3.session.rcgu.o".to_vec()],
        )
        .unwrap();
        assert!(ownership.tracked_indices.is_empty());
        assert!(ownership.initially_owned_identifiers.is_empty());
        assert_eq!(
            dormant_macho_archive_reactivation_indices(
                &patch,
                &[b"crate.cgu.3.session.rcgu.o".to_vec()],
            )
            .unwrap(),
            vec![1],
        );
        assert_eq!(
            dormant_macho_archive_reactivation_indices(
                &patch,
                &[b"crate.cgu.5.session.rcgu.o".to_vec()],
            )
            .unwrap(),
            Vec::<usize>::new(),
        );
        assert_eq!(
            dormant_macho_archive_reactivation_indices(
                &patch,
                &[
                    b"crate.cgu.3.session.rcgu.o".to_vec(),
                    b"crate.cgu.4.session.rcgu.o".to_vec(),
                ],
            )
            .unwrap(),
            vec![1, 2],
        );
        assert!(
            dormant_macho_archive_reactivation_indices(
                &patch,
                &[b"crate.cgu.1.session.rcgu.o".to_vec()],
            )
            .unwrap_err()
            .contains("active ownership")
        );
        assert!(
            dormant_macho_archive_reactivation_indices(
                &patch,
                &[
                    b"crate.cgu.3.session.rcgu.o".to_vec(),
                    b"crate.cgu.5.session.rcgu.o".to_vec(),
                ],
            )
            .unwrap_err()
            .contains("mix dormant and new ownership")
        );
        let mut incomplete = patch;
        incomplete.macho_archive_members[1].rollback_patches[0].output_offset += 1;
        assert!(
            dormant_macho_archive_reactivation_indices(
                &incomplete,
                &[b"crate.cgu.3.session.rcgu.o".to_vec()],
            )
            .unwrap_err()
            .contains("transaction is incomplete")
        );
    }

    #[test]
    fn initially_owned_macho_archive_member_becomes_exact_dormant_ownership() {
        let input_file = hex::encode("libcrate.rlib");
        let previous_identifier = b"crate-hash.cgu.4.old.rcgu.o";
        let current_identifier = b"crate-hash.cgu.4.new.rcgu.o";
        let object = test_macho_object(&[1; 4], &[2; 4], 0);
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(previous_identifier.to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let previous = builder.into_inner().unwrap();
        let member = match patch_archive_member_bytes(&previous, previous_identifier).unwrap() {
            ArchiveMemberMatch::Unique(member) => member,
            _ => panic!("expected unique archive member"),
        };
        let input = resolved_patch_input_ref(&input_file, &input_file, member).unwrap();
        let file = object::File::parse(member.bytes).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let section = FilePatchSectionState {
            input: input.clone(),
            section_index: patch_section_record_index(&file, text.index()).unwrap(),
            section_name: Some("__TEXT,__text".to_owned()),
            input_size: text.size(),
            output_offset: 0,
            output_size: text.size(),
            data_hash: None,
            cstring_nul_boundaries_hash: None,
        };
        let patch = FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: Vec::new(),
            sections: vec![section],
            raw_sections: None,
        };
        let ownership = owned_macho_archive_removal_indices(
            &input_file,
            &patch,
            &[],
            &[previous_identifier.to_vec()],
        )
        .unwrap();
        assert_eq!(
            ownership.initially_owned_identifiers,
            vec![archive_member_patch_identifier(previous_identifier)]
        );
        let mut state = initially_owned_macho_archive_removal_state(
            &previous,
            &input_file,
            &patch,
            &[],
            &archive_member_patch_identifier(previous_identifier),
        )
        .unwrap()
        .unwrap();
        state.symbol_resolutions.push(MachOSymbolResolutionRecord {
            name: hex::encode("_text").into(),
            direct_value: Some(0),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input_file.clone().into(),
                input: input.into(),
                section_index: text.index().0 as u32,
                section_offset: 0,
            }),
        });

        let output = test_macho_object(&[1; 4], &[2; 4], 0);
        retain_initial_macho_archive_removal_transaction(&mut state, &output).unwrap();
        assert!(macho_archive_transaction_patches_match(&state));
        assert_eq!(state.forward_patches.len(), 1);
        assert_eq!(state.rollback_patches.len(), 1);
        assert_ne!(
            state.forward_patches[0].data,
            state.rollback_patches[0].data
        );
        assert_eq!(&state.rollback_patches[0].data[..4], &[0; 4]);

        state.active = false;
        let retained = FilePatchState {
            macho_archive_members: vec![state],
            ..patch
        };
        assert_eq!(
            dormant_macho_archive_reactivation_indices(&retained, &[current_identifier.to_vec()],)
                .unwrap(),
            vec![0]
        );
    }

    #[test]
    fn newly_retired_macho_archive_nlist_rollback_snapshots_round_trip() {
        let mut inputs = state("args", b"output", &[("libarchive.rlib", b"archive")]).input_files;
        let input_file = inputs[0].path.clone();
        let archive_input_ref = |member: &[u8]| {
            let mut input = hex::decode(&input_file).unwrap();
            input.push(0);
            input.extend_from_slice(member);
            input.push(0);
            input.extend_from_slice(b"1:2");
            hex::encode(input)
        };
        let archive_state =
            |active, member: &[u8], forward: &[u8], rollback: &[u8]| MachOArchiveActivationState {
                kind: MachOArchiveActivationKind::AddedMembers,
                members: vec![MachOArchiveMemberIdentity {
                    normalized_identifier: archive_member_patch_identifier(member),
                    object_hash: "a".repeat(blake3::OUT_LEN * 2),
                }],
                active,
                sections: vec![FilePatchSectionState {
                    input: archive_input_ref(member),
                    section_index: 1,
                    section_name: Some("__TEXT,__text".to_owned()),
                    input_size: 16,
                    output_offset: 64,
                    output_size: 16,
                    data_hash: Some("section-hash".to_owned()),
                    cstring_nul_boundaries_hash: None,
                }],
                relocations: Vec::new(),
                symbol_resolutions: Vec::new(),
                indirect_dependencies: Vec::new(),
                rollback_symbol_resolutions: Vec::new(),
                forward_patches: vec![StoredOutputPatch {
                    output_offset: 16,
                    data: forward.to_vec(),
                }],
                rollback_patches: vec![StoredOutputPatch {
                    output_offset: 16,
                    data: rollback.to_vec(),
                }],
                unwind_transaction: None,
            };
        let round_trip = |inputs: &mut [FileState]| {
            let patch = inputs[0].patch.as_mut().unwrap();
            let rendered = render_macho_archive_member_states(&patch.macho_archive_members);
            patch.macho_archive_members =
                parse_macho_archive_member_states(&input_file, &rendered).unwrap();
        };
        let nlist = |string_index: u32, value: u64| {
            let mut entry =
                vec![0; std::mem::size_of::<object::macho::Nlist64<object::Endianness>>()];
            entry[..4].copy_from_slice(&string_index.to_le_bytes());
            entry[4] = object::macho::N_SECT | object::macho::N_EXT;
            entry[5] = 1;
            entry[8..].copy_from_slice(&value.to_le_bytes());
            entry
        };
        let a = nlist(11, 0x1000);
        let b = nlist(22, 0x2000);
        let mut empty = a.clone();
        empty[..4].fill(0);
        let stale = archive_state(false, b"stale", &nlist(33, 0x3000), &nlist(44, 0x4000));
        let mut unrelated = archive_state(true, b"unrelated", &[9; 4], &[10; 4]);
        unrelated.forward_patches.clear();
        unrelated.rollback_patches.clear();
        inputs[0].patch = Some(FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: vec![
                archive_state(false, b"a", &a, &empty),
                archive_state(true, b"b", &b, &empty),
                stale.clone(),
                unrelated,
            ],
            sections: Vec::new(),
            raw_sections: None,
        });
        let retired_a = [RetiredMachOArchiveStateRef {
            input_index: 0,
            state_index: 0,
        }];
        let mut output = vec![0; 48];
        output[16..32].copy_from_slice(&b);

        refresh_dormant_macho_archive_rollback_patches(&mut inputs, &retired_a, &output).unwrap();
        round_trip(&mut inputs);
        let members = &mut inputs[0].patch.as_mut().unwrap().macho_archive_members;
        assert_eq!(members[0].rollback_patches[0].data, b);
        assert_eq!(members[2], stale, "an older dormant state was refreshed");

        members[0].active = true;
        members[1].active = false;
        output[16..32].copy_from_slice(&a);
        refresh_dormant_macho_archive_rollback_patches(
            &mut inputs,
            &[RetiredMachOArchiveStateRef {
                input_index: 0,
                state_index: 1,
            }],
            &output,
        )
        .unwrap();
        round_trip(&mut inputs);
        let members = &mut inputs[0].patch.as_mut().unwrap().macho_archive_members;
        assert_eq!(members[1].rollback_patches[0].data, a);

        members[0].active = false;
        members[1].active = true;
        output[16..32].copy_from_slice(&b);
        refresh_dormant_macho_archive_rollback_patches(&mut inputs, &retired_a, &output).unwrap();
        round_trip(&mut inputs);
        assert_eq!(
            inputs[0].patch.as_ref().unwrap().macho_archive_members[0].rollback_patches[0].data,
            b,
        );
    }

    #[test]
    fn symbol_only_macho_archive_rollback_requires_one_active_replacement() {
        let input_file = hex::encode("libarchive.rlib");
        let input_ref = |member: &[u8]| {
            let mut input = hex::decode(&input_file).unwrap();
            input.push(0);
            input.extend_from_slice(member);
            input.push(0);
            input.extend_from_slice(b"1:2");
            hex::encode(input)
        };
        let nlist = |string_index: u32, value: u64| {
            let mut entry =
                vec![0; std::mem::size_of::<object::macho::Nlist64<object::Endianness>>()];
            entry[..4].copy_from_slice(&string_index.to_le_bytes());
            entry[4] = object::macho::N_SECT | object::macho::N_EXT;
            entry[5] = 2;
            entry[8..].copy_from_slice(&value.to_le_bytes());
            entry
        };
        let old_member = b"crate.old.rcgu.o";
        let new_member = b"crate.new.rcgu.o";
        let old_forward = nlist(11, 0x1000);
        let mut old_canonical_rollback = old_forward.clone();
        old_canonical_rollback[..4].fill(0);
        let new_forward = nlist(22, 0x2000);
        let mut new_rollback = new_forward.clone();
        new_rollback[..4].fill(0);
        let dormant = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(old_member),
                object_hash: "a".repeat(blake3::OUT_LEN * 2),
            }],
            active: false,
            sections: Vec::new(),
            relocations: Vec::new(),
            symbol_resolutions: vec![MachOSymbolResolutionRecord {
                name: hex::encode("_old").into(),
                direct_value: Some(0x1000),
                got_address: None,
                stub_address: None,
                thunk_addresses: Vec::new(),
                target: Some(RelocationTargetRecord {
                    input_file: input_file.clone().into(),
                    input: input_ref(old_member).into(),
                    section_index: 1,
                    section_offset: 0,
                }),
            }],
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: Vec::new(),
            forward_patches: vec![StoredOutputPatch {
                output_offset: 16,
                data: old_forward.clone(),
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: 16,
                data: old_canonical_rollback,
            }],
            unwind_transaction: None,
        };
        let active = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(new_member),
                object_hash: "b".repeat(blake3::OUT_LEN * 2),
            }],
            active: true,
            sections: vec![FilePatchSectionState {
                input: input_ref(new_member),
                section_index: 1,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: 4,
                output_offset: 64,
                output_size: 4,
                data_hash: Some("section-hash".to_owned()),
                cstring_nul_boundaries_hash: None,
            }],
            relocations: Vec::new(),
            symbol_resolutions: Vec::new(),
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: Vec::new(),
            forward_patches: vec![StoredOutputPatch {
                output_offset: 16,
                data: new_forward.clone(),
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: 16,
                data: new_rollback,
            }],
            unwind_transaction: None,
        };
        let mut inputs = state("args", b"output", &[("libarchive.rlib", b"archive")]).input_files;
        inputs[0].patch = Some(FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: Vec::new(),
            sections: Vec::new(),
            raw_sections: None,
        });
        assert!(
            dormant_macho_archive_state_refs(
                0,
                &inputs[0].patch.as_ref().unwrap().macho_archive_members,
            )
            .is_empty(),
            "the full-link seed unexpectedly has archive ownership state",
        );
        inputs[0].patch.as_mut().unwrap().macho_archive_members = vec![dormant, active];
        let mut output = vec![0; 48];
        output[16..32].copy_from_slice(&new_forward);

        let dormant = dormant_macho_archive_state_refs(
            0,
            &inputs[0].patch.as_ref().unwrap().macho_archive_members,
        );
        assert_eq!(
            dormant,
            vec![RetiredMachOArchiveStateRef {
                input_index: 0,
                state_index: 0,
            }],
        );
        refresh_dormant_macho_archive_rollback_patches(&mut inputs, &dormant, &output).unwrap();
        let states = &inputs[0].patch.as_ref().unwrap().macho_archive_members;
        let rendered = render_macho_archive_member_states(states);
        assert_eq!(
            parse_macho_archive_member_states(&input_file, &rendered).unwrap(),
            *states,
        );

        let mut missing_active = states.clone();
        missing_active[1].active = false;
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&missing_active),
            )
            .is_err()
        );
        let mut duplicate_active = states.clone();
        let mut duplicate = duplicate_active[1].clone();
        duplicate.members[0].normalized_identifier = b"duplicate".to_vec();
        duplicate.sections[0].input = input_ref(b"duplicate");
        duplicate_active.push(duplicate);
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&duplicate_active),
            )
            .is_err()
        );
        let mut tampered = states.clone();
        tampered[1].forward_patches[0].data[0] ^= 1;
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&tampered),
            )
            .is_err()
        );

        let states = &mut inputs[0].patch.as_mut().unwrap().macho_archive_members;
        states[0].active = true;
        states[1].active = false;
        output[16..32].copy_from_slice(&old_forward);
        let dormant = dormant_macho_archive_state_refs(
            0,
            &inputs[0].patch.as_ref().unwrap().macho_archive_members,
        );
        refresh_dormant_macho_archive_rollback_patches(&mut inputs, &dormant, &output).unwrap();
        let states = &inputs[0].patch.as_ref().unwrap().macho_archive_members;
        let rendered = render_macho_archive_member_states(states);
        assert_eq!(
            parse_macho_archive_member_states(&input_file, &rendered).unwrap(),
            *states,
        );

        let states = &mut inputs[0].patch.as_mut().unwrap().macho_archive_members;
        states[0].active = false;
        states[1].active = true;
        output[16..32].copy_from_slice(&new_forward);
        let dormant = dormant_macho_archive_state_refs(
            0,
            &inputs[0].patch.as_ref().unwrap().macho_archive_members,
        );
        refresh_dormant_macho_archive_rollback_patches(&mut inputs, &dormant, &output).unwrap();
        let states = &inputs[0].patch.as_ref().unwrap().macho_archive_members;
        let rendered = render_macho_archive_member_states(states);
        assert_eq!(
            parse_macho_archive_member_states(&input_file, &rendered).unwrap(),
            *states,
        );
    }

    #[test]
    fn newly_retired_macho_archive_rollback_refresh_is_atomic_and_exact() {
        let archive_state = |active, member: &[u8], offset, forward: &[u8], rollback: &[u8]| {
            MachOArchiveActivationState {
                kind: MachOArchiveActivationKind::AddedMembers,
                members: vec![MachOArchiveMemberIdentity {
                    normalized_identifier: member.to_vec(),
                    object_hash: "a".repeat(blake3::OUT_LEN * 2),
                }],
                active,
                sections: Vec::new(),
                relocations: Vec::new(),
                symbol_resolutions: Vec::new(),
                indirect_dependencies: Vec::new(),
                rollback_symbol_resolutions: Vec::new(),
                forward_patches: vec![StoredOutputPatch {
                    output_offset: offset,
                    data: forward.to_vec(),
                }],
                rollback_patches: vec![StoredOutputPatch {
                    output_offset: offset,
                    data: rollback.to_vec(),
                }],
                unwind_transaction: None,
            }
        };
        let retired_ref = [RetiredMachOArchiveStateRef {
            input_index: 0,
            state_index: 0,
        }];
        let input_files = |replacement_offset| {
            let mut inputs =
                state("args", b"output", &[("libarchive.rlib", b"archive")]).input_files;
            inputs[0].patch = Some(FilePatchState {
                fingerprint: String::new(),
                archive_member_set_proof: None,
                archive_member_patch_fingerprints: None,
                macho_archive_members: vec![
                    archive_state(false, b"retired", 16, &[1, 2, 3, 4], &[0; 4]),
                    archive_state(
                        true,
                        b"replacement",
                        replacement_offset,
                        &[5, 6, 7, 8],
                        &[0; 4],
                    ),
                ],
                sections: Vec::new(),
                raw_sections: None,
            });
            inputs
        };

        let mut tampered = input_files(16);
        let original = tampered.clone();
        let mut output = vec![0; 32];
        output[16..20].copy_from_slice(&[5, 6, 7, 9]);
        assert!(
            refresh_dormant_macho_archive_rollback_patches(&mut tampered, &retired_ref, &output,)
                .unwrap_err()
                .contains("differs from finalized output")
        );
        assert_eq!(
            tampered, original,
            "a failed refresh changed persisted state"
        );

        let mut proof_bearing = input_files(16);
        let common_members = vec![MachOArchiveMemberIdentity {
            normalized_identifier: b"common.rcgu.o".to_vec(),
            object_hash: "b".repeat(blake3::OUT_LEN * 2),
        }];
        proof_bearing[0]
            .patch
            .as_mut()
            .unwrap()
            .macho_archive_members[0]
            .unwind_transaction = Some(MachOArchiveUnwindTransactionState {
            forward: MachOArchiveUnwindVersionState {
                common_members: common_members.clone(),
                eh_frame_reserve: MachOEhFrameReserveState { start: 0, end: 0 },
            },
            rollback: MachOArchiveUnwindVersionState {
                common_members,
                eh_frame_reserve: MachOEhFrameReserveState { start: 0, end: 0 },
            },
        });
        let original = proof_bearing.clone();
        output[16..20].copy_from_slice(&[5, 6, 7, 8]);
        assert!(
            refresh_dormant_macho_archive_rollback_patches(
                &mut proof_bearing,
                &retired_ref,
                &output,
            )
            .unwrap_err()
            .contains("proof-bearing")
        );
        assert_eq!(
            proof_bearing, original,
            "an interleaved active transaction changed proof-bearing rollback bytes",
        );

        let mut partial = input_files(18);
        let original = partial.clone();
        assert!(
            refresh_dormant_macho_archive_rollback_patches(&mut partial, &retired_ref, &output,)
                .unwrap_err()
                .contains("partially shadows")
        );
        assert_eq!(
            partial, original,
            "a partial shadow changed persisted state"
        );

        let mut stale = input_files(24);
        let original = stale.clone();
        assert!(
            refresh_dormant_macho_archive_rollback_patches(&mut stale, &retired_ref, &output)
                .unwrap_err()
                .contains("without an exact replacement")
        );
        assert_eq!(
            stale, original,
            "an unexplained change updated the snapshot"
        );
    }

    #[test]
    fn initially_owned_macho_archive_symbol_only_member_is_retained() {
        let input_file = hex::encode("libcrate.rlib");
        let previous_identifier = b"crate-hash.cgu.4.old.rcgu.o";
        let current_identifier = b"crate-hash.cgu.4.new.rcgu.o";
        let object = test_macho_object(&[1; 4], &[2; 4], 0);
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(previous_identifier.to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let previous = builder.into_inner().unwrap();
        let member = match patch_archive_member_bytes(&previous, previous_identifier).unwrap() {
            ArchiveMemberMatch::Unique(member) => member,
            _ => panic!("expected unique archive member"),
        };
        let input = resolved_patch_input_ref(&input_file, &input_file, member).unwrap();
        let file = object::File::parse(member.bytes).unwrap();
        let text = file.section_by_name("__text").unwrap();
        let resolution = MachOSymbolResolutionRecord {
            name: hex::encode("_text").into(),
            direct_value: Some(0),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input_file.clone().into(),
                input: input.clone().into(),
                section_index: text.index().0 as u32,
                section_offset: 0,
            }),
        };
        let patch = FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: Vec::new(),
            sections: Vec::new(),
            raw_sections: None,
        };

        let ownership = owned_macho_archive_removal_indices(
            &input_file,
            &patch,
            std::slice::from_ref(&resolution),
            &[previous_identifier.to_vec()],
        )
        .unwrap();
        assert_eq!(
            ownership.initially_owned_identifiers,
            vec![archive_member_patch_identifier(previous_identifier)]
        );
        assert!(
            owned_macho_archive_removal_indices(
                &input_file,
                &patch,
                &[],
                &[previous_identifier.to_vec()],
            )
            .unwrap()
            .initially_owned_identifiers
            .is_empty()
        );

        let mut state = initially_owned_macho_archive_removal_state(
            &previous,
            &input_file,
            &patch,
            std::slice::from_ref(&resolution),
            &archive_member_patch_identifier(previous_identifier),
        )
        .unwrap()
        .unwrap();
        assert!(state.sections.is_empty());
        state.symbol_resolutions = macho_archive_member_symbol_resolutions(
            std::slice::from_ref(&resolution),
            &input_file,
            &HashSet::from([input]),
        );
        assert_eq!(state.symbol_resolutions, vec![resolution]);
        retain_initial_macho_archive_removal_transaction(&mut state, &object).unwrap();
        assert!(macho_archive_transaction_patches_match(&state));
        assert_eq!(state.forward_patches.len(), 1);
        assert_eq!(state.rollback_patches.len(), 1);
        assert_eq!(&state.rollback_patches[0].data[..4], &[0; 4]);

        state.active = false;
        let rendered = render_macho_archive_member_states(std::slice::from_ref(&state));
        let parsed = parse_macho_archive_member_states(&input_file, &rendered).unwrap();
        assert_eq!(parsed, vec![state.clone()]);

        let mut missing_ownership = state.clone();
        missing_ownership.symbol_resolutions.clear();
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&[missing_ownership]),
            )
            .unwrap_err()
            .to_string()
            .contains("symbol-only")
        );

        let mut indirect_ownership = state.clone();
        indirect_ownership.symbol_resolutions[0].got_address = Some(1);
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&[indirect_ownership]),
            )
            .unwrap_err()
            .to_string()
            .contains("symbol-only")
        );

        let mut overlapping_ownership = state.clone();
        let mut second_resolution = overlapping_ownership.symbol_resolutions[0].clone();
        second_resolution.name = hex::encode("_other_text").into();
        overlapping_ownership
            .symbol_resolutions
            .push(second_resolution);
        overlapping_ownership
            .forward_patches
            .push(overlapping_ownership.forward_patches[0].clone());
        overlapping_ownership
            .rollback_patches
            .push(overlapping_ownership.rollback_patches[0].clone());
        assert!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&[overlapping_ownership]),
            )
            .unwrap_err()
            .to_string()
            .contains("symbol-only")
        );

        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(current_identifier.to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let current = builder.into_inner().unwrap();
        let resolver = PatchInputResolver::new(&current, true).unwrap();
        let mut patch = patch;
        patch.macho_archive_members = parsed;
        let mut dormant_output = object.clone();
        for output_patch in &state.rollback_patches {
            let start = output_patch.output_offset as usize;
            dormant_output[start..start + output_patch.data.len()]
                .copy_from_slice(&output_patch.data);
        }
        let live_conflict = MachOSymbolResolutionRecord {
            target: Some(RelocationTargetRecord {
                input_file: hex::encode("other.rlib").into(),
                input: hex::encode("other.rlib").into(),
                section_index: 1,
                section_offset: 0,
            }),
            ..state.symbol_resolutions[0].clone()
        };
        assert!(
            reactivated_macho_archive_text_activation(
                &current,
                &input_file,
                &[current_identifier.to_vec()],
                &resolver,
                &patch,
                &dormant_output,
                std::slice::from_ref(&live_conflict),
                &[],
                &[],
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("conflicts with a live resolution")
        );
        assert!(
            reactivated_macho_archive_text_activation(
                &current,
                &input_file,
                &[current_identifier.to_vec()],
                &resolver,
                &patch,
                &dormant_output,
                std::slice::from_ref(&live_conflict),
                std::slice::from_ref(&live_conflict.name),
                &[],
                true,
            )
            .unwrap()
            .unwrap()
            .is_some()
        );
        let mut tampered_dormant_output = dormant_output.clone();
        let dormant_offset = state.rollback_patches[0].output_offset as usize;
        tampered_dormant_output[dormant_offset] ^= 1;
        assert!(
            reactivated_macho_archive_text_activation(
                &current,
                &input_file,
                &[current_identifier.to_vec()],
                &resolver,
                &patch,
                &tampered_dormant_output,
                &[],
                &[],
                &[],
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("output changed while dormant")
        );
        let first_reactivation = reactivated_macho_archive_text_activation(
            &current,
            &input_file,
            &[current_identifier.to_vec()],
            &resolver,
            &patch,
            &dormant_output,
            &[],
            &[],
            &[],
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert!(first_reactivation.reactivated);
        assert_eq!(first_reactivation.symbol_resolutions.len(), 1);
        assert_eq!(first_reactivation.member_states.len(), 1);
        assert!(first_reactivation.member_states[0].active);
        assert_eq!(
            first_reactivation.member_states[0].symbol_resolutions,
            first_reactivation.symbol_resolutions
        );

        let active_rendered = render_macho_archive_member_states(&first_reactivation.member_states);
        let active = parse_macho_archive_member_states(&input_file, &active_rendered).unwrap();
        assert!(tracked_symbol_only_macho_archive_transaction_is_current(
            &active[0],
            &first_reactivation.symbol_resolutions,
            &object,
        ));
        assert!(!tracked_symbol_only_macho_archive_transaction_is_current(
            &active[0],
            &[],
            &object,
        ));
        let mut recycled_output = object.clone();
        let recycled_offset = active[0].forward_patches[0].output_offset as usize;
        recycled_output[recycled_offset] ^= 1;
        assert!(!tracked_symbol_only_macho_archive_transaction_is_current(
            &active[0],
            &first_reactivation.symbol_resolutions,
            &recycled_output,
        ));
        patch.macho_archive_members = active.clone();
        let ownership = owned_macho_archive_removal_indices(
            &input_file,
            &patch,
            &first_reactivation.symbol_resolutions,
            &[current_identifier.to_vec()],
        )
        .unwrap();
        assert_eq!(ownership.tracked_indices, vec![0]);
        assert!(ownership.initially_owned_identifiers.is_empty());

        let mut dormant_again = active[0].clone();
        let member_inputs = first_reactivation
            .symbol_resolutions
            .iter()
            .filter_map(|resolution| {
                resolution
                    .target
                    .as_ref()
                    .map(|target| target.input.to_string())
            })
            .collect::<HashSet<_>>();
        dormant_again.symbol_resolutions = macho_archive_member_symbol_resolutions(
            &first_reactivation.symbol_resolutions,
            &input_file,
            &member_inputs,
        );
        dormant_again.active = false;
        let dormant_again = parse_macho_archive_member_states(
            &input_file,
            &render_macho_archive_member_states(&[dormant_again]),
        )
        .unwrap();
        patch.macho_archive_members = dormant_again;
        let second_reactivation = reactivated_macho_archive_text_activation(
            &current,
            &input_file,
            &[current_identifier.to_vec()],
            &resolver,
            &patch,
            &dormant_output,
            &[],
            &[],
            &[],
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(
            parse_macho_archive_member_states(
                &input_file,
                &render_macho_archive_member_states(&second_reactivation.member_states),
            )
            .unwrap(),
            second_reactivation.member_states
        );
    }

    #[test]
    fn dormant_macho_archive_reactivation_requires_exact_members_and_refreshes_records() {
        fn archive(members: &[(&[u8], &[u8])]) -> Vec<u8> {
            let mut builder = ar::Builder::new(Vec::new());
            for &(identifier, data) in members {
                builder
                    .append(
                        &ar::Header::new(identifier.to_vec(), data.len() as u64),
                        data,
                    )
                    .unwrap();
            }
            builder.into_inner().unwrap()
        }

        fn archive_input_ref(input_file: &str, identifier: &[u8]) -> String {
            let mut bytes = hex::decode(input_file).unwrap();
            bytes.push(0);
            bytes.extend_from_slice(identifier);
            bytes.push(0);
            bytes.extend_from_slice(b"1:2");
            hex::encode(bytes)
        }

        let input_file = hex::encode("libcrate.rlib");
        let previous_identifier = b"c.1.old.rcgu.o";
        let current_identifier = b"c.1.new.rcgu.o";
        let member_bytes = b"identical object bytes";
        let current = archive(&[(current_identifier, member_bytes)]);
        let resolver = PatchInputResolver::new(&current, true).unwrap();
        let previous_input = archive_input_ref(&input_file, previous_identifier);
        let output = test_macho_unwind_output(0x1000);
        let first_output_offset = output.text_offset;
        let first_target_value = crate::macho::MACHO_START_MEM_ADDRESS
            .checked_add(first_output_offset + 4)
            .unwrap();
        let rollback = MachOSymbolResolutionRecord {
            name: hex::encode("_rollback").into(),
            direct_value: Some(0x1000),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: None,
        };
        let dormant_resolution = MachOSymbolResolutionRecord {
            name: hex::encode("_reactivated").into(),
            direct_value: Some(first_target_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(RelocationTargetRecord {
                input_file: input_file.clone().into(),
                input: previous_input.clone().into(),
                section_index: 2,
                section_offset: 4,
            }),
        };
        let dormant_relocation = RelocationRecord {
            target_symbol_id: 7,
            written_value: Some(first_target_value),
            target_value: first_target_value,
            applied_target_value: Some(first_target_value),
            target_name: Some(hex::encode("_reactivated").into()),
            target: dormant_resolution.target.clone(),
            input_file: input_file.clone().into(),
            input: previous_input.clone().into(),
            section_index: 1,
            relocation_offset: 8,
            output_offset: first_output_offset + 8,
            size: 4,
            kind: u32::from(object::macho::ARM64_RELOC_BRANCH26),
            addend: 0,
        };
        let dormant = MachOArchiveActivationState {
            kind: MachOArchiveActivationKind::AddedMembers,
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(current_identifier),
                object_hash: hash_bytes(member_bytes),
            }],
            active: false,
            sections: vec![FilePatchSectionState {
                input: previous_input,
                section_index: 1,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: 16,
                output_offset: first_output_offset,
                output_size: 32,
                data_hash: Some("section-hash".to_owned()),
                cstring_nul_boundaries_hash: None,
            }],
            relocations: vec![dormant_relocation],
            symbol_resolutions: vec![dormant_resolution],
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: vec![rollback.clone()],
            forward_patches: vec![StoredOutputPatch {
                output_offset: first_output_offset,
                data: vec![1, 2, 3, 4],
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: first_output_offset,
                data: vec![0; 4],
            }],
            unwind_transaction: None,
        };
        let patch = FilePatchState {
            fingerprint: String::new(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: vec![dormant.clone()],
            sections: Vec::new(),
            raw_sections: None,
        };
        let dormant_output = output.bytes;

        let mut refreshed_dormant = dormant.clone();
        refreshed_dormant.active = true;
        let mut live_output = dormant_output.clone();
        let first_output_offset = first_output_offset as usize;
        live_output[first_output_offset..first_output_offset + 4].copy_from_slice(&[9, 10, 11, 12]);
        refresh_active_macho_archive_forward_patches(&mut refreshed_dormant, &live_output).unwrap();
        assert_eq!(refreshed_dormant.forward_patches[0].data, [9, 10, 11, 12]);
        assert_eq!(refreshed_dormant.rollback_patches[0].data, [0; 4]);
        refreshed_dormant.active = false;
        let refreshed_patch = FilePatchState {
            macho_archive_members: vec![refreshed_dormant],
            ..patch.clone()
        };
        let refreshed_activation = reactivated_macho_archive_text_activation(
            &current,
            &input_file,
            &[current_identifier.to_vec()],
            &resolver,
            &refreshed_patch,
            &dormant_output,
            std::slice::from_ref(&rollback),
            &[],
            &[],
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(
            refreshed_activation.reactivated_output_patches[0].data,
            [9, 10, 11, 12],
        );

        let mut invalid = dormant.clone();
        invalid.active = true;
        invalid.forward_patches.push(StoredOutputPatch {
            output_offset: dormant_output.len() as u64 - 2,
            data: vec![5, 6, 7, 8],
        });
        invalid.rollback_patches.push(StoredOutputPatch {
            output_offset: dormant_output.len() as u64 - 2,
            data: vec![0; 4],
        });
        let unchanged = invalid.clone();
        assert!(
            refresh_active_macho_archive_forward_patches(&mut invalid, &live_output)
                .unwrap_err()
                .contains("outside output")
        );
        assert_eq!(invalid, unchanged, "a failed refresh must be transactional");

        let activation = reactivated_macho_archive_text_activation(
            &current,
            &input_file,
            &[current_identifier.to_vec()],
            &resolver,
            &patch,
            &dormant_output,
            std::slice::from_ref(&rollback),
            &[],
            &[],
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();

        assert!(activation.reactivated);
        assert!(activation.member_states[0].active);
        assert!(activation.member_states[0].relocations.is_empty());
        assert!(activation.member_states[0].symbol_resolutions.is_empty());
        assert_eq!(
            activation.recycled_symbol_resolution_names,
            vec![rollback.name.clone()]
        );
        assert_eq!(activation.reactivated_output_patches[0].data, [1, 2, 3, 4]);
        let refreshed = parse_patch_input_ref(&input_file, &activation.sections[0].input)
            .unwrap()
            .unwrap();
        assert_eq!(refreshed.identifier, current_identifier);
        let refreshed = parse_patch_input_ref(
            &input_file,
            activation.reactivated_relocations[0].input.as_str(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(refreshed.identifier, current_identifier);
        let refreshed = parse_patch_input_ref(
            &input_file,
            activation.symbol_resolutions[0]
                .target
                .as_ref()
                .unwrap()
                .input
                .as_str(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(refreshed.identifier, current_identifier);

        let mut reactivated = activation.reactivated_relocations.clone();
        reactivated[0].target_symbol_id = 0;
        let stable = RelocationRecord {
            target_symbol_id: u32::MAX,
            ..reactivated[0].clone()
        };
        assert!(reactivated[0] < stable);
        let mut persisted = vec![stable.clone()];
        assert!(append_reactivated_macho_relocations_preserving_indices(
            &mut persisted,
            &mut reactivated,
        ));
        assert_eq!(persisted[0], stable);
        assert!(reactivated.is_empty());

        let second_previous_identifier = b"c.2.old.rcgu.o";
        let second_current_identifier = b"c.2.new.rcgu.o";
        let second_member_bytes = b"second identical object bytes";
        let second_previous_input = archive_input_ref(&input_file, second_previous_identifier);
        let second_output_offset = first_output_offset as u64 + 64;
        let second_target_value = crate::macho::MACHO_START_MEM_ADDRESS
            .checked_add(second_output_offset + 8)
            .unwrap();
        let second_rollback = MachOSymbolResolutionRecord {
            name: hex::encode("_second_rollback").into(),
            direct_value: Some(0x3000),
            ..rollback.clone()
        };
        let second_resolution = MachOSymbolResolutionRecord {
            name: hex::encode("_second_reactivated").into(),
            direct_value: Some(second_target_value),
            target: Some(RelocationTargetRecord {
                input_file: input_file.clone().into(),
                input: second_previous_input.clone().into(),
                section_index: 3,
                section_offset: 8,
            }),
            ..dormant.symbol_resolutions[0].clone()
        };
        let second_relocation = RelocationRecord {
            target_symbol_id: 8,
            written_value: Some(second_target_value),
            target_value: second_target_value,
            applied_target_value: Some(second_target_value),
            target_name: Some(second_resolution.name.clone()),
            target: second_resolution.target.clone(),
            input: second_previous_input.clone().into(),
            section_index: 2,
            output_offset: second_output_offset + 8,
            ..dormant.relocations[0].clone()
        };
        let second_dormant = MachOArchiveActivationState {
            members: vec![MachOArchiveMemberIdentity {
                normalized_identifier: archive_member_patch_identifier(second_current_identifier),
                object_hash: hash_bytes(second_member_bytes),
            }],
            sections: vec![FilePatchSectionState {
                input: second_previous_input,
                section_index: 2,
                output_offset: second_output_offset,
                ..dormant.sections[0].clone()
            }],
            relocations: vec![second_relocation],
            symbol_resolutions: vec![second_resolution],
            indirect_dependencies: Vec::new(),
            rollback_symbol_resolutions: vec![second_rollback.clone()],
            forward_patches: vec![StoredOutputPatch {
                output_offset: second_output_offset,
                data: vec![5, 6, 7, 8],
            }],
            rollback_patches: vec![StoredOutputPatch {
                output_offset: second_output_offset,
                data: vec![0; 4],
            }],
            ..dormant.clone()
        };
        let multi_current = archive(&[
            (current_identifier, member_bytes),
            (second_current_identifier, second_member_bytes),
        ]);
        let multi_resolver = PatchInputResolver::new(&multi_current, true).unwrap();
        let multi_patch = FilePatchState {
            macho_archive_members: vec![dormant, second_dormant],
            ..patch.clone()
        };
        let mut multi_activation = reactivated_macho_archive_text_activation(
            &multi_current,
            &input_file,
            &[
                current_identifier.to_vec(),
                second_current_identifier.to_vec(),
            ],
            &multi_resolver,
            &multi_patch,
            &dormant_output,
            &[rollback.clone(), second_rollback.clone()],
            &[],
            &[],
            true,
        )
        .unwrap()
        .unwrap()
        .unwrap();
        assert_eq!(multi_activation.member_states.len(), 2);
        assert!(
            multi_activation
                .member_states
                .iter()
                .all(|state| state.active)
        );
        assert_eq!(multi_activation.sections.len(), 2);
        assert_eq!(multi_activation.records.len(), 2);
        assert_eq!(multi_activation.reactivated_relocations.len(), 2);
        assert_eq!(multi_activation.symbol_resolutions.len(), 2);
        assert_eq!(multi_activation.reactivated_output_patches.len(), 2);
        assert_eq!(
            multi_activation.member_states[1].rollback_symbol_resolutions,
            vec![second_rollback.clone()]
        );
        for (section, expected_identifier) in multi_activation.sections.iter().zip([
            current_identifier.as_slice(),
            second_current_identifier.as_slice(),
        ]) {
            let refreshed = parse_patch_input_ref(&input_file, &section.input)
                .unwrap()
                .unwrap();
            assert_eq!(refreshed.identifier, expected_identifier);
        }
        for state in &mut multi_activation.member_states {
            state.rollback_symbol_resolutions.clear();
        }
        let first_predecessor = MachOSymbolResolutionRecord {
            name: multi_activation.symbol_resolutions[0].name.clone(),
            direct_value: Some(0x5000),
            target: None,
            ..rollback.clone()
        };
        let second_predecessor = MachOSymbolResolutionRecord {
            name: multi_activation.symbol_resolutions[1].name.clone(),
            direct_value: Some(0x6000),
            target: None,
            ..rollback.clone()
        };
        let unrelated_predecessor = MachOSymbolResolutionRecord {
            name: hex::encode("_unrelated_retirement").into(),
            direct_value: Some(0x7000),
            ..rollback.clone()
        };
        reconcile_reactivated_macho_archive_rollback_symbol_resolutions(
            &mut multi_activation,
            &[
                first_predecessor.clone(),
                second_predecessor.clone(),
                unrelated_predecessor.clone(),
            ],
        )
        .unwrap();
        assert_eq!(
            multi_activation.member_states[0].rollback_symbol_resolutions,
            vec![first_predecessor.clone()]
        );
        assert_eq!(
            multi_activation.member_states[1].rollback_symbol_resolutions,
            vec![second_predecessor.clone()]
        );
        let changed_predecessor = MachOSymbolResolutionRecord {
            direct_value: Some(0x7000),
            ..first_predecessor
        };
        assert!(
            reconcile_reactivated_macho_archive_rollback_symbol_resolutions(
                &mut multi_activation,
                &[
                    changed_predecessor,
                    second_predecessor,
                    unrelated_predecessor,
                ],
            )
            .unwrap_err()
            .contains("changed while dormant")
        );

        let mut overlapping = multi_patch;
        overlapping.macho_archive_members[1].forward_patches[0].output_offset =
            first_output_offset as u64 + 2;
        overlapping.macho_archive_members[1].rollback_patches[0].output_offset =
            first_output_offset as u64 + 2;
        assert!(
            reactivated_macho_archive_text_activation(
                &multi_current,
                &input_file,
                &[
                    current_identifier.to_vec(),
                    second_current_identifier.to_vec(),
                ],
                &multi_resolver,
                &overlapping,
                &dormant_output,
                &[rollback.clone(), second_rollback],
                &[],
                &[],
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("transactions conflict")
        );

        let mut changed_hash = patch.clone();
        changed_hash.macho_archive_members[0].members[0].object_hash =
            hash_bytes(b"different object bytes");
        assert!(
            reactivated_macho_archive_text_activation(
                &current,
                &input_file,
                &[current_identifier.to_vec()],
                &resolver,
                &changed_hash,
                &dormant_output,
                std::slice::from_ref(&rollback),
                &[],
                &[],
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("changed while dormant")
        );

        let mut conflicting_rollback = rollback;
        conflicting_rollback.direct_value = Some(0x3000);
        assert!(
            reactivated_macho_archive_text_activation(
                &current,
                &input_file,
                &[current_identifier.to_vec()],
                &resolver,
                &patch,
                &dormant_output,
                std::slice::from_ref(&conflicting_rollback),
                &[],
                &[],
                true,
            )
            .unwrap()
            .err()
            .unwrap()
            .contains("rollback symbol changed while dormant")
        );
    }

    fn test_macho_import_branch_record(
        output: &mut TestMachOImportOutput,
        input_file: &str,
        input: &str,
        target_name: SharedText,
    ) -> RelocationRecord {
        let raw = object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        };
        let file = object::File::parse(&*output.bytes).unwrap();
        let place = macho_output_address_for_file_offset(&file, output.text_offset).unwrap();
        let written_value = macho_aarch64_relocated_value(
            object::macho::ARM64_RELOC_BRANCH26,
            output.stub_address,
            0,
            place,
        )
        .unwrap();
        let rel_info =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(raw)
                .unwrap();
        rel_info
            .write_to_buffer(
                written_value,
                &mut output.bytes[output.text_offset as usize..output.text_offset as usize + 4],
            )
            .unwrap();
        RelocationRecord {
            target_symbol_id: 23,
            written_value: Some(written_value),
            target_value: 0,
            applied_target_value: Some(output.stub_address),
            target_name: Some(target_name),
            target: None,
            input_file: input_file.into(),
            input: input.into(),
            section_index: 1,
            relocation_offset: 0,
            output_offset: output.text_offset,
            size: 4,
            kind: encode_macho_aarch64_relocation_kind(raw),
            addend: 0,
        }
    }

    fn test_macho_import_replay(
        record: &RelocationRecord,
        candidates: Vec<u64>,
    ) -> MachOTextRelocationReplay {
        let raw = decode_macho_aarch64_relocation_kind(record.kind).unwrap();
        MachOTextRelocationReplay {
            relocation_index: None,
            input_file: record.input_file.clone(),
            input: record.input.to_string(),
            section_index: record.section_index,
            previous_output_offset: None,
            previous_range: None,
            current_range: 0..record.size as usize,
            r_type: raw.r_type,
            kind: record.kind,
            rel_info:
                <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(
                    raw,
                )
                .unwrap(),
            previous_written_value: None,
            previous_applied_target_value: None,
            current_target_value: record.target_value,
            used_normalized_target_alias: false,
            current_relocation_target_candidates: candidates,
            relax_pageoff_load_to_direct: false,
            current_target_section_offset: 0,
            target_symbol_id: record.target_symbol_id,
            target_name: record.target_name.clone(),
            target_is_global: true,
            target: None,
            addend: record.addend,
            chained_rebase_output_offset: None,
            chained_rebase_value: None,
        }
    }

