    #[test]
    fn recorded_macho_branch_index_omits_unrelated_relocations() {
        let page_kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_PAGE21,
        });
        let branch_kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        });
        let mut relocations = (0..4096)
            .map(|offset| {
                relocation_record(
                    "first.o",
                    1,
                    9,
                    Some(0),
                    0,
                    Some("_page_target"),
                    None,
                    offset,
                    offset,
                    4,
                    page_kind,
                    0,
                )
            })
            .collect::<Vec<_>>();
        relocations.push(relocation_record(
            "first.o",
            1,
            7,
            Some(0),
            0,
            Some("_branch_target"),
            None,
            4096,
            4096,
            4,
            branch_kind,
            0,
        ));
        let branch_target = SharedText::from(hex::encode("_branch_target"));
        let page_target = SharedText::from(hex::encode("_page_target"));
        let index = RecordedMachOBranchTargetCandidates::new(&relocations);

        assert_eq!(index.indexed_relocation_count(), 1);
        assert_eq!(index.target_symbol_id(Some(&branch_target), None), 7);
        assert_eq!(index.target_symbol_id(Some(&page_target), None), 9);
    }

    #[test]
    fn recorded_macho_branch_candidates_reject_mismatched_or_stale_records() {
        let target_value = 0;
        let applied_target_value = 0x1000;
        let (previous_output, text_range, written_value) =
            recorded_branch_output(target_value, applied_target_value, 0);
        let output_file = object::File::parse(previous_output.as_slice()).unwrap();
        let branch_kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        });
        let mut relocation = relocation_record(
            "first.o",
            1,
            7,
            Some(written_value),
            target_value,
            Some("_target"),
            None,
            0,
            text_range.start as u64,
            4,
            branch_kind,
            0,
        );
        relocation.applied_target_value = Some(applied_target_value);
        let target_name = SharedText::from(hex::encode("_target"));

        assert!(
            recorded_macho_branch_target_candidates(
                &[relocation.clone()],
                Some(&target_name),
                true,
                None,
                target_value + 4,
                0,
                &previous_output,
                &output_file,
            )
            .is_empty()
        );
        assert!(
            recorded_macho_branch_target_candidates(
                &[relocation.clone()],
                Some(&target_name),
                true,
                None,
                target_value,
                4,
                &previous_output,
                &output_file,
            )
            .is_empty()
        );

        relocation.written_value = Some(written_value + 4);
        assert!(
            recorded_macho_branch_target_candidates(
                &[relocation],
                Some(&target_name),
                true,
                None,
                target_value,
                0,
                &previous_output,
                &output_file,
            )
            .is_empty()
        );
    }

    fn rematerialized_macho_replay(
        input: &str,
        target_name: &str,
        target_value: u64,
        target: RelocationTargetRecord,
    ) -> MachOTextRelocationReplay {
        let raw_relocation = object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_PAGE21,
        };
        let rel_info =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(
                raw_relocation,
            )
            .unwrap();
        MachOTextRelocationReplay {
            relocation_index: None,
            input_file: SharedText::from(hex::encode(input)),
            input: hex::encode(input),
            section_index: 1,
            previous_output_offset: None,
            previous_range: None,
            current_range: 0..4,
            r_type: raw_relocation.r_type,
            kind: encode_macho_aarch64_relocation_kind(raw_relocation),
            rel_info,
            previous_written_value: None,
            previous_applied_target_value: None,
            current_target_value: target_value,
            used_normalized_target_alias: false,
            current_relocation_target_candidates: vec![target_value],
            relax_pageoff_load_to_direct: false,
            current_target_section_offset: target.section_offset,
            target_symbol_id: 1,
            target_name: Some(SharedText::from(hex::encode(target_name))),
            target_is_global: true,
            target: Some(target),
            addend: 0,
            chained_rebase_output_offset: None,
            chained_rebase_value: None,
        }
    }

    #[test]
    fn normalized_macho_local_target_requires_exact_output_symbol() {
        let global = test_macho_object(&[0; 4], &[0; 8], 2);
        let target_value = 6;
        let has_witness = |output: &[u8], target_value| {
            let output_file = object::File::parse(output).unwrap();
            normalized_macho_local_target_has_output_witness(
                output,
                &output_file,
                &hex::encode("_data"),
                target_value,
            )
            .unwrap()
            .unwrap()
        };

        assert!(!has_witness(&global, target_value));

        let mut local = global.clone();
        let data_entry = test_macho_symbol_entry_offset(&local, b"_data");
        local[data_entry + 4] = object::macho::N_SECT;
        assert!(has_witness(&local, target_value));
        assert!(!has_witness(&local, target_value + 1));

        let mut weak = local.clone();
        weak[data_entry + 6..data_entry + 8]
            .copy_from_slice(&object::macho::N_WEAK_DEF.to_le_bytes());
        assert!(!has_witness(&weak, target_value));

        let mut private = local.clone();
        private[data_entry + 4] |= object::macho::N_PEXT;
        assert!(!has_witness(&private, target_value));

        let mut undefined = local.clone();
        undefined[data_entry + 4] = object::macho::N_UNDF;
        undefined[data_entry + 5] = 0;
        assert!(!has_witness(&undefined, target_value));

        let mut outside_section = local.clone();
        outside_section[data_entry + 8..data_entry + 16].copy_from_slice(&12_u64.to_le_bytes());
        assert!(!has_witness(&outside_section, 12));

        let duplicate = add_test_macho_local_alias(local, b"_data", 2, target_value);
        assert!(!has_witness(&duplicate, target_value));

        let output_file = object::File::parse(global.as_slice()).unwrap();
        assert!(
            !normalized_macho_local_target_has_output_witness(
                &global,
                &output_file,
                &hex::encode("_missing"),
                target_value,
            )
            .unwrap()
            .unwrap()
        );
    }

    #[test]
    fn normalized_macho_target_alias_requires_reconciled_activation() {
        let input = hex::encode("lib.rlib");
        let target = RelocationTargetRecord {
            input_file: input.clone().into(),
            input: input.clone().into(),
            section_index: 1,
            section_offset: 0,
        };
        let replay = rematerialized_macho_replay("lib.rlib", "_target", 0x1000, target.clone());
        let mut replays = MachOTextRelocationReplays {
            replays: vec![replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: true,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let can_activate = |replays: &MachOTextRelocationReplays,
                            resolutions: &[MachOSymbolResolutionRecord],
                            moves: &[MachOSymbolResolutionMove],
                            activation: &[MachOSymbolResolutionRecord],
                            pending: &[MachORelocationTargetMove]| {
            replays
                .can_activate_macho_archive_members(resolutions, moves, activation, pending)
                .unwrap()
        };
        assert!(can_activate(&replays, &[], &[], &[], &[]));

        replays.replays[0].used_normalized_target_alias = true;
        assert!(!can_activate(&replays, &[], &[], &[], &[]));

        replays.rematerialized_sections.push((
            input.clone().into(),
            hex::encode("previous.o"),
            1,
            input.clone(),
            1,
        ));
        assert!(!can_activate(&replays, &[], &[], &[], &[]));

        let resolution = MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode("_target")),
            direct_value: Some(0x1000),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(target.clone()),
        };
        assert!(!can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            &[],
            &[],
            &[],
        ));
        let resolution_move = MachOSymbolResolutionMove {
            name: resolution.name.clone(),
            previous_value: 0x800,
            current_value: 0x1000,
            previous_target: target.clone(),
            current_target: target.clone(),
        };
        assert!(can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            std::slice::from_ref(&resolution_move),
            &[],
            &[],
        ));
        let mut mismatched_move = resolution_move.clone();
        mismatched_move.current_value += 1;
        assert!(!can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            std::slice::from_ref(&mismatched_move),
            &[],
            &[],
        ));
        assert!(can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            &[],
            std::slice::from_ref(&resolution),
            &[],
        ));
        assert!(!can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            std::slice::from_ref(&resolution_move),
            std::slice::from_ref(&resolution),
            &[],
        ));

        let pending_move = MachORelocationTargetMove {
            relocation_index: 0,
            current_section_offset: 0,
            current_target_value: 0x1000,
            current_input: None,
        };
        assert!(!can_activate(
            &replays,
            std::slice::from_ref(&resolution),
            std::slice::from_ref(&resolution_move),
            &[],
            std::slice::from_ref(&pending_move),
        ));

        replays.replays[0].target_is_global = false;
        assert!(!can_activate(&replays, &[], &[], &[], &[]));
        replays.replays[0].target.as_mut().unwrap().input = hex::encode("other.o").into();
        assert!(!can_activate(&replays, &[], &[], &[], &[]));
    }

    #[test]
    fn filtered_macho_text_replays_require_changed_input_record_owners() {
        let input = "changed.o";
        let target = RelocationTargetRecord {
            input_file: SharedText::from(hex::encode(input)),
            input: SharedText::from(hex::encode(input)),
            section_index: 2,
            section_offset: 0,
        };
        let mut replay = rematerialized_macho_replay(input, "_target", 0x1000, target);
        replay.relocation_index = Some(0);
        let mut replays = MachOTextRelocationReplays {
            replays: vec![replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let input_file = hex::encode(input);
        let relocations = vec![relocation_record(
            input,
            1,
            1,
            Some(0x1000),
            0x1000,
            Some("_target"),
            Some((input, 2, 0)),
            0,
            100,
            4,
            0,
            0,
        )];

        assert!(replays.uses_only_records_owned_by_input(&relocations, &input_file));

        replays.replays[0].relocation_index = None;
        assert!(replays.uses_only_records_owned_by_input(&relocations, &input_file));
        replays.replays[0].relocation_index = Some(0);

        replays.replays[0].input_file = SharedText::from(hex::encode("other.o"));
        assert!(!replays.uses_only_records_owned_by_input(&relocations, &input_file));
        replays.replays[0].input_file = SharedText::from(input_file.clone());

        replays.rematerialized_sections.push((
            SharedText::from(input_file.clone()),
            hex::encode(input),
            1,
            hex::encode(input),
            1,
        ));
        assert!(replays.uses_only_records_owned_by_input(&relocations, &input_file));
        replays.rematerialized_sections[0].0 = SharedText::from(hex::encode("other.o"));
        assert!(!replays.uses_only_records_owned_by_input(&relocations, &input_file));
        replays.rematerialized_sections[0].0 = SharedText::from(input_file.clone());
        replays.rematerialized_sections.clear();

        replays.symbol_resolutions_changed = true;
        assert!(replays.uses_only_records_owned_by_input(&relocations, &input_file));

        replays.replays[0].relocation_index = Some(1);
        assert!(!replays.uses_only_records_owned_by_input(&relocations, &input_file));
    }

