    #[test]
    fn macho_text_relocation_replay_allocates_and_rematerializes_local_branch_thunk() {
        let previous_output = test_macho_object(&[0; 16], b"\x01\x02\x03\x04", 0);
        let output_file = object::File::parse(previous_output.as_slice()).unwrap();
        let text_range = test_macho_section_range(&previous_output, "__text");
        let input = "crate-hash.cgu.rcgu.o";
        let target_name = "_target";
        let target = RelocationTargetRecord {
            input_file: SharedText::from(hex::encode("libarchive.rlib")),
            input: SharedText::from(hex::encode("target.rcgu.o")),
            section_index: 1,
            section_offset: 0,
        };
        let place =
            macho_output_address_for_file_offset(&output_file, text_range.start as u64).unwrap();
        let target_value = place + 200 * 1024 * 1024;
        let mut replay =
            rematerialized_macho_replay(input, target_name, target_value, target.clone());
        replay.r_type = object::macho::ARM64_RELOC_BRANCH26;
        replay.kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        });
        replay.rel_info =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(
                object::macho::RelocationInfo {
                    r_address: 0,
                    r_symbolnum: 0,
                    r_pcrel: true,
                    r_length: 2,
                    r_extern: true,
                    r_type: object::macho::ARM64_RELOC_BRANCH26,
                },
            )
            .unwrap();
        replay.current_target_value = target_value;
        replay.current_relocation_target_candidates = vec![target_value];
        let replays = MachOTextRelocationReplays {
            replays: vec![replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let mut patches = vec![ResolvedSectionPatch {
            section: PatchSection {
                input: hex::encode(input),
                section_index: 1,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: 4,
                output_offset: text_range.start as u64,
                output_size: 16,
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            patch: SectionPatch {
                output_offset: text_range.start as u64,
                size: 16,
                data: 0x1400_0000_u32.to_le_bytes().to_vec(),
                deferred_relocation: None,
                preserve_ranges: vec![0..4],
                adjustments: Vec::new(),
            },
        }];
        let mut relocations = Vec::new();

        apply_macho_text_relocation_replays(
            &mut patches,
            &replays,
            &previous_output,
            &mut relocations,
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
        )
        .unwrap();

        let thunk_address = place + 4;
        let mut expected_thunk = vec![0; 12];
        <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::write_thunk(
            thunk_address,
            target_value,
            &mut expected_thunk,
        );
        let mut expected_branch = 0x1400_0000_u32.to_le_bytes();
        replays.replays[0]
            .rel_info
            .write_to_buffer(thunk_address - place, &mut expected_branch)
            .unwrap();
        assert_eq!(&patches[0].patch.data[..4], expected_branch);
        assert_eq!(&patches[0].patch.data[4..], expected_thunk);
        assert_eq!(relocations.len(), 1);
        assert_eq!(relocations[0].applied_target_value, Some(thunk_address));

        let mut next_previous_output = previous_output;
        next_previous_output[text_range.start..text_range.start + 16]
            .copy_from_slice(&patches[0].patch.data);
        let mut next_replay = replays.replays[0].clone();
        next_replay.relocation_index = Some(0);
        next_replay.previous_output_offset = Some(text_range.start as u64);
        next_replay.previous_range = Some(0..4);
        next_replay.previous_written_value = relocations[0].written_value;
        next_replay.previous_applied_target_value = Some(thunk_address);
        next_replay.current_relocation_target_candidates = vec![thunk_address, target_value];
        let next_replays = MachOTextRelocationReplays {
            replays: vec![next_replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let mut next_patches = vec![ResolvedSectionPatch {
            section: patches[0].section.clone(),
            patch: SectionPatch {
                output_offset: text_range.start as u64,
                size: 16,
                data: 0x1400_0000_u32.to_le_bytes().to_vec(),
                deferred_relocation: None,
                preserve_ranges: vec![0..4],
                adjustments: Vec::new(),
            },
        }];

        apply_macho_text_relocation_replays(
            &mut next_patches,
            &next_replays,
            &next_previous_output,
            &mut relocations,
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
        )
        .unwrap();

        assert_eq!(&next_patches[0].patch.data[4..], expected_thunk);
        assert_eq!(relocations.len(), 1);
        assert_eq!(relocations[0].applied_target_value, Some(thunk_address));

        let direct_target = place + 8;
        let mut grown_replay = next_replays.replays[0].clone();
        grown_replay.current_target_value = direct_target;
        grown_replay.current_relocation_target_candidates = vec![direct_target];
        let grown_replays = MachOTextRelocationReplays {
            replays: vec![grown_replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let mut grown_patches = vec![ResolvedSectionPatch {
            section: PatchSection {
                input_size: 16,
                ..patches[0].section.clone()
            },
            patch: SectionPatch {
                output_offset: text_range.start as u64,
                size: 16,
                data: vec![0; 16],
                deferred_relocation: None,
                preserve_ranges: vec![0..4],
                adjustments: Vec::new(),
            },
        }];

        apply_macho_text_relocation_replays(
            &mut grown_patches,
            &grown_replays,
            &next_previous_output,
            &mut relocations,
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
            &mut Vec::new(),
        )
        .unwrap();

        assert_eq!(&grown_patches[0].patch.data[4..], &[0; 12]);
        assert_eq!(relocations[0].applied_target_value, Some(direct_target));
    }

    #[test]
    fn macho_text_relocation_replay_allocates_persistent_reserved_branch_thunk() {
        let previous_output = test_macho_object(&[0; 64], b"\x01\x02\x03\x04", 0);
        let output_file = object::File::parse(previous_output.as_slice()).unwrap();
        let text_range = test_macho_section_range(&previous_output, "__text");
        let input = "crate-hash.cgu.rcgu.o";
        let target_name = "_target";
        let target = RelocationTargetRecord {
            input_file: SharedText::from(hex::encode("libarchive.rlib")),
            input: SharedText::from(hex::encode("target.rcgu.o")),
            section_index: 1,
            section_offset: 0,
        };
        let place =
            macho_output_address_for_file_offset(&output_file, text_range.start as u64).unwrap();
        let target_value = place + 200 * 1024 * 1024;
        let mut replay =
            rematerialized_macho_replay(input, target_name, target_value, target.clone());
        replay.r_type = object::macho::ARM64_RELOC_BRANCH26;
        replay.kind = encode_macho_aarch64_relocation_kind(object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        });
        replay.rel_info =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(
                object::macho::RelocationInfo {
                    r_address: 0,
                    r_symbolnum: 0,
                    r_pcrel: true,
                    r_length: 2,
                    r_extern: true,
                    r_type: object::macho::ARM64_RELOC_BRANCH26,
                },
            )
            .unwrap();
        replay.current_target_value = target_value;
        replay.current_relocation_target_candidates = vec![target_value];
        let replays = MachOTextRelocationReplays {
            replays: vec![replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let mut patches = vec![ResolvedSectionPatch {
            section: PatchSection {
                input: hex::encode(input),
                section_index: 1,
                section_name: Some("__TEXT,__text".to_owned()),
                input_size: 4,
                output_offset: text_range.start as u64,
                output_size: 4,
                data_hash: None,
                cstring_nul_boundaries_hash: None,
            },
            patch: SectionPatch {
                output_offset: text_range.start as u64,
                size: 4,
                data: 0x1400_0000_u32.to_le_bytes().to_vec(),
                deferred_relocation: None,
                preserve_ranges: vec![0..4],
                adjustments: Vec::new(),
            },
        }];
        let reserve_offset = (text_range.start + 16).next_multiple_of(16) as u64;
        let mut reserved_ranges = vec![ReservedRangeRecord {
            output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
            alignment_exponent: 4,
            output_offset: reserve_offset,
            size: 32,
        }];
        let mut resolutions = vec![MachOSymbolResolutionRecord {
            name: SharedText::from(hex::encode(target_name)),
            direct_value: Some(target_value),
            got_address: None,
            stub_address: None,
            thunk_addresses: Vec::new(),
            target: Some(target),
        }];
        let mut relocations = Vec::new();
        let mut reserved_thunk_patches = Vec::new();

        apply_macho_text_relocation_replays(
            &mut patches,
            &replays,
            &previous_output,
            &mut relocations,
            &mut resolutions,
            &mut reserved_ranges,
            &mut reserved_thunk_patches,
            &mut Vec::new(),
        )
        .unwrap();

        let thunk_address =
            macho_output_address_for_file_offset(&output_file, reserve_offset).unwrap();
        assert_eq!(resolutions[0].thunk_addresses, vec![thunk_address]);
        assert_eq!(
            reserved_ranges,
            vec![ReservedRangeRecord {
                output_section_id: crate::output_section_id::TEXT.as_usize() as u32,
                alignment_exponent: 4,
                output_offset: reserve_offset + 16,
                size: 16,
            }]
        );
        assert_eq!(reserved_thunk_patches.len(), 1);
        assert_eq!(reserved_thunk_patches[0].output_offset, reserve_offset);
        assert_eq!(reserved_thunk_patches[0].size, 16);
        let mut expected_thunk = vec![0; 12];
        <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::write_thunk(
            thunk_address,
            target_value,
            &mut expected_thunk,
        );
        assert_eq!(reserved_thunk_patches[0].data, expected_thunk);
        assert_eq!(relocations[0].applied_target_value, Some(thunk_address));

        let mut expected_branch = 0x1400_0000_u32.to_le_bytes();
        replays.replays[0]
            .rel_info
            .write_to_buffer(thunk_address - place, &mut expected_branch)
            .unwrap();
        assert_eq!(patches[0].patch.data, expected_branch);

        let mut next_replay = replays.replays[0].clone();
        next_replay.relocation_index = Some(0);
        next_replay.current_relocation_target_candidates = vec![target_value];
        let next_replays = MachOTextRelocationReplays {
            replays: vec![next_replay],
            rematerialized_sections: Vec::new(),
            local_symbol_cohorts: Vec::new(),
            normalize_rust_archive_patch_inputs: false,
            symbol_resolutions_changed: false,
            possible_removed_resolution_names: Vec::new(),
        };
        let mut next_patches = vec![ResolvedSectionPatch {
            section: patches[0].section.clone(),
            patch: SectionPatch {
                output_offset: text_range.start as u64,
                size: 4,
                data: 0x1400_0000_u32.to_le_bytes().to_vec(),
                deferred_relocation: None,
                preserve_ranges: vec![0..4],
                adjustments: Vec::new(),
            },
        }];
        let mut next_reserved_thunk_patches = Vec::new();

        apply_macho_text_relocation_replays(
            &mut next_patches,
            &next_replays,
            &previous_output,
            &mut relocations,
            &mut resolutions,
            &mut reserved_ranges,
            &mut next_reserved_thunk_patches,
            &mut Vec::new(),
        )
        .unwrap();

        assert!(next_reserved_thunk_patches.is_empty());
        assert_eq!(resolutions[0].thunk_addresses, vec![thunk_address]);
        assert_eq!(next_patches[0].patch.data, expected_branch);
        assert_eq!(relocations[0].applied_target_value, Some(thunk_address));
    }

    #[test]
    fn rematerialized_macho_symbol_resolution_activates_new_direct_target() {
        let input = state("args", b"output", &[("input.o", b"input")])
            .input_files
            .remove(0);
        let target = RelocationTargetRecord {
            input_file: SharedText::from(hex::encode("input.o")),
            input: SharedText::from(hex::encode("input.o")),
            section_index: 3,
            section_offset: 32,
        };
        let replay =
            rematerialized_macho_replay("input.o", "_new_target", 0x1000_4020, target.clone());
        let mut resolutions = Vec::new();

        let (output_symbols, changed, possible_removals) =
            reconcile_rematerialized_macho_symbol_resolutions(
                &mut resolutions,
                &[],
                &[replay],
                &[(
                    SharedText::from(hex::encode("input.o")),
                    hex::encode("input.o"),
                    1,
                    hex::encode("input.o"),
                    1,
                )],
                false,
                &[],
                &input,
            )
            .unwrap();

        assert!(changed);
        assert!(possible_removals.is_empty());
        assert_eq!(output_symbols.len(), 1);
        assert_eq!(output_symbols[0].target_name, hex::encode("_new_target"));
        assert_eq!(output_symbols[0].previous_target_value, 0);
        assert_eq!(output_symbols[0].target_value, 0x1000_4020);
        assert_eq!(
            resolutions,
            vec![MachOSymbolResolutionRecord {
                name: SharedText::from(hex::encode("_new_target")),
                direct_value: Some(0x1000_4020),
                got_address: None,
                stub_address: None,
                thunk_addresses: Vec::new(),
                target: Some(target),
            }]
        );
    }

