    #[cfg_attr(target_os = "wasi", ignore = "wasi doesn't have a temp dir")]
    #[test]
    fn metadata_update_overlay_updates_only_changed_inputs() {
        let dir = tempfile::tempdir().unwrap();
        let mut state = state("args", b"output", &[("a.o", b"a"), ("b.o", b"b")]);
        state.input_files[0].patch = Some(FilePatchState {
            fingerprint: "old-patch-hash".to_owned(),
            archive_member_set_proof: None,
            archive_member_patch_fingerprints: None,
            macho_archive_members: Vec::new(),
            sections: vec![FilePatchSectionState {
                input: hex::encode("a.o"),
                section_index: 1,
                section_name: Some(".text.a".to_owned()),
                input_size: 4,
                output_offset: 100,
                output_size: 8,
                data_hash: Some("old-section-hash".to_owned()),
                cstring_nul_boundaries_hash: None,
            }],
            raw_sections: None,
        });
        state.sections.push(section_record("a.o", 1, 100, 8));
        state.macho_symbol_resolutions_file =
            Some(write_macho_resolutions_sidecar(dir.path(), &[]).unwrap());
        state.write(dir.path()).unwrap();
        let base_index = std::fs::read_to_string(dir.path().join(INDEX_FILE)).unwrap();
        let mut updated = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        updated.link_start = Some(FileIdentity {
            len: 0,
            dev: 1,
            ino: 2,
            modified_sec: 3,
            modified_nsec: 4,
            changed_sec: 5,
            changed_nsec: 6,
        });
        updated.output = FileContentState::from_bytes(b"new-output");
        updated.macho_symbol_resolutions_file = None;
        updated.input_files[0].content = FileContentState::from_bytes(b"aa");
        updated.input_files[0].patch = Some(FilePatchState {
            fingerprint: "new-patch-hash".to_owned(),
            archive_member_set_proof: Some(ArchiveMemberSetProof {
                raw_ordered_hash: "raw-hash".to_owned(),
                normalized_ordered_hash: "normalized-hash".to_owned(),
                member_count: 2,
                rustc_link_content_digest: None,
            }),
            archive_member_patch_fingerprints: None,
            macho_archive_members: Vec::new(),
            sections: vec![FilePatchSectionState {
                input: hex::encode("a.o"),
                section_index: 1,
                section_name: Some(".text.a".to_owned()),
                input_size: 4,
                output_offset: 100,
                output_size: 8,
                data_hash: Some("new-section-hash".to_owned()),
                cstring_nul_boundaries_hash: Some("cstring-hash".to_owned()),
            }],
            raw_sections: None,
        });

        updated
            .write_metadata_update_for_inputs(dir.path(), &[0])
            .unwrap();

        assert_eq!(
            std::fs::read_to_string(dir.path().join(INDEX_FILE)).unwrap(),
            base_index
        );
        assert!(metadata_update_path(dir.path()).exists());
        let mut metadata = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        assert_eq!(metadata.output, updated.output);
        assert!(metadata.macho_symbol_resolutions_file.is_none());
        assert_eq!(
            metadata.input_files[0].content,
            updated.input_files[0].content
        );
        let metadata_patch = metadata.input_files[0].patch.as_ref().unwrap();
        let updated_patch = updated.input_files[0].patch.as_ref().unwrap();
        assert_eq!(metadata_patch.fingerprint, updated_patch.fingerprint);
        assert_eq!(
            metadata_patch.archive_member_set_proof,
            updated_patch.archive_member_set_proof
        );
        assert!(metadata_patch.sections.is_empty());
        assert_eq!(
            metadata_patch.raw_sections.as_deref(),
            Some(render_patch_sections(updated_patch).as_str())
        );
        assert_eq!(metadata.input_files[1], state.input_files[1]);

        metadata.input_files[1].content = FileContentState::from_bytes(b"bb");
        metadata
            .write_metadata_update_for_inputs(dir.path(), &[1])
            .unwrap();
        let composed = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        assert_eq!(
            composed.input_files[0].content,
            updated.input_files[0].content
        );
        assert_eq!(
            composed.input_files[0]
                .patch
                .as_ref()
                .map(|patch| patch.fingerprint.as_str()),
            Some("new-patch-hash")
        );
        assert_eq!(
            composed.input_files[1].content,
            metadata.input_files[1].content
        );

        composed.write_index(dir.path()).unwrap();
        assert!(!metadata_update_path(dir.path()).exists());
        let persisted = PersistedState::read(dir.path()).unwrap().unwrap();
        assert_eq!(persisted.input_files[0].patch, updated.input_files[0].patch);
        assert_eq!(persisted.sections, state.sections);
        assert!(persisted.macho_symbol_resolutions_file.is_none());
    }

    #[cfg_attr(target_os = "wasi", ignore = "wasi doesn't have a temp dir")]
    #[test]
    fn metadata_record_overrides_replace_owner_records() {
        let dir = tempfile::tempdir().unwrap();
        let mut state = state(
            "args",
            b"output",
            &[("a.o", b"a"), ("b.o", b"b"), ("c.o", b"c")],
        );
        state.sections.push(section_record("a.o", 1, 100, 8));
        state.sections.push(section_record("b.o", 1, 200, 8));
        state.sections.push(section_record("c.o", 1, 300, 8));
        state.relocations.push(relocation_record(
            "a.o",
            1,
            4,
            Some(0x1000),
            0x2000,
            Some("target"),
            Some(("b.o", 1, 0)),
            0,
            100,
            8,
            1,
            0,
        ));
        state.fdes.push(fde_record("a.o", 1, 2, 0, 120, 24));
        state
            .dynamic_relocations
            .push(dynamic_relocation_record("a.o", 1, 0, 160, 24));
        state.write(dir.path()).unwrap();
        let base_index = std::fs::read(dir.path().join(INDEX_FILE)).unwrap();
        let base_sections_file = PersistedState::read_metadata(dir.path())
            .unwrap()
            .unwrap()
            .sections_file
            .unwrap();
        let base_sections = std::fs::read(dir.path().join(&base_sections_file)).unwrap();

        let mut updated = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        updated.load_macho_symbol_resolutions(dir.path()).unwrap();
        updated
            .sections
            .retain(|record| record.input_file != hex::encode("a.o"));
        updated.sections.push(section_record("a.o", 2, 104, 12));
        updated.relocations.clear();
        updated.relocations.push(relocation_record(
            "a.o",
            2,
            5,
            Some(0x3000),
            0x4000,
            Some("new-target"),
            Some(("c.o", 1, 4)),
            4,
            104,
            8,
            1,
            0,
        ));
        updated.fdes.clear();
        updated.fdes.push(fde_record("a.o", 2, 3, 0, 140, 24));
        updated.dynamic_relocations.clear();
        updated
            .dynamic_relocations
            .push(dynamic_relocation_record("a.o", 2, 4, 180, 24));
        updated
            .write_record_overrides_for_inputs(dir.path(), [hex::encode("a.o")])
            .unwrap();
        updated
            .write_metadata_update_for_inputs(dir.path(), &[0])
            .unwrap();

        assert_eq!(
            std::fs::read(dir.path().join(INDEX_FILE)).unwrap(),
            base_index
        );
        assert_eq!(
            std::fs::read(dir.path().join(&base_sections_file)).unwrap(),
            base_sections
        );
        let restored = PersistedState::read(dir.path()).unwrap().unwrap();
        assert_eq!(
            restored
                .sections
                .iter()
                .filter(|record| record.input_file == hex::encode("a.o"))
                .cloned()
                .collect::<Vec<_>>(),
            vec![section_record("a.o", 2, 104, 12)]
        );
        assert_eq!(restored.relocations, updated.relocations);
        assert_eq!(restored.fdes, updated.fdes);
        assert_eq!(restored.dynamic_relocations, updated.dynamic_relocations);
        restored.write_index(dir.path()).unwrap();
        assert_eq!(
            std::fs::read(dir.path().join(INDEX_FILE)).unwrap(),
            base_index
        );
        assert_eq!(
            PersistedState::read(dir.path())
                .unwrap()
                .unwrap()
                .relocations,
            updated.relocations
        );

        let mut metadata = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        let b_inputs = [hex::encode("b.o")].into_iter().collect::<HashSet<_>>();
        let filtered_coverage = metadata
            .read_records_for_input_files(dir.path(), &b_inputs)
            .unwrap();
        assert!(filtered_coverage.complete_record_input_files.is_empty());
        assert_eq!(metadata.sections, vec![section_record("b.o", 1, 200, 8)]);
        assert!(metadata.relocations.is_empty());

        let mut metadata = PersistedState::read_metadata(dir.path()).unwrap().unwrap();
        let c_inputs = [hex::encode("c.o")].into_iter().collect::<HashSet<_>>();
        metadata
            .read_records_for_input_files(dir.path(), &c_inputs)
            .unwrap();
        assert_eq!(metadata.sections, vec![section_record("c.o", 1, 300, 8)]);
        assert_eq!(metadata.relocations, updated.relocations);
    }

    #[cfg_attr(target_os = "wasi", ignore = "wasi doesn't have a temp dir")]
    #[test]
    fn metadata_record_overrides_preserve_deletions_and_successive_inputs() {
        let dir = tempfile::tempdir().unwrap();
        let mut state = state("args", b"output", &[("a.o", b"a"), ("b.o", b"b")]);
        state.sections.push(section_record("a.o", 1, 100, 8));
        state.sections.push(section_record("b.o", 1, 200, 8));
        state.relocations.push(relocation_record(
            "a.o",
            1,
            4,
            Some(0x1000),
            0x2000,
            Some("target"),
            Some(("b.o", 1, 0)),
            0,
            100,
            8,
            1,
            0,
        ));
        state.write(dir.path()).unwrap();

        let mut updated = PersistedState::read(dir.path()).unwrap().unwrap();
        let a = hex::encode("a.o");
        updated
            .sections
            .retain(|record| record.input_file.as_str() != a);
        updated
            .relocations
            .retain(|record| record.input_file.as_str() != a);
        updated
            .write_record_overrides_for_inputs(dir.path(), [a.clone()])
            .unwrap();
        assert!(updated.record_overrides_file.is_none());
        updated
            .write_metadata_update_for_inputs(dir.path(), &[0])
            .unwrap();

        let deleted = PersistedState::read(dir.path()).unwrap().unwrap();
        assert!(
            deleted
                .sections
                .iter()
                .all(|record| record.input_file.as_str() != a)
        );
        assert!(deleted.relocations.is_empty());

        let mut updated = deleted;
        let b = hex::encode("b.o");
        updated
            .sections
            .retain(|record| record.input_file.as_str() != b);
        updated.sections.push(section_record("b.o", 2, 208, 16));
        updated
            .write_record_overrides_for_inputs(dir.path(), [b])
            .unwrap();
        updated
            .write_metadata_update_for_inputs(dir.path(), &[1])
            .unwrap();

        let restored = PersistedState::read(dir.path()).unwrap().unwrap();
        assert_eq!(restored.sections, vec![section_record("b.o", 2, 208, 16)]);
        assert!(restored.relocations.is_empty());
        assert_eq!(restored.record_override_inputs.len(), 2);
    }

