    #[cfg_attr(target_os = "wasi", ignore = "wasi doesn't have a temp dir")]
    #[test]
    fn disappeared_output_pins_retained_source_without_restoring() {
        let dir = tempfile::tempdir().unwrap();
        let output = dir.path().join("out");
        let state_dir = dir.path().join("out.incr");
        std::fs::write(&output, b"output").unwrap();
        let previous = FileContentState::from_path(&output).unwrap();
        install_output_snapshot(&state_dir, &output).unwrap();

        assert!(output.try_exists().unwrap());
        std::fs::remove_file(&output).unwrap();
        let output_match = output_content_match(&previous, &output, false).unwrap();

        assert_eq!(output_match, OutputContentMatch::Missing);
        let PreviousOutputSourceSelection::Available(source) =
            select_previous_output_source(&state_dir, &previous, &output, true, output_match)
                .unwrap()
        else {
            panic!("retained output snapshot was not selected");
        };
        let source_path = source.path().to_path_buf();
        assert_ne!(source.path(), output_snapshot_path(&state_dir));
        assert!(source.is_retained());
        std::fs::write(output_snapshot_path(&state_dir), b"changed").unwrap();
        assert_eq!(std::fs::read(source.path()).unwrap(), b"output");
        assert!(!output.exists());
        drop(source);
        assert!(!source_path.exists());
    }

    #[cfg(unix)]
    #[test]
    fn matching_live_output_is_pinned_before_the_public_path_changes() {
        let dir = tempfile::tempdir().unwrap();
        let output = dir.path().join("out");
        let state_dir = dir.path().join("out.incr");
        std::fs::create_dir(&state_dir).unwrap();
        std::fs::write(&output, b"selected").unwrap();
        let previous = FileContentState::from_path(&output).unwrap();

        let PreviousOutputSourceSelection::Available(source) = select_previous_output_source(
            &state_dir,
            &previous,
            &output,
            true,
            OutputContentMatch::Matches,
        )
        .unwrap() else {
            panic!("live output was not selected");
        };
        let source_path = source.path().to_path_buf();
        assert!(!source.is_retained());
        assert_ne!(source.path(), output);
        let selected_identity = source.live_identity().unwrap().clone();
        assert!(
            publish_selected_output_source(
                &state_dir,
                source.path(),
                &output,
                source.live_identity(),
                true,
            )
            .unwrap()
        );
        assert_eq!(
            FileIdentity::from_path(&output).unwrap().as_ref(),
            Some(&selected_identity)
        );

        std::fs::write(&output, b"replaced").unwrap();
        assert_eq!(std::fs::read(source.path()).unwrap(), b"selected");
        drop(source);
        assert!(!source_path.exists());
    }

