    #[test]
    fn macho_cross_input_relocations_follow_target_moves() {
        let absolute = object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: false,
            r_length: 3,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_UNSIGNED,
        };
        assert!(macho_aarch64_cross_input_relocation_is_supported(
            absolute, 8,
        ));
        let output = test_macho_unwind_output(0x1000);
        let (written, data) = macho_aarch64_cross_input_absolute_patch(
            absolute,
            8,
            output.text_offset,
            &output.bytes,
            0x2010,
            0x2000,
            0x3000,
        )
        .unwrap()
        .unwrap();
        assert_eq!(written, 0x3010);
        assert_eq!(data, 0x3010_u64.to_le_bytes());

        assert!(macho_aarch64_cross_input_relocation_is_supported(
            object::macho::RelocationInfo {
                r_address: 0,
                r_symbolnum: 0,
                r_pcrel: true,
                r_length: 2,
                r_extern: true,
                r_type: object::macho::ARM64_RELOC_BRANCH26,
            },
            4,
        ));
        assert!(!macho_aarch64_cross_input_relocation_is_supported(
            object::macho::RelocationInfo {
                r_address: 0,
                r_symbolnum: 0,
                r_pcrel: false,
                r_length: 2,
                r_extern: true,
                r_type: object::macho::ARM64_RELOC_BRANCH26,
            },
            4,
        ));
        assert!(macho_aarch64_cross_input_relocation_is_supported(
            object::macho::RelocationInfo {
                r_address: 0,
                r_symbolnum: 0,
                r_pcrel: true,
                r_length: 2,
                r_extern: true,
                r_type: object::macho::ARM64_RELOC_GOT_LOAD_PAGE21,
            },
            4,
        ));
        assert_eq!(
            macho_aarch64_relocated_value_after_target_move(
                object::macho::ARM64_RELOC_BRANCH26,
                0x1000,
                0x2000,
                0x2004,
                0,
            ),
            Some(0x1004)
        );
        assert_eq!(
            macho_aarch64_relocated_value_after_target_move(
                object::macho::ARM64_RELOC_PAGE21,
                (-0x4000_i64) as u64,
                0x1ffc,
                0x2004,
                0,
            ),
            Some((-0x3000_i64) as u64)
        );
        assert_eq!(
            macho_aarch64_relocated_value_after_target_move(
                object::macho::ARM64_RELOC_PAGEOFF12,
                0x1ffc,
                0x1ffc,
                0x2004,
                0,
            ),
            Some(0x2004)
        );
    }

    #[test]
    fn macho_cross_input_branch_patch_encodes_the_new_displacement() {
        let raw_relocation = object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        };
        let rel_info =
            <crate::macho_aarch64::MachOAArch64 as crate::platform::Arch>::relocation_from_raw(
                raw_relocation,
            )
            .unwrap();
        let previous_output = [0xfd, 0xff, 0xff, 0x17];
        let mut data = vec![0; previous_output.len()];

        materialize_deferred_relocation_patch(
            &mut data,
            &previous_output,
            DeferredRelocationPatch {
                rel_info,
                previous_written_value: (-12_i64) as u64,
                written_value: (-8_i64) as u64,
            },
        )
        .unwrap();

        assert_eq!(data, [0xfe, 0xff, 0xff, 0x17]);
    }

    #[test]
    fn macho_relocation_target_refreshes_repartitioned_archive_member() {
        let mut object = test_macho_object(&[0; 4], &[0; 8], 0);
        let data_name = object
            .windows(b"_data\0".len())
            .rposition(|window| window == b"_data\0")
            .unwrap();
        object[data_name..data_name + b"__Rxx".len()].copy_from_slice(b"__Rxx");
        let data_symbol = macho_symbol_value_field_range(&object, object::SymbolIndex(1))
            .unwrap()
            .start
            - 8;
        object[data_symbol + 4] = object::macho::N_SECT;
        object[data_symbol + 6..data_symbol + 8]
            .copy_from_slice(&object::macho::N_WEAK_DEF.to_le_bytes());
        let current_identifier = b"crate-hash.current-cgu.current-invocation.rcgu.o";
        let mut builder = ar::Builder::new(Vec::new());
        builder
            .append(
                &ar::Header::new(current_identifier.to_vec(), object.len() as u64),
                object.as_slice(),
            )
            .unwrap();
        let current = builder.into_inner().unwrap();
        let mut state = state("args", b"output", &[("libcrate.rlib", &current)]);
        let input = state.input_files.remove(0);
        let raw_relocation = object::macho::RelocationInfo {
            r_address: 0,
            r_symbolnum: 0,
            r_pcrel: true,
            r_length: 2,
            r_extern: true,
            r_type: object::macho::ARM64_RELOC_BRANCH26,
        };
        let mut relocation = relocation_record(
            "caller.o",
            1,
            42,
            Some(0),
            0x2000,
            Some("__Rxx"),
            Some(("libcrate.rlib", 2, 0)),
            0,
            300,
            4,
            encode_macho_aarch64_relocation_kind(raw_relocation),
            0,
        );
        relocation.target.as_mut().unwrap().input =
            hex::encode(b"libcrate.rlib\0crate-hash.retired-cgu.old-invocation.rcgu.o\08:16")
                .into();
        let mut relocations = [relocation];

        let patches = relocation_target_patches_for_input(&mut relocations, &input, &current)
            .unwrap()
            .unwrap();

        let target_input = display_hex_text(&relocations[0].target.as_ref().unwrap().input);
        assert!(target_input.contains(String::from_utf8_lossy(current_identifier).as_ref()));
        assert_eq!(patches.changed_relocation_indices, vec![0]);
        assert!(patches.macho_cross_input_target_moves.is_empty());
    }

